import { initializeApp } from "firebase/app";
import { getFirestore, collection, addDoc, getDocs, deleteDoc, doc, query, orderBy, limit, Timestamp, updateDoc, setDoc } from "firebase/firestore";
import { HistoryItem, CapitalItem, Product, Sale } from "../types";

// --- ENVIRONMENT VARIABLE HELPER ---
const getEnv = (key: string, defaultValue: string = "") => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) {
      // @ts-ignore
      const val = import.meta.env[`VITE_FIREBASE_${key}`] || import.meta.env[`NEXT_PUBLIC_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env) {
      const val = process.env[`NEXT_PUBLIC_FIREBASE_${key}`] || process.env[`REACT_APP_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  return defaultValue;
};

// --- CONFIGURATION ---
const firebaseConfig = {
  apiKey: getEnv("API_KEY"),
  authDomain: getEnv("AUTH_DOMAIN"),
  projectId: getEnv("PROJECT_ID"),
  storageBucket: getEnv("STORAGE_BUCKET"),
  messagingSenderId: getEnv("MESSAGING_SENDER_ID"),
  appId: getEnv("APP_ID"),
  measurementId: getEnv("MEASUREMENT_ID")
};

let db: any = null;
let useLocalStorage = true;

try {
  if (firebaseConfig.apiKey) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    useLocalStorage = false;
    console.log("✅ Firebase connected successfully to project:", firebaseConfig.projectId);
  } else {
    console.warn("⚠️ Firebase API Key not found in env. Using LocalStorage fallback.");
  }
} catch (error) {
  console.error("❌ Error initializing Firebase, falling back to LocalStorage", error);
  useLocalStorage = true;
}

export const getSyncStatus = () => {
    return {
        isCloud: !useLocalStorage,
        projectId: firebaseConfig.projectId || 'Local'
    };
};

const JOBS_COLLECTION = "print_jobs";
const JOBS_STORAGE_KEY = "bambuCalc_History";

const CAPITAL_COLLECTION = "capital_expenses";
const CAPITAL_STORAGE_KEY = "bambuCalc_Capital";

const PRODUCTS_COLLECTION = "products";
const PRODUCTS_STORAGE_KEY = "bambuCalc_Products";

const SALES_COLLECTION = "sales";
const SALES_STORAGE_KEY = "bambuCalc_Sales";

// --- JOBS ---

export const saveJob = async (item: Omit<HistoryItem, 'id'>): Promise<HistoryItem> => {
  if (useLocalStorage) {
    const finalItem: HistoryItem = { ...item, id: Date.now().toString() };
    const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
    existing.unshift(finalItem);
    if (existing.length > 50) existing.pop();
    localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(existing));
    return finalItem;
  } else {
    try {
      const docRef = await addDoc(collection(db, JOBS_COLLECTION), {
        ...item,
        createdAt: Timestamp.fromMillis(item.createdAt || Date.now())
      });
      return { ...item, id: docRef.id };
    } catch (e) {
      console.error("Firebase save failed, falling back to local:", e);
      const finalItem: HistoryItem = { ...item, id: Date.now().toString() };
      const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
      existing.unshift(finalItem);
      localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(existing));
      return finalItem;
    }
  }
};

export const updateJob = async (id: string, updates: Partial<HistoryItem>): Promise<void> => {
  // Always update Local Storage first (Optimistic)
  const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
  const index = existing.findIndex((j: HistoryItem) => j.id === id);
  if (index !== -1) {
    existing[index] = { ...existing[index], ...updates };
    localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(existing));
  }

  if (!useLocalStorage) {
    try {
      const docRef = doc(db, JOBS_COLLECTION, id);
      await updateDoc(docRef, updates);
    } catch (e) {
      console.error("Firebase update failed:", e);
    }
  }
};

export const getJobs = async (): Promise<HistoryItem[]> => {
  const localData = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
  if (useLocalStorage) {
    return localData;
  } else {
    try {
      const q = query(collection(db, JOBS_COLLECTION), orderBy("createdAt", "desc"), limit(50));
      const querySnapshot = await getDocs(q);
      const cloudData = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
        // Convert timestamp back to number if needed
        createdAt: doc.data().createdAt?.toMillis?.() || doc.data().createdAt || Date.now()
      })) as unknown as HistoryItem[];

      return cloudData.length > 0 ? cloudData : localData;
    } catch (e) {
      console.error("Firebase fetch failed:", e);
      return localData;
    }
  }
};

export const deleteJob = async (id: string): Promise<void> => {
  // Always delete from Local Storage first
  const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
  const filtered = existing.filter((item: HistoryItem) => item.id !== id);
  localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(filtered));

  if (!useLocalStorage) {
    try {
      await deleteDoc(doc(db, JOBS_COLLECTION, id));
    } catch (e) {
      console.error("Firebase delete failed", e);
    }
  }
};

