import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Store, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, CloudOff
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus, setSyncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<{name: string, price: number, cost: number} | null>(null);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  useEffect(() => {
    Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost, 
    inputs.wastageMultiplier,
    inputs.machineCost, 
    inputs.lifespanHours, 
    inputs.powerWatts, 
    inputs.dryerPowerWatts, 
    inputs.elecRate, 
    inputs.laborRate, 
    inputs.laborMins, 
    inputs.failMargin, 
    // Shopee Fee Triggers
    inputs.platformCommissionFee, 
    inputs.platformTransactionFee, 
    inputs.platformServiceFee, 
    inputs.platformFixedFee, 

    inputs.taxRate, 
    inputs.packagingCost, 
    inputs.shippingCost, 
    inputs.markup
  ]);

  // Sidebar persistence
  useEffect(() => {
      localStorage.setItem('bambuCalc_Sidebar', JSON.stringify(isSidebarOpen));
  }, [isSidebarOpen]);

  // --- ACTIONS: CALCULATOR ---

  const handleSaveJob = async (asCopy = false) => {
    setIsSaving(true);
    const currentResults = calculateCosts(inputs);

    // Base object
    const jobData: any = {
      name: inputs.jobName,
      inputs: { ...inputs },
      resultsSnapshot: currentResults,
      finalPrice: currentResults.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    if (editingJobId && !asCopy) {
      // Update existing
      await updateJob(editingJobId, {
        ...jobData,
        updatedAt: Date.now()
      });
      setEditingJobId(null); // Exit edit mode
    } else {
      // Create new
      await saveJob({
        ...jobData,
        date: new Date().toLocaleDateString(),
        createdAt: Date.now()
      });
    }

    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
  };

  const handleLoadJob = (job: HistoryItem) => {
    // Just load inputs, treat as new unless they explicitly clicked edit
    setInputs(job.inputs);
    setEditingJobId(null);
  };

  const handleCancel = () => {
    setEditingJobId(null);
    setInputs(mergeWithDefaults(loadSettings()));
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      setHistory(await getJobs());
      setJobToDelete(null);
    }
  };

  const handleImportToInventory = () => {
    if (!inputs.jobName) {
      alert("Please enter a Job Name first.");
      return;
    }

    // Exclude shipping from inventory cost basis usually
    const shipping = typeof inputs.shippingCost === 'number' ? inputs.shippingCost : parseFloat(inputs.shippingCost as string) || 0;
    const costBasis = Math.max(0, results.unit.totalCostBasis - shipping);

    setProductToImport({
      name: inputs.jobName,
      price: parseFloat(results.unit.finalPrice.toFixed(2)),
      cost: parseFloat(costBasis.toFixed(2))
    });
  };

  const executeImportToInventory = async () => {
    if (!productToImport) return;

    await saveProduct({
      name: productToImport.name,
      category: 'Printed', // Default category
      price: productToImport.price,
      cost: productToImport.cost,
      stock: 0,
      createdAt: Date.now()
    });
    setProducts(await getProducts());
    setProductToImport(null);
    setActiveView('products'); // Switch view to show the result
  };

  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
        const parsed = await parseGCodeFile(file);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                jobName: parsed.filename ? parsed.filename.replace(/\.(gcode|3mf|txt)$/i, '') : prev.jobName,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
        } else {
            alert('Could not extract data from file.');
        }
    } catch (e) {
        alert('Error parsing file.');
    } finally {
        setIsParsing(false);
    }
  };

  // --- ACTIONS: PRODUCTS ---
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    setProducts(await getProducts());
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    setProducts(await getProducts());
  };

  const handleDeleteProduct = (id: string) => {
    setProductToDelete(id);
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
        await deleteProduct(productToDelete);
        setProducts(await getProducts());
        setProductToDelete(null);
    }
  };

  // --- ACTIONS: POS ---
  const handleAddToCart = (item: SaleItem) => {
    setCart(prev => {
      const existing = prev.findIndex(i => i.refId === item.refId && i.type === item.type);
      if (existing !== -1) {
        const updated = [...prev];
        updated[existing].quantity += 1;
        return updated;
      }
      return [...prev, item];
    });
  };

  const handleUpdateCartQty = (index: number, delta: number) => {
    setCart(prev => {
      const updated = [...prev];
      updated[index].quantity += delta;
      if (updated[index].quantity <= 0) return prev.filter((_, i) => i !== index);
      return updated;
    });
  };

  const handleCheckout = async (method: Sale['paymentMethod']) => {
    const totalRev = cart.reduce((sum, i) => sum + (i.unitPrice * i.quantity), 0);
    const totalCost = cart.reduce((sum, i) => sum + (i.unitCost * i.quantity), 0);

    // 1. Save Sale
    await saveSale({
      items: cart,
      totalRevenue: totalRev,
      totalCost: totalCost,
      totalProfit: totalRev - totalCost,
      paymentMethod: method,
      timestamp: Date.now(),
      dateStr: new Date().toLocaleDateString()
    });

    // 2. Update Inventory Stock
    for (const item of cart) {
        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                const newStock = product.stock - item.quantity;
                await updateProduct(product.id, { stock: newStock });
            }
        }
    }

    setSales(await getSales());
    setProducts(await getProducts());
    setCart([]);
    alert('Sale Completed!');
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    setSales(await getSales());
  };

  const handleDeleteSale = (id: string) => {
    setSaleToDelete(id);
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
        await deleteSale(saleToDelete);
        setSales(await getSales());
        setSaleToDelete(null);
    }
  };

  // --- RENDER HELPERS ---
  const currency = (val: number | undefined) => {
    return '₱' + (val || 0).toLocaleString('en-US', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    });
  };

  // --- MAIN RENDER ---
  return (
    <div className="flex flex-col h-screen bg-gray-100 overflow-hidden font-sans">

      {/* 1. TOP NAVIGATION */}
      <div className="bg-slate-900 text-white h-16 flex items-center justify-between px-6 shadow-md flex-none z-50">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-1.5 rounded-lg">
             <Printer size={20} />
          </div>
          <h1 className="font-bold text-lg tracking-tight hidden sm:block">Command <span className="text-brand-500">Center</span></h1>
        </div>

        <nav className="flex bg-slate-800 rounded-lg p-1 gap-1">
          <NavButton active={activeView === 'calculator'} onClick={() => setActiveView('calculator')} icon={<Calculator size={18}/>} label="Calculator" />
          <NavButton active={activeView === 'products'} onClick={() => setActiveView('products')} icon={<PackageIcon size={18}/>} label="Inventory" />
          <NavButton active={activeView === 'pos'} onClick={() => setActiveView('pos')} icon={<Store size={18}/>} label="POS" />
          <NavButton active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} icon={<LayoutDashboard size={18}/>} label="Analytics" />
        </nav>

        <div className="flex items-center gap-4 w-32 justify-end">
           {/* Cloud Status Badge */}
           <div 
             className={clsx(
               "flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border",
               syncStatus.isCloud ? "bg-green-900/30 text-green-400 border-green-800" : "bg-gray-800 text-gray-400 border-gray-700"
             )}
             title={syncStatus.isCloud ? `Synced to project: ${syncStatus.projectId}` : "Using Local Storage"}
           >
              {syncStatus.isCloud ? <Cloud size={12} /> : <CloudOff size={12} />}
              <span className="hidden lg:inline">{syncStatus.isCloud ? "Cloud Sync" : "Local Mode"}</span>
           </div>

           {cart.length > 0 && activeView !== 'pos' && (
              <button onClick={() => setActiveView('pos')} className="relative p-2 bg-brand-600 rounded-full hover:bg-brand-500 transition-colors">
                 <ShoppingCart size={18} />
                 <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-bold">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                 </span>
              </button>
           )}
        </div>
      </div>

      {/* 2. MAIN CONTENT AREA */}
      <div className="flex-1 overflow-hidden relative">

        {/* VIEW: CALCULATOR */}
        {activeView === 'calculator' && (
           <CalculatorView 
              inputs={inputs} setInputs={setInputs} results={results} history={history}
              editingJobId={editingJobId} isSaving={isSaving} isParsing={isParsing}
              isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen}
              onLoadJob={handleLoadJob} onEditJob={handleEditJob} onSaveJob={handleSaveJob}
              onDeleteJob={(id) => setJobToDelete(id)}
              onCancel={handleCancel}
              onShowMath={() => setShowMathModal(true)} onShowDashboard={() => setActiveView('dashboard')}
              onAddToInventory={handleImportToInventory}
              handleFile={handleFile} currency={currency}
           />
        )}

        {/* VIEW: PRODUCTS */}
        {activeView === 'products' && (
           <ProductManager 
              products={products} 
              onAdd={handleAddProduct} 
              onUpdate={handleUpdateProduct}
              onDelete={handleDeleteProduct} 
              currency={currency} 
           />
        )}

        {/* VIEW: POS */}
        {activeView === 'pos' && (
           <POSInterface 
              products={products}
              jobs={history}
              cart={cart}
              currency={currency}
              onAddToCart={handleAddToCart}
              onUpdateCartQty={handleUpdateCartQty}
              onRemoveFromCart={(idx) => {
                 setCart(prev => prev.filter((_, i) => i !== idx));
              }}
              onCheckout={handleCheckout}
              onClearCart={() => setCart([])}
           />
        )}

        {/* VIEW: DASHBOARD */}
        {activeView === 'dashboard' && (
           <DashboardView 
              history={history}
              capitalHistory={capitalHistory}
              sales={sales}
              onAddCapital={async (i) => { 
                await saveCapitalItem(i); 
                // Force a refresh of the list
                const items = await getCapitalItems();
                setCapitalHistory(items); 
              }}
              onUpdateCapital={async (id, updates) => {
                await updateCapitalItem(id, updates);
                setCapitalHistory(await getCapitalItems());
              }}
              onDeleteCapital={async (id) => { 
                await deleteCapitalItem(id); 
                setCapitalHistory(await getCapitalItems()); 
              }}
              onDeleteJob={(id) => setJobToDelete(id)}
              onUpdateSale={handleUpdateSale}
              onDeleteSale={handleDeleteSale}
              currency={currency}
           />
        )}
      </div>

      <MathModal 
        isOpen={showMathModal} onClose={() => setShowMathModal(false)}
        inputs={inputs} results={results} currency={currency}
      />

      <ConfirmDialog 
        isOpen={!!jobToDelete}
        title="Delete Job History"
        message="Are you sure you want to delete this job? This action cannot be undone."
        onConfirm={confirmDeleteJob}
        onCancel={() => setJobToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!productToDelete}
        title="Delete Product"
        message="Are you sure you want to delete this product? This action cannot be undone."
        onConfirm={confirmDeleteProduct}
        onCancel={() => setProductToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!saleToDelete}
        title="Delete Sale Record"
        message="Are you sure you want to delete this sales record? This will remove it from the ledger permanently."
        onConfirm={confirmDeleteSale}
        onCancel={() => setSaleToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!productToImport}
        title="Import to Inventory"
        message={`Add "${productToImport?.name}" to Inventory?\nRecommended Price: ${currency(productToImport?.price)}\nCost Basis: ${currency(productToImport?.cost)}`}
        onConfirm={executeImportToInventory}
        onCancel={() => setProductToImport(null)}
        confirmText="Import"
        type="info"
      />

    </div>
  );
}

const NavButton = ({ active, onClick, icon, label }: any) => (
  <button 
    onClick={onClick}
    className={clsx(
      "flex items-center gap-2 px-4 py-1.5 rounded-md text-sm font-medium transition-all",
      active ? "bg-slate-700 text-white shadow-sm" : "text-slate-400 hover:text-white hover:bg-slate-700/50"
    )}
  >
    {icon} <span className="hidden md:inline">{label}</span>
  </button>
);

export default App;

import React, { useState, useCallback, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost } from '../types';
import { InputGroup } from './InputGroup';
import { SummaryChart } from './SummaryChart';
import { HistoryPanel } from './HistoryPanel';
import { 
  Upload, Box, Zap, TrendingUp, Save, Copy, 
  Edit2, History, Loader2, Trash2, Plus, LayoutDashboard, ChevronLeft, ChevronRight, PackagePlus, X, ChevronDown, ChevronUp
} from 'lucide-react';
import clsx from 'clsx';

interface CalculatorViewProps {
  inputs: CalculatorInputs;
  setInputs: React.Dispatch<React.SetStateAction<CalculatorInputs>>;
  results: CalculatedResults;
  history: HistoryItem[];
  editingJobId: string | null;
  isSaving: boolean;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (v: boolean) => void;
  onLoadJob: (job: HistoryItem) => void;
  onEditJob: (job: HistoryItem) => void;
  onDeleteJob: (id: string) => void;
  onSaveJob: (asCopy: boolean) => void;
  onCancel: () => void;
  onShowMath: () => void;
  onShowDashboard: () => void;
  onAddToInventory: () => void;
  handleFile: (file: File) => void;
  isParsing: boolean;
  currency: (val: number) => string;
}

export const CalculatorView: React.FC<CalculatorViewProps> = ({
  inputs, setInputs, results, history, editingJobId,
  isSaving, isSidebarOpen, setIsSidebarOpen,
  onLoadJob, onEditJob, onDeleteJob, onSaveJob, onCancel, onShowMath, onShowDashboard, onAddToInventory,
  handleFile, isParsing, currency
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');

  // Section Visibility State
  const [sections, setSections] = useState({
      overhead: true,
      commercial: true
  });

  // Price Editing State
  const [isEditingPrice, setIsEditingPrice] = useState(false);
  const [priceInputValue, setPriceInputValue] = useState('');

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number | boolean) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  const addExtra = () => {
    setInputs(prev => ({ ...prev, extras: [...prev.extras, { id: Date.now().toString(), name: '', price: 0 }] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => ex.id === id ? { ...ex, [field]: val } : ex)
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Reverse Calculation Handler ---
  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPriceInputValue(val);

    const numericVal = parseFloat(val);
    if (isNaN(numericVal) || numericVal < 0) return;

    // 1. Determine the Target Unit Price based on View Mode
    const qty = typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1;
    const targetUnitPrice = viewMode === 'unit' ? numericVal : numericVal / qty;

    // 2. Get Cost Basis and Fees
    const opCost = results.unit.productionCost + results.unit.packaging;
    if (opCost <= 0) return;

    const useFees = inputs.usePlatformFees !== false;
    const comm = useFees ? (typeof inputs.platformCommissionFee === 'number' ? inputs.platformCommissionFee : parseFloat(inputs.platformCommissionFee as string) || 0) : 0;
    const svc = useFees ? (typeof inputs.platformServiceFee === 'number' ? inputs.platformServiceFee : parseFloat(inputs.platformServiceFee as string) || 0) : 0;
    const trans = useFees ? (typeof inputs.platformTransactionFee === 'number' ? inputs.platformTransactionFee : parseFloat(inputs.platformTransactionFee as string) || 0) : 0;
    const fixed = useFees ? (typeof inputs.platformFixedFee === 'number' ? inputs.platformFixedFee : parseFloat(inputs.platformFixedFee as string) || 0) : 0;
    const ship = results.unit.shipping;

    const totalRate = (comm + svc + trans) / 100;

    // Deductions approx (ignoring shipping trans fee nuance for quick UI update)
    const deductions = (targetUnitPrice * totalRate) + fixed;
    const netReceive = targetUnitPrice - deductions - ship;

    const impliedProfit = netReceive - opCost;
    const newMarkup = (impliedProfit / opCost) * 100;

    setInputs(prev => ({
        ...prev,
        markup: parseFloat(newMarkup.toFixed(2))
    }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, [handleFile]);

  return (
    <div className="flex h-full relative overflow-hidden">

      {/* Sidebar - Collapsible */}
      <div 
        className={clsx(
          "bg-white border-r border-gray-200 flex flex-col transition-all duration-300 z-30 flex-none h-full",
          isSidebarOpen ? "w-72" : "w-0 overflow-hidden"
        )}
      >
        <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between flex-none">
            <h3 className="font-bold text-gray-700 text-xs flex items-center gap-2 uppercase tracking-wide">
                <History size={14} /> Recent Jobs
            </h3>
        </div>
        <div className="flex-1 overflow-y-auto py-2">
            <HistoryPanel 
                items={history} 
                onLoad={onLoadJob} 
                onEdit={onEditJob} 
                onDelete={(item) => onDeleteJob(item.id)} 
            />
        </div>
      </div>

      {/* Sidebar Toggle - Custom Design */}
      <button
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className={clsx(
            "absolute top-4 z-50 bg-white border border-gray-200 shadow-md h-8 w-6 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 transition-all duration-300 cursor-pointer border-l-0",
            isSidebarOpen ? "left-72" : "left-0"
        )}
        title={isSidebarOpen ? "Collapse History" : "Expand History"}
      >
        {isSidebarOpen ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
      </button>

      {/* Main Scrollable Content */}
      <div className="flex-1 overflow-y-auto bg-gray-50/50 p-6 md:p-8">
        <div className="max-w-[1600px] mx-auto grid grid-cols-1 xl:grid-cols-12 gap-8">

          {/* LEFT COLUMN: INPUTS */}
          <div className="xl:col-span-8 space-y-6">

            {/* File Drop Zone */}
            <div 
                className={clsx(
                    "border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer relative group flex flex-col items-center justify-center min-h-[120px]", 
                    dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 bg-white"
                )}
                onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                onClick={() => document.getElementById('fileUpload')?.click()}
            >
                <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt,.3mf" />
                <div className={clsx("p-3 rounded-full transition-colors mb-2", dragActive ? "bg-brand-100 text-brand-600" : "bg-blue-50 text-blue-500 group-hover:bg-blue-100")}>
                     {isParsing ? <Loader2 className="animate-spin" size={20} /> : <Upload size={20} />}
                </div>
                <div className="text-sm font-bold text-gray-900">Import G-Code / 3MF</div>
                <p className="text-[10px] text-gray-400">Drag file or click to analyze</p>
            </div>

            {/* SECTION 01: JOB SPECIFICATIONS */}
            <Section title="01 // Job Specifications" icon={<Box size={18} className="text-gray-400" />}>
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <InputGroup label="Job Name" placeholder="e.g. Iron Man Helmet" value={inputs.jobName} onChange={(e) => handleInputChange('jobName', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Batch Quantity" type="number" suffix="pcs" value={inputs.batchQty} onChange={(e) => handleInputChange('batchQty', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Filament Used" type="number" suffix="g" value={inputs.materialGrams} onChange={(e) => handleInputChange('materialGrams', e.target.value)} />
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                        <InputGroup label="Material Cost (1kg)" type="number" prefix="₱" value={inputs.materialCost} onChange={(e) => handleInputChange('materialCost', e.target.value)} />
                    </div>
                    <div>
                            <InputGroup label="Print Time (Hrs)" type="number" value={inputs.timeHours} onChange={(e) => handleInputChange('timeHours', e.target.value)} />
                    </div>
                    <div>
                            <InputGroup label="Print Time (Mins)" type="number" value={inputs.timeMinutes} onChange={(e) => handleInputChange('timeMinutes', e.target.value)} />
                    </div>
                </div>

                {/* Drying Time (Yellow Box) */}
                <div className="bg-orange-50/50 rounded-lg border border-orange-100 p-4">
                    <div className="flex justify-between items-center mb-3">
                        <label className="text-xs font-bold text-gray-600 uppercase tracking-wide">Drying Time</label>
                        <label className="flex items-center gap-2 cursor-pointer select-none">
                            <input 
                                type="checkbox" 
                                className="w-4 h-4 text-brand-600 rounded border-gray-300 focus:ring-brand-500"
                                checked={inputs.dryingTimeSameAsPrintTime}
                                onChange={(e) => handleInputChange('dryingTimeSameAsPrintTime', e.target.checked)}
                            />
                            <span className="text-[10px] font-bold text-brand-600 uppercase tracking-wide">Sync with Print Time</span>
                        </label>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                            <InputGroup 
                            label="" 
                            type="number" 
                            suffix="hrs" 
                            className={clsx("mb-0 bg-white", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                            value={inputs.dryingTimeSameAsPrintTime ? inputs.timeHours : inputs.dryingHours} 
                            onChange={(e) => handleInputChange('dryingHours', e.target.value)} 
                            placeholder="0"
                            />
                            <InputGroup 
                            label="" 
                            type="number" 
                            suffix="min" 
                            className={clsx("mb-0 bg-white", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                            value={inputs.dryingTimeSameAsPrintTime ? inputs.timeMinutes : inputs.dryingMinutes} 
                            onChange={(e) => handleInputChange('dryingMinutes', e.target.value)} 
                            placeholder="0"
                            />
                    </div>
                </div>

                {/* Extras */}
                <div className="bg-gray-50 rounded-lg p-4 border border-gray-200">
                    <div className="flex justify-between items-center mb-3">
                        <span className="text-xs font-bold text-gray-500 uppercase tracking-wider">Hardware & Extras</span>
                        <button onClick={addExtra} className="text-[10px] text-brand-600 font-bold hover:bg-brand-50 px-2 py-1 rounded border border-transparent hover:border-brand-200 transition-colors flex items-center gap-1">
                            <Plus size={12} /> Add Item
                        </button>
                    </div>
                    <div className="space-y-2">
                        {inputs.extras.map((extra) => (
                            <div key={extra.id} className="flex gap-3 animate-in fade-in slide-in-from-top-1 duration-200">
                                <input 
                                    className="flex-1 text-sm border-gray-300 rounded-md px-3 py-2 focus:ring-brand-500 focus:border-brand-500" 
                                    value={extra.name} 
                                    onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} 
                                    placeholder="Item name (e.g. Magnets)" 
                                />
                                <div className="relative w-32">
                                    <span className="absolute left-3 top-2 text-gray-400 text-sm">₱</span>
                                    <input 
                                        className="w-full text-sm border-gray-300 rounded-md pl-7 pr-3 py-2 focus:ring-brand-500 focus:border-brand-500" 
                                        type="number" 
                                        value={extra.price} 
                                        onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} 
                                        placeholder="0.00" 
                                    />
                                </div>
                                <button onClick={() => removeExtra(extra.id)} className="text-gray-400 hover:text-red-500 p-2 hover:bg-red-50 rounded-md transition-colors">
                                    <Trash2 size={16}/>
                                </button>
                            </div>
                        ))}
                        {inputs.extras.length === 0 && (
                            <p className="text-xs text-gray-400 italic text-center py-2">No extras added</p>
                        )}
                    </div>
                </div>
            </Section>

            {/* SECTION 02: FACTORY OVERHEAD */}
            <Section 
                title="02 // Factory Overhead" 
                icon={<Zap size={18} className="text-gray-400" />}
                isOpen={sections.overhead}
                onToggle={() => setSections(prev => ({ ...prev, overhead: !prev.overhead }))}
            >
                <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
                    <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={(e) => handleInputChange('machineCost', e.target.value)} />
                    <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={(e) => handleInputChange('lifespanHours', e.target.value)} />
                    <InputGroup label="Power Draw" suffix="W" value={inputs.powerWatts} onChange={(e) => handleInputChange('powerWatts', e.target.value)} />
                    <InputGroup label="Dryer Power" suffix="W" value={inputs.dryerPowerWatts} onChange={(e) => handleInputChange('dryerPowerWatts', e.target.value)} />

                    <InputGroup label="Elec. Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={(e) => handleInputChange('elecRate', e.target.value)} />
                    <InputGroup label="Labor Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={(e) => handleInputChange('laborRate', e.target.value)} />
                    <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={(e) => handleInputChange('laborMins', e.target.value)} />
                </div>
            </Section>

            {/* SECTION 03: COMMERCIAL */}
            <Section 
                title="03 // Commercial" 
                icon={<TrendingUp size={18} className="text-gray-400" />}
                isOpen={sections.commercial}
                onToggle={() => setSections(prev => ({ ...prev, commercial: !prev.commercial }))}
                action={
                    <div className="flex items-center gap-2" onClick={(e) => e.stopPropagation()}>
                         <label 
                            onClick={() => handleInputChange('usePlatformFees', !inputs.usePlatformFees)}
                            className="text-xs font-bold text-gray-500 uppercase tracking-wide cursor-pointer select-none hover:text-gray-700 transition-colors"
                         >
                             Platform Fees
                         </label>
                         <div 
                           className={clsx(
                               "w-8 h-4 rounded-full p-0.5 cursor-pointer transition-colors", 
                               inputs.usePlatformFees !== false ? "bg-brand-500" : "bg-gray-300"
                           )}
                           onClick={() => handleInputChange('usePlatformFees', !inputs.usePlatformFees)}
                         >
                            <div className={clsx(
                                "w-3 h-3 bg-white rounded-full shadow-sm transition-transform duration-200", 
                                inputs.usePlatformFees !== false ? "translate-x-4" : "translate-x-0"
                            )} />
                         </div>
                    </div>
                }
            >
                <div>
                    {/* Fee Grid - Conditionally Rendered */}
                    {inputs.usePlatformFees !== false && (
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4 animate-in fade-in slide-in-from-top-2 duration-300">
                            <InputGroup label="Commission %" suffix="%" value={inputs.platformCommissionFee} onChange={(e) => handleInputChange('platformCommissionFee', e.target.value)} />
                            <InputGroup label="Transaction %" suffix="%" value={inputs.platformTransactionFee} onChange={(e) => handleInputChange('platformTransactionFee', e.target.value)} />
                            <InputGroup label="Service %" suffix="%" value={inputs.platformServiceFee} onChange={(e) => handleInputChange('platformServiceFee', e.target.value)} />
                            <InputGroup label="Fixed Fee" prefix="₱" value={inputs.platformFixedFee} onChange={(e) => handleInputChange('platformFixedFee', e.target.value)} />
                        </div>
                    )}

                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                        <InputGroup label="Fail Margin" suffix="%" value={inputs.failMargin} onChange={(e) => handleInputChange('failMargin', e.target.value)} />
                        <InputGroup label="Tax Rate" suffix="%" value={inputs.taxRate} onChange={(e) => handleInputChange('taxRate', e.target.value)} />
                        <InputGroup label="Packaging" prefix="₱" value={inputs.packagingCost} onChange={(e) => handleInputChange('packagingCost', e.target.value)} />
                        <InputGroup label="Shipping" prefix="₱" value={inputs.shippingCost} onChange={(e) => handleInputChange('shippingCost', e.target.value)} />

                        <div className="col-span-2">
                             <InputGroup 
                                label="Markup Goal" suffix="%" 
                                value={inputs.markup} onChange={(e) => handleInputChange('markup', e.target.value)} 
                                className="font-bold text-brand-600 bg-brand-50 border-brand-200"
                            />
                        </div>
                    </div>
                </div>
            </Section>

          </div>

          {/* RIGHT COLUMN: HUD */}
          <div className="xl:col-span-4 space-y-6">
            <div className="sticky top-6">
                <div className="bg-slate-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-slate-800 ring-1 ring-white/10">

                    {/* Header & Toggle */}
                    <div className="p-6 pb-0">
                        <div className="flex items-center justify-between mb-6">
                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                <span className="w-2 h-2 bg-brand-500 rounded-full animate-pulse"></span>
                                Live Pricing
                            </span>
                            <div className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
