// --- ENVIRONMENT VARIABLE HELPER ---
const getEnv = (key: string, defaultValue: string = "") => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) {
      // @ts-ignore
      const val = import.meta.env[`VITE_FIREBASE_${key}`] || import.meta.env[`NEXT_PUBLIC_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  try {
    if (typeof process !== 'undefined' && process.env) {
      const val = process.env[`NEXT_PUBLIC_FIREBASE_${key}`] || process.env[`REACT_APP_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  return defaultValue;
};

// --- CONFIGURATION ---
const firebaseConfig = {
  apiKey: getEnv("API_KEY"),
  authDomain: getEnv("AUTH_DOMAIN"),
  projectId: getEnv("PROJECT_ID"),
  storageBucket: getEnv("STORAGE_BUCKET"),
  messagingSenderId: getEnv("MESSAGING_SENDER_ID"),
  appId: getEnv("APP_ID"),
  measurementId: getEnv("MEASUREMENT_ID")
};

let db: any = null;

try {
  if (firebaseConfig.apiKey) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    console.log("✅ Firebase connected successfully to project:", firebaseConfig.projectId);
  } else {
    console.error("❌ Firebase API Key missing. App will not function correctly.");
  }
} catch (error) {
  console.error("❌ Error initializing Firebase:", error);
}

