import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Package, Search, Edit2 } from 'lucide-react';
import clsx from 'clsx';

interface ProductManagerProps {
  products: Product[];
  onAdd: (p: Omit<Product, 'id'>) => Promise<void>;
  onUpdate: (id: string, p: Partial<Product>) => Promise<void>;
  onDelete: (id: string) => void;
  currency: (val: number) => string;
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onAdd, onUpdate, onDelete, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form State
  const [newName, setNewName] = useState('');
  const [newPrice, setNewPrice] = useState('');
  const [newCost, setNewCost] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategory, setNewCategory] = useState('Standard');
  const [newTaxRate, setNewTaxRate] = useState('12');

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setNewName('');
    setNewPrice('');
    setNewCost('');
    setNewStock('');
    setNewCategory('Standard');
    setNewTaxRate('12');
  };

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setNewName(p.name);
    setNewPrice(p.price.toString());
    setNewCost(p.cost.toString());
    setNewStock(p.stock.toString());
    setNewCategory(p.category);
    setNewTaxRate(p.taxRate?.toString() || '12');
    setIsAdding(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newPrice) return;

    const productData = {
      name: newName,
      price: parseFloat(newPrice),
      cost: parseFloat(newCost) || 0,
      stock: parseInt(newStock) || 0,
      category: newCategory,
      taxRate: parseFloat(newTaxRate) || 0
    };

    if (editingId) {
        await onUpdate(editingId, productData);
    } else {
        await onAdd({
            ...productData,
            createdAt: Date.now()
        });
    }

    resetForm();
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="max-w-6xl mx-auto p-6">

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Package className="text-brand-600" /> Product Inventory
           </h2>
           <p className="text-gray-500 text-sm mt-1">Manage standardized items for Point of Sale.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="bg-brand-600 hover:bg-brand-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 text-sm shadow-lg shadow-brand-500/20"
        >
          <Plus size={18} /> Add Product
        </button>
      </div>

      {/* Add/Edit Modal/Panel */}
      {isAdding && (
        <div className="mb-8 bg-white p-6 rounded-xl border border-brand-100 shadow-sm animate-in slide-in-from-top-4">
           <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide mb-4">
               {editingId ? 'Edit Product Details' : 'New Product Details'}
           </h3>
           <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
              <div className="md:col-span-2">
                 <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                 <input autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. 3D Benchy - Red" value={newName} onChange={e => setNewName(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Selling Price (VAT Inc)</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newPrice} onChange={e => setNewPrice(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Cost Basis</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newCost} onChange={e => setNewCost(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">VAT Rate %</label>
                 <input type="number" step="1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="12" value={newTaxRate} onChange={e => setNewTaxRate(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                 <input type="number" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0" value={newStock} onChange={e => setNewStock(e.target.value)} />
              </div>
              <div className="md:col-span-6 flex justify-end gap-2 mt-2">
                 <button type="button" onClick={resetForm} className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
                 <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 rounded-lg">
                     {editingId ? 'Update Item' : 'Save Item'}
                 </button>
              </div>
           </form>
        </div>
      )}

      {/* Filter */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input 
          className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
          placeholder="Search products by name..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
             <tr>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Product</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-center">Stock</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Cost</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Price (Inc)</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Profit</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
             {filtered.map(p => {
               // Profit Calculation considering VAT
               const rate = p.taxRate || 12; // Default to 12 if not set
               const netPrice = p.price / (1 + (rate/100));
               const profit = netPrice - p.cost;
               const margin = netPrice > 0 ? (profit / netPrice) * 100 : 0;

               return (
               <tr key={p.id} className={clsx("hover:bg-gray-50 group transition-all", p.stock <= 0 && "opacity-60 grayscale bg-gray-50/50")}>
                 <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{p.name}</div>
                    <div className="text-xs text-gray-500">{p.category} {rate > 0 ? `• VAT ${rate}%` : ''}</div>
                 </td>
                 <td className="px-6 py-4 text-center">
                    <span className={clsx("px-2 py-1 rounded text-xs font-bold", p.stock > 0 ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
                      {p.stock}
                    </span>
                 </td>
                 <td className="px-6 py-4 text-right text-sm text-gray-500">{currency(p.cost)}</td>
                 <td className="px-6 py-4 text-right text-sm font-bold text-gray-900">{currency(p.price)}</td>
                 <td className="px-6 py-4 text-right">
                    <div className="text-sm font-bold text-brand-600">{currency(profit)}</div>
                    <div className="text-[10px] text-gray-400">{margin.toFixed(0)}% margin</div>
                 </td>
                 <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(p)} className="text-gray-400 hover:text-brand-600 p-1.5 hover:bg-brand-50 rounded">
                           <Edit2 size={16} />
                        </button>
                        <button onClick={() => onDelete(p.id)} className="text-gray-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded">
                           <Trash2 size={16} />
                        </button>
                    </div>
                 </td>
               </tr>
             )})}
             {filtered.length === 0 && (
               <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-400">No products found.</td></tr>
             )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React from 'react';
import { X, Calculator } from 'lucide-react';
import { CalculatedResults, CalculatorInputs } from '../types';

interface MathModalProps {
  isOpen: boolean;
  onClose: () => void;
  inputs: CalculatorInputs;
  results: CalculatedResults;
  currency: (val: number) => string;
}

export const MathModal: React.FC<MathModalProps> = ({ isOpen, onClose, inputs, results, currency }) => {
  if (!isOpen) return null;

  const toNumber = (val: number | string | undefined) => parseFloat(String(val || 0));

  // Inputs
  const materialCost = toNumber(inputs.materialCost);
  const grams = toNumber(inputs.materialGrams);

  const powerWatts = toNumber(inputs.powerWatts);
  const dryerWatts = toNumber(inputs.dryerPowerWatts);
  const rate = toNumber(inputs.elecRate);
  const printHours = results.meta.printHours;
  const dryingHours = results.meta.dryingHours;

  const machineCost = toNumber(inputs.machineCost);
  const lifespan = toNumber(inputs.lifespanHours);

  const laborRate = toNumber(inputs.laborRate);
  const laborMins = toNumber(inputs.laborMins);

  const failMargin = toNumber(inputs.failMargin);

  const markup = toNumber(inputs.markup);
  const taxRate = toNumber(inputs.taxRate);

  // Fee Inputs
  const useFees = inputs.usePlatformFees !== false;
  const commRate = useFees ? toNumber(inputs.platformCommissionFee) : 0;
  const transRate = useFees ? toNumber(inputs.platformTransactionFee) : 0;
  const svcRate = useFees ? toNumber(inputs.platformServiceFee) : 0;
  const fixedFee = useFees ? toNumber(inputs.platformFixedFee) : 0;

  // Batch Values for display
  const b = results.batch;

  // Helper for OpCost
  const opCost = b.productionCost + b.packaging;
  const targetNetAsk = opCost + b.profit;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl animate-in fade-in zoom-in duration-200">

        {/* Header */}
        <div className="flex justify-between items-center px-6 py-4 border-b border-gray-100 bg-gray-50">
          <div className="flex items-center gap-2 text-brand-600">
            <Calculator size={20} />
            <h2 className="text-lg font-bold text-gray-900">Cost Breakdown (Batch)</h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-200 rounded-full transition-colors">
            <X size={20} className="text-gray-500" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto space-y-8 text-sm text-gray-700">

            {/* 1. Production Costs */}
            <Section title="A. Production Costs" total={currency(b.productionCost)}>

                <Item label="1. Material">
                    <Formula text="(Cost per kg / 1000) × Grams" />
                    <Calculation 
                        values={`(${currency(materialCost)} / 1000) × ${grams}g`} 
                        result={currency(b.material)} 
                    />
                </Item>

                <Item label="2. Energy (Printer + Dryer)">
                    <Formula text="((Watts / 1000) × Hours × Rate) + Dryer" />
                    <Calculation 
                        values={`P: (${powerWatts}W/1k × ${printHours.toFixed(2)}h × ${currency(rate)}) + D: (${dryerWatts}W/1k × ${dryingHours.toFixed(2)}h × ${currency(rate)})`} 
                        result={currency(b.energy)} 
                    />
                </Item>

                <Item label="3. Depreciation">
                    <Formula text="(Machine Cost / Lifespan) × Print Hours" />
                    <Calculation 
                        values={`(${currency(machineCost)} / ${lifespan}h) × ${printHours.toFixed(2)}h`} 
                        result={currency(b.depreciation)} 
                    />
                </Item>

                <Item label="4. Labor">
                    <Formula text="(Hourly Rate / 60) × Prep Minutes" />
                    <Calculation 
                        values={`(${currency(laborRate)} / 60) × ${laborMins}m`} 
                        result={currency(b.labor)} 
                    />
                </Item>

                <Item label="5. Extras">
                    <div className="flex justify-between items-center bg-gray-50 p-2 rounded border border-gray-100 text-xs">
                       <span>Hardware & Misc Items</span>
                       <span className="font-bold">{currency(b.extras)}</span>
                    </div>
                </Item>

                <Item label="6. Failure Margin">
                    <Formula text="(Sum of above) × Margin %" />
                    <Calculation 
                        values={`${currency(b.productionCost - b.failureRisk)} × ${failMargin}%`} 
                        result={currency(b.failureRisk)} 
                    />
                </Item>
            </Section>

            {/* 2. Commercial Costs */}
            <Section title="B. Commercial Costs (Pass-through / Ops)" total={currency(b.packaging + b.shipping)}>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <SimpleCalc label="Packaging (Ops)" formula="Cost × Qty" val={currency(b.packaging)} />
                    <SimpleCalc label="Shipping (Pass-through)" formula="Cost × Qty" val={currency(b.shipping)} />
                </div>
            </Section>

            {/* 3. Pricing Logic */}
            <Section title={useFees ? "C. Pricing Strategy (Shopee Uplift + VAT)" : "C. Pricing Strategy (Direct Sale + VAT)"}>

                 <div className="bg-blue-50/50 p-3 rounded-lg border border-blue-100 mb-4">
                     <div className="flex justify-between items-center mb-1">
                        <span className="text-xs font-bold text-blue-800">Operational Cost Base</span>
                        <span className="text-xs font-bold text-blue-800">{currency(opCost)}</span>
                     </div>
                     <p className="text-[10px] text-blue-600">Production Cost + Packaging</p>
                 </div>

                 <Item label="1. Profit Markup (On Operations Only)">
                    <Formula text="Op. Cost × Markup %" />
                    <Calculation 
                        values={`${currency(opCost)} × ${markup}%`} 
                        result={currency(b.profit)} 
                    />
                 </Item>

                 <div className="flex justify-between items-center py-2 border-t border-gray-100">
                    <span className="font-bold text-gray-600">Target Net Ask (Wallet)</span>
                    <span className="font-bold text-gray-900">{currency(targetNetAsk)}</span>
                 </div>

                 <p className="text-[10px] text-gray-400 mb-4">* The amount you want to receive before Shipping deductions.</p>

                 {useFees ? (
                    <>
                        <Item label="2. Shopee + VAT Formula">
                            <p className="text-xs text-gray-500 mb-2 leading-relaxed">
                                Calculates price required to cover <b>Fees</b> and <b>VAT ({taxRate}%)</b>. 
                                VAT is removed from the Gross Price first.
                            </p>
                            <Formula text="(Target + Fixed + Ship*Trans%) / (1/(1+VAT) - Comm% - Svc% - Trans%)" />
                            <Calculation 
                                values={`Numerator / (1/${1 + taxRate/100} - ${(commRate+svcRate+transRate)/100})`} 
                                result={currency(b.finalPrice)} 
                            />
                        </Item>

                        <div className="bg-orange-50 p-3 rounded-lg border border-orange-100 mt-2">
                            <div className="flex justify-between items-center mb-1">
                                <span className="text-xs font-bold text-orange-800">Total Deductions (Fees + Tax)</span>
                                <span className="text-xs font-bold text-orange-800">{currency(b.platformFeeAmount + b.tax)}</span>
                            </div>
                            <div className="space-y-1 mt-2 border-t border-orange-200/50 pt-2">
                                <SubFee label={`VAT (${taxRate}%)`} val={b.tax} currency={currency} />
                                <SubFee label={`Commission (${commRate}%)`} val={b.finalPrice * (commRate/100)} currency={currency} />
                                <SubFee label={`Service (${svcRate}%)`} val={b.finalPrice * (svcRate/100)} currency={currency} />
                                <SubFee label={`Transaction (${transRate}%)`} val={(b.finalPrice + b.shipping) * (transRate/100)} currency={currency} />
                                <SubFee label={`Fixed Fee`} val={fixedFee * (inputs.batchQty as number || 1)} currency={currency} />
                            </div>
                        </div>
                    </>
                 ) : (
                    <>
                         <Item label="2. Direct Sale + VAT Formula">
                            <Formula text="Target / (1 / (1 + VAT))" />
                             <Calculation 
                                values={`${currency(targetNetAsk)} / (1 / 1.${taxRate})`} 
                                result={currency(b.finalPrice)} 
                            />
                         </Item>
                         <div className="bg-green-50 p-3 rounded-lg border border-green-100 mt-2 flex justify-between items-center">
                            <span className="text-xs font-bold text-green-800">Final List Price (Inc. Tax)</span>
                            <span className="text-sm font-bold text-green-800">{currency(b.finalPrice)}</span>
                         </div>
                    </>
                 )}
            </Section>

            {/* Final */}
            <div className="bg-brand-50 border border-brand-200 p-4 rounded-xl flex justify-between items-center">
                <div>
                    <h3 className="font-bold text-brand-900">Final List Price</h3>
                    <p className="text-xs text-brand-600">{useFees ? 'Shopee listing price' : 'Direct sale price'}</p>
                </div>
                <div className="text-3xl font-black text-brand-600">{currency(b.finalPrice)}</div>
            </div>

            {/* Break Even */}
            <div className="text-center">
                 <p className="text-[10px] text-gray-400 uppercase tracking-widest">Break-Even Point</p>
                 <p className="text-xs font-bold text-gray-500">{currency(b.totalCostBasis)}</p>
                 <p className="text-[9px] text-gray-400">(Op. Costs + Shipping + Tax + {useFees ? 'Fees' : 'Overheads'})</p>
            </div>

        </div>
      </div>
    </div>
  );
};

const Section = ({ title, total, children }: any) => (
    <div className="space-y-4">
        <div className="flex justify-between items-center border-b border-gray-200 pb-2">
            <h3 className="font-bold text-gray-900 uppercase tracking-wider text-xs">{title}</h3>
            {total && <span className="font-bold text-gray-900">{total}</span>}
        </div>
        <div className="space-y-4 pl-2">
            {children}
        </div>
    </div>
);

const Item = ({ label, children }: any) => (
    <div>
        <h4 className="text-xs font-bold text-gray-700 mb-1">{label}</h4>
        {children}
    </div>
);

const SimpleCalc = ({ label, formula, val }: any) => (
    <div className="bg-gray-50 p-3 rounded border border-gray-100">
        <div className="text-xs text-gray-500 mb-1">{label}</div>
        <div className="text-[10px] text-gray-400 mb-1">{formula}</div>
        <div className="font-bold text-gray-900">{val}</div>
    </div>
);

const SubFee = ({ label, val, currency }: any) => (
    <div className="flex justify-between text-[10px] text-orange-700/80">
        <span>{label}</span>
        <span>{currency(val)}</span>
    </div>
);

const Formula = ({ text }: any) => (
    <div className="text-[10px] text-gray-400 font-mono mb-1 bg-gray-50 inline-block px-1.5 py-0.5 rounded border border-gray-100">
        {text}
    </div>
);

const Calculation = ({ values, result }: any) => (
    <div className="flex text-xs bg-blue-50/50 p-2 rounded border border-blue-100 items-center justify-between">
        <span className="font-mono text-blue-800">{values}</span>
        <span className="font-bold text-blue-700">= {result}</span>
    </div>
);

import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Store, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<{name: string, price: number, cost: number} | null>(null);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  useEffect(() => {
    Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost, 
    inputs.wastageMultiplier,
    inputs.machineCost, 
    inputs.lifespanHours, 
    inputs.powerWatts, 
    inputs.dryerPowerWatts, 
    inputs.elecRate, 
    inputs.laborRate, 
    inputs.laborMins, 
    inputs.failMargin, 
    // Shopee Fee Triggers
    inputs.platformCommissionFee, 
    inputs.platformTransactionFee, 
    inputs.platformServiceFee, 
    inputs.platformFixedFee, 

    inputs.taxRate, 
    inputs.packagingCost, 
    inputs.shippingCost, 
    inputs.markup
  ]);

  // Sidebar persistence
  useEffect(() => {
      localStorage.setItem('bambuCalc_Sidebar', JSON.stringify(isSidebarOpen));
  }, [isSidebarOpen]);

  // --- ACTIONS: CALCULATOR ---

  const handleSaveJob = async (asCopy = false) => {
    setIsSaving(true);
    const currentResults = calculateCosts(inputs);

    // Base object
    const jobData: any = {
      name: inputs.jobName,
      inputs: { ...inputs },
      resultsSnapshot: currentResults,
      finalPrice: currentResults.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    if (editingJobId && !asCopy) {
      // Update existing
      await updateJob(editingJobId, {
        ...jobData,
        updatedAt: Date.now()
      });
      setEditingJobId(null); // Exit edit mode
    } else {
      // Create new
      await saveJob({
        ...jobData,
        date: new Date().toLocaleDateString(),
        createdAt: Date.now()
      });
    }

    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
  };

  const handleLoadJob = (job: HistoryItem) => {
    // Just load inputs, treat as new unless they explicitly clicked edit
    setInputs(job.inputs);
    setEditingJobId(null);
  };

  const handleCancel = () => {
    setEditingJobId(null);
    setInputs(mergeWithDefaults(loadSettings()));
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      setHistory(await getJobs());
      setJobToDelete(null);
    }
  };

  const handleImportToInventory = () => {
    if (!inputs.jobName) {
      alert("Please enter a Job Name first.");
      return;
    }

    // Exclude shipping from inventory cost basis usually
    const shipping = typeof inputs.shippingCost === 'number' ? inputs.shippingCost : parseFloat(inputs.shippingCost as string) || 0;
    const costBasis = Math.max(0, results.unit.totalCostBasis - shipping);

    setProductToImport({
      name: inputs.jobName,
      price: parseFloat(results.unit.finalPrice.toFixed(2)),
      cost: parseFloat(costBasis.toFixed(2))
    });
  };

  const executeImportToInventory = async () => {
    if (!productToImport) return;

    await saveProduct({
      name: productToImport.name,
      category: 'Printed', // Default category
      price: productToImport.price,
      cost: productToImport.cost,
      taxRate: 12, // Default Tax
      stock: 0,
      createdAt: Date.now()
    });
    setProducts(await getProducts());
    setProductToImport(null);
    setActiveView('products'); // Switch view to show the result
  };

  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
        const parsed = await parseGCodeFile(file);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                jobName: parsed.filename ? parsed.filename.replace(/\.(gcode|3mf|txt)$/i, '') : prev.jobName,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
        } else {
            alert('Could not extract data from file.');
        }
    } catch (e) {
        alert('Error parsing file.');
    } finally {
        setIsParsing(false);
    }
  };

  // --- ACTIONS: PRODUCTS ---
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    setProducts(await getProducts());
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    setProducts(await getProducts());
  };

  const handleDeleteProduct = (id: string) => {
    setProductToDelete(id);
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
        await deleteProduct(productToDelete);
        setProducts(await getProducts());
        setProductToDelete(null);
    }
  };

  // --- ACTIONS: POS ---
  const handleAddToCart = (item: SaleItem) => {
    setCart(prev => {
      const existing = prev.findIndex(i => i.refId === item.refId && i.type === item.type);
      if (existing !== -1) {
        const updated = [...prev];
        updated[existing].quantity += 1;
        return updated;
      }
      return [...prev, item];
    });
  };

  const handleUpdateCartQty = (index: number, delta: number) => {
    setCart(prev => {
      const updated = [...prev];
      updated[index].quantity += delta;
      if (updated[index].quantity <= 0) return prev.filter((_, i) => i !== index);
      return updated;
    });
  };

  const handleCheckout = async (method: Sale['paymentMethod']) => {
    const totalRev = cart.reduce((sum, i) => sum + (i.unitPrice * i.quantity), 0);
    const totalCost = cart.reduce((sum, i) => sum + (i.unitCost * i.quantity), 0);

    // 1. Save Sale
    await saveSale({
      items: cart,
      totalRevenue: totalRev,
      totalCost: totalCost,
      totalProfit: totalRev - totalCost,
      paymentMethod: method,
      timestamp: Date.now(),
      dateStr: new Date().toLocaleDateString()
    });

    // 2. Update Inventory Stock
    for (const item of cart) {
        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                const newStock = product.stock - item.quantity;
                await updateProduct(product.id, { stock: newStock });
            }
        }
    }

    setSales(await getSales());
    setProducts(await getProducts());
    setCart([]);
    alert('Sale Completed!');
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    setSales(await getSales());
  };

  const handleDeleteSale = (id: string) => {
    setSaleToDelete(id);
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
        await deleteSale(saleToDelete);
        setSales(await getSales());
        setSaleToDelete(null);
    }
  };

  // --- RENDER HELPERS ---
  const currency = (val: number | undefined) => {
    return '₱' + (val || 0).toLocaleString('en-US', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    });
  };

  // --- MAIN RENDER ---
  return (
    <div className="flex flex-col h-screen bg-gray-100 overflow-hidden font-sans">

      {/* 1. TOP NAVIGATION */}
      <div className="bg-slate-900 text-white h-16 flex items-center justify-between px-6 shadow-md flex-none z-50">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-1.5 rounded-lg">
             <Printer size={20} />
          </div>
          <h1 className="font-bold text-lg tracking-tight hidden sm:block">Command <span className="text-brand-500">Center</span></h1>
        </div>

        <nav className="flex bg-slate-800 rounded-lg p-1 gap-1">
          <NavButton active={activeView === 'calculator'} onClick={() => setActiveView('calculator')} icon={<Calculator size={18}/>} label="Calculator" />
          <NavButton active={activeView === 'products'} onClick={() => setActiveView('products')} icon={<PackageIcon size={18}/>} label="Inventory" />
          <NavButton active={activeView === 'pos'} onClick={() => setActiveView('pos')} icon={<Store size={18}/>} label="POS" />
          <NavButton active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} icon={<LayoutDashboard size={18}/>} label="Analytics" />
        </nav>

        <div className="flex items-center gap-4 w-32 justify-end">
           {/* Cloud Status Text */}
           <div 
             className={clsx(
               "flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border",
               syncStatus.isCloud ? "bg-green-900/30 text-green-400 border-green-800" : "bg-red-900/30 text-red-400 border-red-800"
             )}
             title={`Project ID: ${syncStatus.projectId}`}
           >
              <Cloud size={12} />
              <span className="hidden lg:inline">{syncStatus.isCloud ? "Online" : "Connection Error"}</span>
           </div>

           {cart.length > 0 && activeView !== 'pos' && (
              <button onClick={() => setActiveView('pos')} className="relative p-2 bg-brand-600 rounded-full hover:bg-brand-500 transition-colors">
                 <ShoppingCart size={18} />
                 <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-bold">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                 </span>
              </button>
           )}
        </div>
      </div>

      {/* 2. MAIN CONTENT AREA */}
      <div className="flex-1 overflow-hidden relative">

        {/* VIEW: CALCULATOR */}
        {activeView === 'calculator' && (
           <CalculatorView 
              inputs={inputs} setInputs={setInputs} results={results} history={history}
              editingJobId={editingJobId} isSaving={isSaving} isParsing={isParsing}
              isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen}
              onLoadJob={handleLoadJob} onEditJob={handleEditJob} onSaveJob={handleSaveJob}
              onDeleteJob={(id) => setJobToDelete(id)}
              onCancel={handleCancel}
              onShowMath={() => setShowMathModal(true)} onShowDashboard={() => setActiveView('dashboard')}
              onAddToInventory={handleImportToInventory}
              handleFile={handleFile} currency={currency}
           />
        )}

        {/* VIEW: PRODUCTS */}
        {activeView === 'products' && (
           <ProductManager 
              products={products} 
              onAdd={handleAddProduct} 
              onUpdate={handleUpdateProduct}
              onDelete={handleDeleteProduct} 
              currency={currency} 
           />
        )}

        {/* VIEW: POS */}
        {activeView === 'pos' && (
           <POSInterface 
              products={products}
              jobs={history}
              cart={cart}
              currency={currency}
              onAddToCart={handleAddToCart}
              onUpdateCartQty={handleUpdateCartQty}
              onRemoveFromCart={(idx) => {
                 setCart(prev => prev.filter((_, i) => i !== idx));
              }}
              onCheckout={handleCheckout}
              onClearCart={() => setCart([])}
           />
        )}

        {/* VIEW: DASHBOARD */}
        {activeView === 'dashboard' && (
           <DashboardView 
              history={history}
              capitalHistory={capitalHistory}
              sales={sales}
              onAddCapital={async (i) => { 
                await saveCapitalItem(i); 
                // Force a refresh of the list
                const items = await getCapitalItems();
                setCapitalHistory(items); 
              }}
              onUpdateCapital={async (id, updates) => {
                await updateCapitalItem(id, updates);
                setCapitalHistory(await getCapitalItems());
              }}
              onDeleteCapital={async (id) => { 
                await deleteCapitalItem(id); 
                setCapitalHistory(await getCapitalItems()); 
              }}
              onDeleteJob={(id) => setJobToDelete(id)}
              onUpdateSale={handleUpdateSale}
              onDeleteSale={handleDeleteSale}
              currency={currency}
           />
        )}
      </div>

      <MathModal 
        isOpen={showMathModal} onClose={() => setShowMathModal(false)}
        inputs={inputs} results={results} currency={currency}
      />

      <ConfirmDialog 
        isOpen={!!jobToDelete}
        title="Delete Job History"
        message="Are you sure you want to delete this job? This action cannot be undone."
        onConfirm={confirmDeleteJob}
        onCancel={() => setJobToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!productToDelete}
        title="Delete Product"
        message="Are you sure you want to delete this product? This action cannot be undone."
        onConfirm={confirmDeleteProduct}
        onCancel={() => setProductToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!saleToDelete}
        title="Delete Sale Record"
        message="Are you sure you want to delete this sales record? This will remove it from the ledger permanently."
        onConfirm={confirmDeleteSale}
        onCancel={() => setSaleToDelete(null)}
        confirmText="Delete"
        type="danger"
      />

      <ConfirmDialog 
        isOpen={!!productToImport}
        title="Import to Inventory"
        message={`Add "${productToImport?.name}" to Inventory?\nRecommended Price: ${currency(productToImport?.price)}\nCost Basis: ${currency(productToImport?.cost)}`}
        onConfirm={executeImportToInventory}
        onCancel={() => setProductToImport(null)}
        confirmText="Import"
        type="info"
      />

    </div>
  );
}

const NavButton = ({ active, onClick, icon, label }: any) => (
  <button 
    onClick={onClick}
    className={clsx(
      "flex items-center gap-2 px-4 py-1.5 rounded-md text-sm font-medium transition-all",
      active ? "bg-slate-700 text-white shadow-sm" : "text-slate-400 hover:text-white hover:bg-slate-700/50"
    )}
  >
    {icon} <span className="hidden md:inline">{label}</span>
  </button>
);

export default App;

