                        <div className="mb-4">
                            <label className="block text-xs font-bold text-gray-500 mb-1">Remarks / Receipt Link</label>
                            <input className="w-full text-sm border-gray-300 rounded-lg p-2.5 mb-2" placeholder="http://..." value={newExpense.receiptLink || ''} onChange={e => setNewExpense({...newExpense, receiptLink: e.target.value})} />
                            <textarea className="w-full text-sm border-gray-300 rounded-lg p-2.5" rows={2} placeholder="Additional notes..." value={newExpense.remarks || ''} onChange={e => setNewExpense({...newExpense, remarks: e.target.value})} />
                        </div>

                        <div className="flex justify-end gap-2 pt-4 border-t border-gray-100">
                            <button type="button" onClick={closeExpenseModal} className="px-4 py-2 text-sm text-gray-600 font-medium hover:bg-gray-200 rounded-lg">Cancel</button>
                            <button type="submit" className="px-6 py-2 text-sm bg-brand-600 text-white font-bold hover:bg-brand-700 rounded-lg">
                                {editingExpenseId ? 'Update Expense' : 'Add Expense'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Package, Search, Edit2 } from 'lucide-react';
import clsx from 'clsx';

interface ProductManagerProps {
  products: Product[];
  onAdd: (p: Omit<Product, 'id'>) => Promise<void>;
  onUpdate: (id: string, p: Partial<Product>) => Promise<void>;
  onDelete: (id: string) => void;
  currency: (val: number) => string;
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onAdd, onUpdate, onDelete, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form State
  const [newName, setNewName] = useState('');
  const [newPrice, setNewPrice] = useState('');
  const [newCost, setNewCost] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategory, setNewCategory] = useState('Standard');
  const [newTaxRate, setNewTaxRate] = useState('12');

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setNewName('');
    setNewPrice('');
    setNewCost('');
    setNewStock('');
    setNewCategory('Standard');
    setNewTaxRate('12');
  };

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setNewName(p.name);
    setNewPrice(p.price.toString());
    setNewCost(p.cost.toString());
    setNewStock(p.stock.toString());
    setNewCategory(p.category);
    setNewTaxRate(p.taxRate?.toString() || '12');
    setIsAdding(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newPrice) return;

    const productData = {
      name: newName,
      price: parseFloat(newPrice),
      cost: parseFloat(newCost) || 0,
      stock: parseInt(newStock) || 0,
      category: newCategory,
      taxRate: parseFloat(newTaxRate) || 0
    };

    if (editingId) {
        await onUpdate(editingId, productData);
    } else {
        await onAdd({
            ...productData,
            createdAt: Date.now()
        });
    }

    resetForm();
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  // Live calculation for form
  const formPrice = parseFloat(newPrice) || 0;
  const formCost = parseFloat(newCost) || 0;
  const formTax = parseFloat(newTaxRate) || 0;
  const formNet = formPrice / (1 + (formTax/100));
  const formProfit = formNet - formCost;
  const formMargin = formNet > 0 ? (formProfit/formNet)*100 : 0;

  return (
    <div className="max-w-6xl mx-auto p-6">

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Package className="text-brand-600" /> Product Inventory
           </h2>
           <p className="text-gray-500 text-sm mt-1">Manage standardized items for Point of Sale.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="bg-brand-600 hover:bg-brand-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 text-sm shadow-lg shadow-brand-500/20"
        >
          <Plus size={18} /> Add Product
        </button>
      </div>

      {/* Add/Edit Modal/Panel */}
      {isAdding && (
        <div className="mb-8 bg-white p-6 rounded-xl border border-brand-100 shadow-sm animate-in slide-in-from-top-4">
           <div className="flex justify-between items-start mb-4">
               <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide">
                   {editingId ? 'Edit Product Details' : 'New Product Details'}
               </h3>
               {/* Live Profit Preview */}
               <div className="bg-gray-50 rounded px-3 py-1 text-right border border-gray-100">
                   <div className="text-[10px] text-gray-500 uppercase">Projected Profit</div>
                   <div className="text-sm font-bold text-brand-600">{currency(formProfit)} ({formMargin.toFixed(0)}%)</div>
               </div>
           </div>

           <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
              <div className="md:col-span-2">
                 <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                 <input autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. 3D Benchy - Red" value={newName} onChange={e => setNewName(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Selling Price (VAT Inc)</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newPrice} onChange={e => setNewPrice(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Cost Basis</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newCost} onChange={e => setNewCost(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">VAT Rate %</label>
                 <input type="number" step="1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="12" value={newTaxRate} onChange={e => setNewTaxRate(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                 <input type="number" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0" value={newStock} onChange={e => setNewStock(e.target.value)} />
              </div>
              <div className="md:col-span-6 flex justify-end gap-2 mt-2">
                 <button type="button" onClick={resetForm} className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
                 <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 rounded-lg">
                     {editingId ? 'Update Item' : 'Save Item'}
                 </button>
              </div>
           </form>
        </div>
      )}

      {/* Filter */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input 
          className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
          placeholder="Search products by name..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
             <tr>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Product</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-center">Stock</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Cost</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Price (Inc)</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Profit</th>
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
             {filtered.map(p => {
               // Profit Calculation considering VAT
               const rate = p.taxRate || 12; // Default to 12 if not set
               const netPrice = p.price / (1 + (rate/100));
               const profit = netPrice - p.cost;
               const margin = netPrice > 0 ? (profit / netPrice) * 100 : 0;

               return (
               <tr key={p.id} className={clsx("hover:bg-gray-50 group transition-all", p.stock <= 0 && "opacity-60 grayscale bg-gray-50/50")}>
                 <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{p.name}</div>
                    <div className="text-xs text-gray-500">{p.category} {rate > 0 ? `• VAT ${rate}%` : ''}</div>
                 </td>
                 <td className="px-6 py-4 text-center">
                    <span className={clsx("px-2 py-1 rounded text-xs font-bold", p.stock > 0 ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
                      {p.stock}
                    </span>
                 </td>
                 <td className="px-6 py-4 text-right text-sm text-gray-500">{currency(p.cost)}</td>
                 <td className="px-6 py-4 text-right text-sm font-bold text-gray-900">{currency(p.price)}</td>
                 <td className="px-6 py-4 text-right">
                    <div className="text-sm font-bold text-brand-600">{currency(profit)}</div>
                    <div className="text-[10px] text-gray-400">{margin.toFixed(0)}% margin</div>
                 </td>
                 <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(p)} className="text-gray-400 hover:text-brand-600 p-1.5 hover:bg-brand-50 rounded">
                           <Edit2 size={16} />
                        </button>
                        <button onClick={() => onDelete(p.id)} className="text-gray-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded">
                           <Trash2 size={16} />
                        </button>
                    </div>
                 </td>
               </tr>
             )})}
             {filtered.length === 0 && (
               <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-400">No products found.</td></tr>
             )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Sale } from '../types';
import { Download, TrendingUp, DollarSign, Wallet, ShoppingCart, Edit2, X, Trash2, Plus, Calendar, User, Truck, Tag, Link as LinkIcon, Store } from 'lucide-react';
import clsx from 'clsx';

interface DashboardViewProps {
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => Promise<void>;
  onUpdateCapital: (id: string, updates: Partial<CapitalItem>) => Promise<void>;
  onDeleteCapital: (id: string) => void;
  onUpdateSale: (id: string, updates: Partial<Sale>) => Promise<void>;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

export const DashboardView: React.FC<DashboardViewProps> = ({ 
  history, capitalHistory, sales,
  onDeleteJob, onAddCapital, onUpdateCapital, onDeleteCapital, onUpdateSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = React.useState<'sales' | 'expenses'>('sales');

  // Sale Edit State
  const [editingSale, setEditingSale] = useState<Sale | null>(null);

  // Expense Add/Edit State
  const [isAddingExpense, setIsAddingExpense] = useState(false);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);

  const DEFAULT_EXPENSE = {
      name: '',
      category: 'Parts',
      platform: 'Shopee',
      store: '',
      purchaseDate: new Date().toISOString().split('T')[0],
      dateReceived: '',
      orderedBy: 'BB',
      paidBy: 'BB',
      receiptLink: '',
      remarks: '',
      quantity: 1,
      unitPrice: ''
  };

  const [newExpense, setNewExpense] = useState<{
      name: string;
      category: string;
      platform: string;
      store: string;
      purchaseDate: string;
      dateReceived?: string;
      orderedBy: string;
      paidBy: string;
      receiptLink?: string;
      remarks?: string;
      quantity: number | '';
      unitPrice: string;
  }>(DEFAULT_EXPENSE);

  // Calculate aggregates
  const stats = useMemo(() => {
    // 1. Sales Revenue (Realized)
    let totalSalesRev = 0;
    let totalSalesProfit = 0;
    let totalTaxCollected = 0;

    sales.forEach(s => {
      totalSalesRev += s.totalRevenue;
      totalSalesProfit += s.totalProfit;

      // Calculate tax portion for stats
      // Note: This is an estimation based on stored items if available, or we could add a field to Sale.
      // For now, let's re-derive it from items.
      if (s.items) {
          s.items.forEach(i => {
              const rate = i.taxRate || 0;
              const netPrice = i.unitPrice / (1 + (rate/100));
              totalTaxCollected += (i.unitPrice - netPrice) * i.quantity;
          });
      }
    });

    // 2. Potential Value (Saved Jobs)
    let potentialRev = 0;
    history.forEach(job => {
       potentialRev += job.finalPrice || 0;
    });

    // 3. Capital
    const totalCapital = capitalHistory.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalSalesProfit - totalCapital;

    return { totalSalesRev, totalSalesProfit, totalCapital, netPosition, potentialRev, totalTaxCollected };
  }, [history, capitalHistory, sales]);

  const downloadCSV = () => {
      let content = "";
      let filename = "";

      if (activeTab === 'sales') {
        const headers = ['Date', 'Type', 'Total', 'VAT', 'Profit', 'Payment'];
        const rows = sales.map(s => {
            let tax = 0;
            s.items.forEach(i => {
                const rate = i.taxRate || 0;
                const net = i.unitPrice / (1 + (rate/100));
                tax += (i.unitPrice - net) * i.quantity;
            });
            return [
                s.dateStr, 
                'Sale', 
                s.totalRevenue.toFixed(2), 
                tax.toFixed(2), 
                s.totalProfit.toFixed(2), 
                s.paymentMethod
            ].join(',');
        });
        content = [headers.join(','), ...rows].join('\n');
        filename = 'sales_ledger.csv';
      } else {
        const headers = ['Purchase Date', 'Item', 'Qty', 'Category', 'Total Price', 'Store', 'Platform', 'Ordered By', 'Paid By'];
        const rows = capitalHistory.map(c => [
            c.purchaseDate, c.name, c.quantity || 1, c.category, c.price.toFixed(2), c.store, c.platform, c.orderedBy, c.paidBy
        ].join(','));
        content = [headers.join(','), ...rows].join('\n');
        filename = 'capital_expenses.csv';
      }

      const csvContent = "data:text/csv;charset=utf-8," + encodeURI(content);
      const link = document.createElement("a");
      link.setAttribute("href", csvContent);
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleSaveSaleEdit = async () => {
      if (!editingSale) return;
      const newProfit = editingSale.totalRevenue - editingSale.totalCost; // Simplified logic, assumes cost doesn't change
      await onUpdateSale(editingSale.id, {
          dateStr: editingSale.dateStr,
          paymentMethod: editingSale.paymentMethod,
          totalRevenue: editingSale.totalRevenue,
          totalProfit: newProfit
      });
      setEditingSale(null);
  };

  const handleEditExpense = (item: CapitalItem) => {
      setNewExpense({
          name: item.name,
          category: item.category,
          platform: item.platform || '',
          store: item.store || '',
          purchaseDate: item.purchaseDate,
          dateReceived: item.dateReceived || '',
          orderedBy: item.orderedBy || 'BB',
          paidBy: item.paidBy || 'BB',
          receiptLink: item.receiptLink || '',
          remarks: item.remarks || '',
          quantity: item.quantity || 1,
          unitPrice: item.quantity > 0 ? (item.price / item.quantity).toFixed(2) : item.price.toFixed(2)
      });
      setEditingExpenseId(item.id);
      setIsAddingExpense(true);
  };

  const closeExpenseModal = () => {
      setIsAddingExpense(false);
      setEditingExpenseId(null);
      setNewExpense(DEFAULT_EXPENSE);
  };

  const handleSaveExpense = async (e: React.FormEvent) => {
      e.preventDefault();

      const qty = Number(newExpense.quantity) || 1;
      const unit = parseFloat(newExpense.unitPrice) || 0;
      const total = unit * qty;

      if (!newExpense.name || total <= 0) {
          alert("Please enter a valid Name and Price.");
          return;
      }

      const expenseData = {
          name: newExpense.name,
          price: total,
          quantity: qty,
          category: newExpense.category as any,
          platform: newExpense.platform || '',
          store: newExpense.store || '',
          purchaseDate: newExpense.purchaseDate || new Date().toLocaleDateString(),
          // FIX: Convert undefined to null for Firebase compatibility
          dateReceived: newExpense.dateReceived || null,
          orderedBy: newExpense.orderedBy || 'BB',
          paidBy: newExpense.paidBy || 'BB',
          receiptLink: newExpense.receiptLink || null,
          remarks: newExpense.remarks || null,
      };

      try {
        if (editingExpenseId) {
            await onUpdateCapital(editingExpenseId, expenseData);
        } else {
            await onAddCapital({
                ...expenseData,
                createdAt: Date.now()
            });
        }
        closeExpenseModal();
      } catch (err) {
        alert("Failed to save expense. Please try again.");
        console.error(err);
      }
  };

  return (
    <div className="flex flex-col h-full bg-gray-50 overflow-hidden relative">

        {/* Stats Overview */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 flex-none">
            <StatsCard 
              icon={<DollarSign size={20} />} 
              label="Realized Revenue" 
              value={currency(stats.totalSalesRev)} 
              subValue={`${currency(stats.totalTaxCollected)} VAT included`}
              color="text-blue-600" bg="bg-blue-50" 
            />
             <StatsCard 
              icon={<TrendingUp size={20} />} 
              label="Net Profit" 
              value={currency(stats.totalSalesProfit)} 
              color="text-green-600" bg="bg-green-50" 
            />
             <StatsCard 
              icon={<ShoppingCart size={20} />} 
              label="Capital Expenses" 
              value={currency(stats.totalCapital)} 
              color="text-orange-600" bg="bg-orange-50" 
            />
            <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex items-center gap-3">
                <div className={clsx("p-2 rounded-lg", stats.netPosition >= 0 ? "bg-brand-50 text-brand-600" : "bg-red-50 text-red-600")}>
                    <Wallet size={20} />
                </div>
                <div>
                    <p className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Net Position</p>
                    <p className={clsx("text-xl font-bold", stats.netPosition >= 0 ? "text-brand-600" : "text-red-600")}>
                      {stats.netPosition < 0 ? '-' : '+'}{currency(Math.abs(stats.netPosition))}
                    </p>
                </div>
            </div>
        </div>

        {/* Tab Navigation */}
        <div className="px-6 border-b border-gray-200 bg-white flex items-center justify-between flex-none">
          <div className="flex gap-6">
            <TabButton active={activeTab === 'sales'} onClick={() => setActiveTab('sales')} label="Sales Ledger" />
            <TabButton active={activeTab === 'expenses'} onClick={() => setActiveTab('expenses')} label="Capital Expenses" />
          </div>
          <div className="flex items-center gap-2">
            {activeTab === 'expenses' && (
                <button 
                    onClick={() => { closeExpenseModal(); setIsAddingExpense(true); }}
                    className="text-xs font-bold bg-brand-600 text-white px-3 py-1.5 rounded-lg hover:bg-brand-700 flex items-center gap-1 shadow-sm"
                >
                    <Plus size={14} /> Add Expense
                </button>
            )}
            <button onClick={downloadCSV} className="text-xs font-bold text-gray-500 hover:text-brand-600 flex items-center gap-1 px-3 py-1.5 rounded-lg hover:bg-gray-50">
                <Download size={14} /> Export
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-auto p-6">

             {/* SALES LEDGER TABLE */}
             {activeTab === 'sales' && (
                <table className="w-full text-left border-collapse bg-white rounded-xl shadow-sm overflow-hidden">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Date</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Items</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Method</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Total</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">VAT</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Profit</th>
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {sales.map((sale) => {
                            // Calculate Sales Tax for display row
                            const tax = sale.items.reduce((acc, i) => {
                                const rate = i.taxRate || 0;
                                const net = i.unitPrice / (1 + (rate/100));
                                return acc + ((i.unitPrice - net) * i.quantity);
                            }, 0);

                            return (
                            <tr key={sale.id} className="hover:bg-gray-50 transition-colors group">
                                <td className="px-6 py-3 text-sm text-gray-500 whitespace-nowrap">{sale.dateStr}</td>
                                <td className="px-6 py-3 text-sm text-gray-900">
                                <div className="flex flex-col">
                                    {sale.items.map((i, idx) => (
                                    <span key={idx} className="text-xs text-gray-600">{i.quantity}x {i.name}</span>
                                    ))}
                                </div>
                                </td>
                                <td className="px-6 py-3 text-sm text-gray-500 capitalize">{sale.paymentMethod}</td>
                                <td className="px-6 py-3 text-sm text-gray-900 font-bold text-right">{currency(sale.totalRevenue)}</td>
                                <td className="px-6 py-3 text-sm text-gray-400 text-right">{currency(tax)}</td>
                                <td className="px-6 py-3 text-sm text-green-600 font-bold text-right">{currency(sale.totalProfit)}</td>
                                <td className="px-6 py-3 text-right">
                                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                        <button onClick={() => setEditingSale(sale)} className="p-1.5 text-gray-400 hover:text-brand-600 hover:bg-brand-50 rounded">
                                            <Edit2 size={16} />
                                        </button>
                                        <button onClick={() => onDeleteSale(sale.id)} className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        )})}
                        {sales.length === 0 && <tr><td colSpan={7} className="text-center py-12 text-gray-400">No sales recorded yet.</td></tr>}
                    </tbody>
                </table>
             )}

             {/* CAPITAL EXPENSES TABLE */}
             {activeTab === 'expenses' && (
                <table className="w-full text-left border-collapse bg-white rounded-xl shadow-sm overflow-hidden">
