const Section = ({ title, icon, children, isOpen = true, onToggle, action }: any) => {
    return (
        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
            <div 
                className={clsx(
                    "px-6 py-4 border-b border-gray-100 bg-gray-50/50 flex items-center justify-between cursor-pointer hover:bg-gray-100 transition-colors",
                    !isOpen && "border-b-0"
                )}
                onClick={onToggle}
            >
                <div className="flex items-center gap-2">
                    {icon}
                    <h2 className="text-xs font-bold text-gray-700 uppercase tracking-widest">{title}</h2>
                </div>
                <div className="flex items-center gap-3">
                    {action}
                    {onToggle && (
                        <div className="text-gray-400">
                            {isOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                        </div>
                    )}
                </div>
            </div>

            {isOpen && (
                <div className="p-6 space-y-6 animate-in slide-in-from-top-2 duration-200">
                    {children}
                </div>
            )}
        </section>
    );
};

const LineItem = ({ label, value, color, currency }: { label: string, value: number, color: string, currency: (val: number) => string }) => (
    <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
            <div className={clsx("w-2 h-2 rounded-full", color)}></div>
            <span className="text-xs font-bold text-slate-400">{label}</span>
        </div>
        <span className="text-xs font-bold text-white">{currency(value)}</span>
    </div>
);

const SubItem = ({ label, value, currency, color }: { label: string, value: number, currency: (val: number) => string, color?: string }) => (
    <div className={clsx("flex justify-between items-center text-[10px] font-medium", color || "text-slate-500")}>
        <span>{label}</span>
        <span>{currency(value)}</span>
    </div>
);

import React from 'react';
import { HistoryItem } from '../types';
import { Edit2, Trash2 } from 'lucide-react';

interface HistoryPanelProps {
  items: HistoryItem[];
  onLoad: (item: HistoryItem) => void;
  onEdit: (item: HistoryItem) => void;
  onDelete: (item: HistoryItem) => void;
}

export const HistoryPanel: React.FC<HistoryPanelProps> = ({ items, onLoad, onEdit, onDelete }) => {
  if (!items || items.length === 0) {
    return (
      <div className="text-center py-6 mx-4 border-2 border-dashed border-gray-200 rounded-xl">
        <p className="text-gray-400 text-xs">No history yet.</p>
      </div>
    );
  }

  return (
    <div className="space-y-2 px-2">
        {items.map((job) => (
            <div 
                key={job.id}
                className="group flex flex-col p-3 bg-white border border-gray-200 rounded-lg hover:border-brand-500 hover:shadow-md transition-all relative"
            >
                <div 
                  className="cursor-pointer"
                  onClick={() => onLoad(job)}
                >
                  <div className="flex justify-between items-start mb-1">
                      <h4 className="font-semibold text-gray-800 text-xs truncate max-w-[120px]" title={job.name}>{job.name || 'Untitled'}</h4>
                      <span className="text-[10px] text-gray-400">{job.date}</span>
                  </div>

                  {job.inputs.notes && (
                      <p className="text-[10px] text-gray-400 italic truncate mb-2">{job.inputs.notes}</p>
                  )}

                  <div className="flex justify-between items-end">
                      <span className="text-[10px] text-gray-500 bg-gray-100 px-1.5 py-0.5 rounded">{job.inputs.batchQty} pcs</span>
                      <div className="text-right">
                          <div className="text-brand-600 font-bold text-xs">
                              ₱{(job.finalPrice || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })}
                          </div>
                      </div>
                  </div>
                </div>

                <div className="absolute right-2 bottom-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1 bg-white pl-2 shadow-sm rounded">
                   <button 
                      onClick={(e) => { e.stopPropagation(); onEdit(job); }}
                      className="p-1 bg-gray-100 hover:bg-brand-50 hover:text-brand-600 text-gray-500 rounded-md border border-gray-200"
                      title="Edit Job"
                   >
                     <Edit2 size={12} />
                   </button>
                   <button 
                      onClick={(e) => { e.stopPropagation(); onDelete(job); }}
                      className="p-1 bg-gray-100 hover:bg-red-50 hover:text-red-600 text-gray-500 rounded-md border border-gray-200"
                      title="Delete Job"
                   >
                     <Trash2 size={12} />
                   </button>
                </div>
            </div>
        ))}
    </div>
  );
};

