import React, { useState, useMemo } from 'react';
import { HistoryItem } from '../types';
import { Edit2, Trash2, Search, Filter, CheckCircle, Circle, ArrowUpDown } from 'lucide-react';
import clsx from 'clsx';

interface HistoryPanelProps {
  items: HistoryItem[];
  onLoad: (item: HistoryItem) => void;
  onEdit: (item: HistoryItem) => void;
  onDelete: (item: HistoryItem) => void;
  onToggleStatus: (item: HistoryItem) => void;
}

type SortOption = 'date_desc' | 'date_asc' | 'price_desc' | 'price_asc' | 'name';
type FilterStatus = 'all' | 'pending' | 'completed';

export const HistoryPanel: React.FC<HistoryPanelProps> = ({ items, onLoad, onEdit, onDelete, onToggleStatus }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortOption, setSortOption] = useState<SortOption>('date_desc');
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [showFilters, setShowFilters] = useState(false);

  const filteredItems = useMemo(() => {
    let result = [...items];

    // 1. Search
    if (searchTerm) {
        const lower = searchTerm.toLowerCase();
        result = result.filter(i => 
            i.name.toLowerCase().includes(lower) || 
            i.inputs.notes?.toLowerCase().includes(lower) ||
            i.date.includes(lower)
        );
    }

    // 2. Filter
    if (filterStatus !== 'all') {
        result = result.filter(i => (i.status || 'pending') === filterStatus);
    }

    // 3. Sort
    result.sort((a, b) => {
        switch (sortOption) {
            case 'date_asc': 
                return (a.createdAt || 0) - (b.createdAt || 0);
            case 'date_desc': 
                return (b.createdAt || 0) - (a.createdAt || 0);
            case 'price_desc': 
                return b.finalPrice - a.finalPrice;
            case 'price_asc': 
                return a.finalPrice - b.finalPrice;
            case 'name': 
                return a.name.localeCompare(b.name);
            default: return 0;
        }
    });

    return result;
  }, [items, searchTerm, sortOption, filterStatus]);

  if (!items || items.length === 0) {
    return (
      <div className="text-center py-6 mx-4 border-2 border-dashed border-gray-200 rounded-xl">
        <p className="text-gray-400 text-xs">No history yet.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
        {/* Controls */}
        <div className="px-4 pb-2 space-y-2 border-b border-gray-100 mb-2">
            <div className="relative">
                <Search className="absolute left-2.5 top-2 text-gray-400" size={14} />
                <input 
                    className="w-full pl-8 pr-3 py-1.5 text-xs border border-gray-200 rounded-lg focus:ring-brand-500 focus:border-brand-500"
                    placeholder="Search jobs..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
                <button 
                    onClick={() => setShowFilters(!showFilters)}
                    className={clsx(
                        "absolute right-1 top-1 p-1 rounded hover:bg-gray-100 transition-colors",
                        showFilters ? "text-brand-600 bg-brand-50" : "text-gray-400"
                    )}
                >
                    <Filter size={14} />
                </button>
            </div>

            {showFilters && (
                <div className="grid grid-cols-2 gap-2 animate-in slide-in-from-top-1">
                    <select 
                        className="text-xs border border-gray-200 rounded px-2 py-1 bg-white"
                        value={sortOption}
                        onChange={(e) => setSortOption(e.target.value as SortOption)}
                    >
                        <option value="date_desc">Newest First</option>
                        <option value="date_asc">Oldest First</option>
                        <option value="price_desc">Highest Price</option>
                        <option value="price_asc">Lowest Price</option>
                        <option value="name">Name (A-Z)</option>
                    </select>
                    <select 
                        className="text-xs border border-gray-200 rounded px-2 py-1 bg-white"
                        value={filterStatus}
                        onChange={(e) => setFilterStatus(e.target.value as FilterStatus)}
                    >
                        <option value="all">All Status</option>
                        <option value="pending">Pending</option>
                        <option value="completed">Completed</option>
                    </select>
                </div>
            )}
        </div>

        {/* List */}
        <div className="space-y-2 px-2 overflow-y-auto flex-1">
            {filteredItems.map((job) => {
                const isCompleted = job.status === 'completed';
                return (
                <div 
                    key={job.id}
                    className={clsx(
                        "group flex flex-col p-3 border rounded-lg transition-all relative",
                        isCompleted ? "bg-gray-50 border-gray-200" : "bg-white border-gray-200 hover:border-brand-500 hover:shadow-md"
                    )}
                >
                    <div 
                        className="cursor-pointer"
                        onClick={() => onLoad(job)}
                    >
                        <div className="flex justify-between items-start mb-1">
                            <h4 className={clsx("font-semibold text-xs truncate max-w-[120px]", isCompleted ? "text-gray-500 line-through" : "text-gray-800")} title={job.name}>
                                {job.name || 'Untitled'}
                            </h4>
                            <span className="text-[10px] text-gray-400">{job.date}</span>
                        </div>

                        {job.inputs.notes && (
                            <p className="text-[10px] text-gray-400 italic truncate mb-2">{job.inputs.notes}</p>
                        )}

                        <div className="flex justify-between items-end">
                            <span className="text-[10px] text-gray-500 bg-gray-100 px-1.5 py-0.5 rounded">{job.inputs.batchQty} pcs</span>
                            <div className="text-right">
                                <div className={clsx("font-bold text-xs", isCompleted ? "text-gray-400" : "text-brand-600")}>
                                    ₱{(job.finalPrice || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Action Bar */}
                    <div className="absolute right-2 bottom-2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-1 bg-white/80 backdrop-blur pl-2 shadow-sm rounded border border-gray-100">
                        <button 
                            onClick={(e) => { e.stopPropagation(); onToggleStatus(job); }}
                            className={clsx(
                                "p-1 rounded-md border transition-colors",
                                isCompleted ? "bg-green-50 text-green-600 border-green-200" : "bg-gray-100 text-gray-400 border-gray-200 hover:text-green-600 hover:border-green-300"
                            )}
                            title={isCompleted ? "Mark Pending" : "Mark Completed"}
                        >
                            {isCompleted ? <CheckCircle size={12} /> : <Circle size={12} />}
                        </button>
                        <button 
                            onClick={(e) => { e.stopPropagation(); onEdit(job); }}
                            className="p-1 bg-gray-100 hover:bg-brand-50 hover:text-brand-600 text-gray-500 rounded-md border border-gray-200"
                            title="Edit Job"
                        >
                            <Edit2 size={12} />
                        </button>
                        <button 
                            onClick={(e) => { e.stopPropagation(); onDelete(job); }}
                            className="p-1 bg-gray-100 hover:bg-red-50 hover:text-red-600 text-gray-500 rounded-md border border-gray-200"
                            title="Delete Job"
                        >
                            <Trash2 size={12} />
                        </button>
                    </div>
                </div>
            )})}

            {filteredItems.length === 0 && (
                <div className="text-center py-4 text-xs text-gray-400">
                    No matching jobs.
                </div>
            )}
        </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Package, Search, Edit2, ArrowUp, ArrowDown } from 'lucide-react';
import clsx from 'clsx';

interface ProductManagerProps {
  products: Product[];
  onAdd: (p: Omit<Product, 'id'>) => Promise<void>;
  onUpdate: (id: string, p: Partial<Product>) => Promise<void>;
  onDelete: (id: string) => void;
  currency: (val: number) => string;
}

type SortKey = 'name' | 'stock' | 'cost' | 'price' | 'profit';
interface SortConfig {
    key: SortKey;
    direction: 'asc' | 'desc';
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onAdd, onUpdate, onDelete, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'asc' });

  // Form State
  const [newName, setNewName] = useState('');
  const [newPrice, setNewPrice] = useState('');
  const [newCost, setNewCost] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategory, setNewCategory] = useState('Standard');
  const [newTaxRate, setNewTaxRate] = useState('12');

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setNewName('');
    setNewPrice('');
    setNewCost('');
    setNewStock('');
    setNewCategory('Standard');
    setNewTaxRate('12');
  };

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setNewName(p.name);
    setNewPrice(p.price.toString());
    setNewCost(p.cost.toString());
    setNewStock(p.stock.toString());
    setNewCategory(p.category);
    setNewTaxRate(p.taxRate !== undefined ? p.taxRate.toString() : '12');
    setIsAdding(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newPrice) return;

    const productData = {
      name: newName,
      price: parseFloat(newPrice),
      cost: parseFloat(newCost) || 0,
      stock: parseInt(newStock) || 0,
      category: newCategory,
      taxRate: parseFloat(newTaxRate) || 0
    };

    if (editingId) {
        await onUpdate(editingId, productData);
    } else {
        await onAdd({
            ...productData,
            createdAt: Date.now()
        });
    }

    resetForm();
  };

  const handleSort = (key: SortKey) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  const processedProducts = useMemo(() => {
    let result = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

    result.sort((a, b) => {
        const rateA = (a.taxRate !== undefined) ? a.taxRate : 0;
        const netPriceA = a.price / (1 + (rateA/100));
        const profitA = netPriceA - a.cost;

        const rateB = (b.taxRate !== undefined) ? b.taxRate : 0;
        const netPriceB = b.price / (1 + (rateB/100));
        const profitB = netPriceB - b.cost;

        let valA: any = a[sortConfig.key as keyof Product];
        let valB: any = b[sortConfig.key as keyof Product];

        // Handle computed keys
        if (sortConfig.key === 'profit') {
            valA = profitA;
            valB = profitB;
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });

    return result;
  }, [products, searchTerm, sortConfig]);

  // Live calculation for form
  const formPrice = parseFloat(newPrice) || 0;
  const formCost = parseFloat(newCost) || 0;
  const formTax = parseFloat(newTaxRate) || 0;
  const formNet = formPrice / (1 + (formTax/100));
  const formProfit = formNet - formCost;
  const formMargin = formNet > 0 ? (formProfit/formNet)*100 : 0;

  const SortHeader = ({ label, sKey, align = 'left' }: { label: string, sKey: SortKey, align?: string }) => (
      <th 
        className={`px-6 py-3 text-xs font-bold text-gray-500 uppercase cursor-pointer hover:text-brand-600 hover:bg-gray-100 transition-colors text-${align}`}
        onClick={() => handleSort(sKey)}
      >
          <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
            {label}
            {sortConfig.key === sKey && (
                sortConfig.direction === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>
            )}
          </div>
      </th>
  );

  return (
    <div className="max-w-6xl mx-auto p-6">

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Package className="text-brand-600" /> Product Inventory
           </h2>
           <p className="text-gray-500 text-sm mt-1">Manage standardized items for Point of Sale.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="bg-brand-600 hover:bg-brand-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 text-sm shadow-lg shadow-brand-500/20"
        >
          <Plus size={18} /> Add Product
        </button>
      </div>

      {/* Add/Edit Modal/Panel */}
      {isAdding && (
        <div className="mb-8 bg-white p-6 rounded-xl border border-brand-100 shadow-sm animate-in slide-in-from-top-4">
           <div className="flex justify-between items-start mb-4">
               <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide">
                   {editingId ? 'Edit Product Details' : 'New Product Details'}
               </h3>
               {/* Live Profit Preview */}
               <div className="bg-gray-50 rounded px-3 py-1 text-right border border-gray-100">
                   <div className="text-[10px] text-gray-500 uppercase">Projected Profit</div>
                   <div className="text-sm font-bold text-brand-600">{currency(formProfit)} ({formMargin.toFixed(0)}%)</div>
               </div>
           </div>

           <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
              <div className="md:col-span-2">
                 <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                 <input autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. 3D Benchy - Red" value={newName} onChange={e => setNewName(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Selling Price (VAT Inc)</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newPrice} onChange={e => setNewPrice(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Cost Basis</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newCost} onChange={e => setNewCost(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">VAT Rate %</label>
                 <input type="number" step="0.1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="12" value={newTaxRate} onChange={e => setNewTaxRate(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                 <input type="number" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0" value={newStock} onChange={e => setNewStock(e.target.value)} />
              </div>
              <div className="md:col-span-6 flex justify-end gap-2 mt-2">
                 <button type="button" onClick={resetForm} className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
                 <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 rounded-lg">
                     {editingId ? 'Update Item' : 'Save Item'}
                 </button>
              </div>
           </form>
        </div>
      )}

      {/* Filter */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input 
          className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
          placeholder="Search products by name..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
             <tr>
               <SortHeader label="Product" sKey="name" />
               <SortHeader label="Stock" sKey="stock" align="center" />
               <SortHeader label="Cost" sKey="cost" align="right" />
               <SortHeader label="Price (Inc)" sKey="price" align="right" />
               <SortHeader label="Profit" sKey="profit" align="right" />
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
             {processedProducts.map(p => {
               const rate = (p.taxRate !== undefined && p.taxRate !== null) ? p.taxRate : 0;
               const netPrice = p.price / (1 + (rate/100));
               const profit = netPrice - p.cost;
               const margin = netPrice > 0 ? (profit / netPrice) * 100 : 0;

               return (
               <tr key={p.id} className={clsx("hover:bg-gray-50 group transition-all", p.stock <= 0 && "opacity-60 grayscale bg-gray-50/50")}>
                 <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{p.name}</div>
                    <div className="text-xs text-gray-500">{p.category} {rate > 0 ? `• VAT ${rate}%` : ''}</div>
                 </td>
                 <td className="px-6 py-4 text-center">
                    <span className={clsx("px-2 py-1 rounded text-xs font-bold", p.stock > 0 ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
                      {p.stock}
                    </span>
                 </td>
                 <td className="px-6 py-4 text-right text-sm text-gray-500">{currency(p.cost)}</td>
                 <td className="px-6 py-4 text-right text-sm font-bold text-gray-900">{currency(p.price)}</td>
                 <td className="px-6 py-4 text-right">
                    <div className="text-sm font-bold text-brand-600">{currency(profit)}</div>
                    <div className="text-[10px] text-gray-400">{margin.toFixed(0)}% margin</div>
                 </td>
                 <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(p)} className="text-gray-400 hover:text-brand-600 p-1.5 hover:bg-brand-50 rounded">
                           <Edit2 size={16} />
                        </button>
                        <button onClick={() => onDelete(p.id)} className="text-gray-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded">
                           <Trash2 size={16} />
                        </button>
                    </div>
                 </td>
               </tr>
             )})}
             {processedProducts.length === 0 && (
               <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-400">No products found.</td></tr>
             )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Sale } from '../types';
import { Download, TrendingUp, DollarSign, Wallet, ShoppingCart, Edit2, X, Trash2, Plus, Calendar, User, Truck, Tag, Link as LinkIcon, Store, Search, ArrowUp, ArrowDown } from 'lucide-react';
import clsx from 'clsx';

interface DashboardViewProps {
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => Promise<void>;
  onUpdateCapital: (id: string, updates: Partial<CapitalItem>) => Promise<void>;
  onDeleteCapital: (id: string) => void;
  onUpdateSale: (id: string, updates: Partial<Sale>) => Promise<void>;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

interface SortConfig {
    key: string;
    direction: 'asc' | 'desc';
}

export const DashboardView: React.FC<DashboardViewProps> = ({ 
  history, capitalHistory, sales,
  onDeleteJob, onAddCapital, onUpdateCapital, onDeleteCapital, onUpdateSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = React.useState<'sales' | 'expenses'>('sales');

  // Sale Edit State
  const [editingSale, setEditingSale] = useState<Sale | null>(null);

  // Sorting & Searching State
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'date', direction: 'desc' });

  // Expense Add/Edit State
  const [isAddingExpense, setIsAddingExpense] = useState(false);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);

  const DEFAULT_EXPENSE = {
      name: '',
      category: 'Parts',
      platform: 'Shopee',
      store: '',
      purchaseDate: new Date().toISOString().split('T')[0],
      dateReceived: '',
      orderedBy: 'BB',
      paidBy: 'BB',
      receiptLink: '',
      remarks: '',
      quantity: 1,
      unitPrice: ''
  };

  const [newExpense, setNewExpense] = useState<{
      name: string;
      category: string;
      platform: string;
      store: string;
      purchaseDate: string;
      dateReceived?: string;
      orderedBy: string;
      paidBy: string;
      receiptLink?: string;
      remarks?: string;
      quantity: number | '';
      unitPrice: string;
  }>(DEFAULT_EXPENSE);

  // Calculate aggregates
  const stats = useMemo(() => {
    // 1. Sales Revenue (Realized)
    let totalSalesRev = 0;
    let totalSalesProfit = 0;
    let totalTaxCollected = 0;

    sales.forEach(s => {
      totalSalesRev += s.totalRevenue;
      totalSalesProfit += s.totalProfit;

      // Calculate tax portion for stats
      if (s.items) {
          s.items.forEach(i => {
              const rate = i.taxRate || 0;
              const netPrice = i.unitPrice / (1 + (rate/100));
              totalTaxCollected += (i.unitPrice - netPrice) * i.quantity;
          });
      }
    });

    // 2. Potential Value (Saved Jobs)
    let potentialRev = 0;
    history.forEach(job => {
       potentialRev += job.finalPrice || 0;
    });

    // 3. Capital
    const totalCapital = capitalHistory.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalSalesProfit - totalCapital;

    return { totalSalesRev, totalSalesProfit, totalCapital, netPosition, potentialRev, totalTaxCollected };
  }, [history, capitalHistory, sales]);

  // Handle Sort
  const handleSort = (key: string) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  // Filter and Sort Sales
  const processedSales = useMemo(() => {
      let result = [...sales];
      if (searchTerm) {
          const lower = searchTerm.toLowerCase();
          result = result.filter(s => 
              s.dateStr.toLowerCase().includes(lower) || 
              s.paymentMethod.toLowerCase().includes(lower) || 
              s.items.some(i => i.name.toLowerCase().includes(lower))
          );
      }
      result.sort((a, b) => {
          let valA: any = a[sortConfig.key as keyof Sale];
          let valB: any = b[sortConfig.key as keyof Sale];

          // Special Keys
          if (sortConfig.key === 'date') {
              valA = a.timestamp;
              valB = b.timestamp;
          }

          if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
          if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
          return 0;
      });
      return result;
  }, [sales, searchTerm, sortConfig]);

  // Filter and Sort Expenses
  const processedExpenses = useMemo(() => {
    let result = [...capitalHistory];
    if (searchTerm) {
        const lower = searchTerm.toLowerCase();
        result = result.filter(e => 
            e.name.toLowerCase().includes(lower) ||
            e.store.toLowerCase().includes(lower) ||
            e.platform.toLowerCase().includes(lower) || 
            e.category.toLowerCase().includes(lower)
        );
    }
    result.sort((a, b) => {
        let valA: any = a[sortConfig.key as keyof CapitalItem];
        let valB: any = b[sortConfig.key as keyof CapitalItem];

        // Special Keys
        if (sortConfig.key === 'date') {
            valA = new Date(a.purchaseDate).getTime();
            valB = new Date(b.purchaseDate).getTime();
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });
    return result;
  }, [capitalHistory, searchTerm, sortConfig]);


  const downloadCSV = () => {
      let content = "";
      let filename = "";

      if (activeTab === 'sales') {
        const headers = ['Date', 'Type', 'Total', 'VAT', 'Profit', 'Payment'];
        const rows = processedSales.map(s => {
            let tax = 0;
            s.items.forEach(i => {
                const rate = i.taxRate || 0;
                const net = i.unitPrice / (1 + (rate/100));
                tax += (i.unitPrice - net) * i.quantity;
            });
            return [
                s.dateStr, 
                'Sale', 
                s.totalRevenue.toFixed(2), 
                tax.toFixed(2), 
                s.totalProfit.toFixed(2), 
                s.paymentMethod
            ].join(',');
        });
        content = [headers.join(','), ...rows].join('\n');
        filename = 'sales_ledger.csv';
      } else {
        const headers = ['Purchase Date', 'Item', 'Qty', 'Category', 'Total Price', 'Store', 'Platform', 'Ordered By', 'Paid By'];
        const rows = processedExpenses.map(c => [
            c.purchaseDate, c.name, c.quantity || 1, c.category, c.price.toFixed(2), c.store, c.platform, c.orderedBy, c.paidBy
        ].join(','));
        content = [headers.join(','), ...rows].join('\n');
        filename = 'capital_expenses.csv';
      }

      const csvContent = "data:text/csv;charset=utf-8," + encodeURI(content);
      const link = document.createElement("a");
      link.setAttribute("href", csvContent);
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleSaveSaleEdit = async () => {
      if (!editingSale) return;
      const newProfit = editingSale.totalRevenue - editingSale.totalCost; // Simplified logic, assumes cost doesn't change
      await onUpdateSale(editingSale.id, {
          dateStr: editingSale.dateStr,
          paymentMethod: editingSale.paymentMethod,
          totalRevenue: editingSale.totalRevenue,
          totalProfit: newProfit
      });
      setEditingSale(null);
  };

  const handleEditExpense = (item: CapitalItem) => {
      setNewExpense({
          name: item.name,
          category: item.category,
          platform: item.platform || '',
          store: item.store || '',
          purchaseDate: item.purchaseDate,
          dateReceived: item.dateReceived || '',
          orderedBy: item.orderedBy || 'BB',
          paidBy: item.paidBy || 'BB',
          receiptLink: item.receiptLink || '',
          remarks: item.remarks || '',
          quantity: item.quantity || 1,
          unitPrice: item.quantity > 0 ? (item.price / item.quantity).toFixed(2) : item.price.toFixed(2)
      });
      setEditingExpenseId(item.id);
      setIsAddingExpense(true);
  };

  const closeExpenseModal = () => {
      setIsAddingExpense(false);
      setEditingExpenseId(null);
      setNewExpense(DEFAULT_EXPENSE);
  };

  const handleSaveExpense = async (e: React.FormEvent) => {
      e.preventDefault();

      const qty = Number(newExpense.quantity) || 1;
      const unit = parseFloat(newExpense.unitPrice) || 0;
      const total = unit * qty;

      if (!newExpense.name || total <= 0) {
          alert("Please enter a valid Name and Price.");
          return;
      }

      const expenseData = {
          name: newExpense.name,
          price: total,
          quantity: qty,
          category: newExpense.category as any,
          platform: newExpense.platform || '',
          store: newExpense.store || '',
          purchaseDate: newExpense.purchaseDate || new Date().toLocaleDateString(),
          dateReceived: newExpense.dateReceived || null,
          orderedBy: newExpense.orderedBy || 'BB',
          paidBy: newExpense.paidBy || 'BB',
          receiptLink: newExpense.receiptLink || null,
          remarks: newExpense.remarks || null,
      };

      try {
        if (editingExpenseId) {
            await onUpdateCapital(editingExpenseId, expenseData);
        } else {
            await onAddCapital({
                ...expenseData,
                createdAt: Date.now()
            });
        }
        closeExpenseModal();
      } catch (err) {
        alert("Failed to save expense. Please try again.");
        console.error(err);
      }
  };

  const SortHeader = ({ label, sKey, align = 'left' }: { label: string, sKey: string, align?: string }) => (
      <th 
        className={`px-6 py-3 text-xs font-bold text-gray-500 uppercase cursor-pointer hover:text-brand-600 hover:bg-gray-100 transition-colors text-${align}`}
        onClick={() => handleSort(sKey)}
      >
          <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
            {label}
            {sortConfig.key === sKey && (
                sortConfig.direction === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>
            )}
          </div>
      </th>
  );

  return (
    <div className="flex flex-col h-full bg-gray-50 overflow-hidden relative">

        {/* Stats Overview */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 flex-none">
            <StatsCard 
              icon={<DollarSign size={20} />} 
              label="Realized Revenue" 
              value={currency(stats.totalSalesRev)} 
              subValue={`${currency(stats.totalTaxCollected)} VAT included`}
              color="text-blue-600" bg="bg-blue-50" 
            />
             <StatsCard 
              icon={<TrendingUp size={20} />} 
              label="Net Profit" 
              value={currency(stats.totalSalesProfit)} 
              color="text-green-600" bg="bg-green-50" 
            />
             <StatsCard 
              icon={<ShoppingCart size={20} />} 
              label="Capital Expenses" 
              value={currency(stats.totalCapital)} 
              color="text-orange-600" bg="bg-orange-50" 
            />
            <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex items-center gap-3">
                <div className={clsx("p-2 rounded-lg", stats.netPosition >= 0 ? "bg-brand-50 text-brand-600" : "bg-red-50 text-red-600")}>
                    <Wallet size={20} />
                </div>
                <div>
                    <p className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Net Position</p>
                    <p className={clsx("text-xl font-bold", stats.netPosition >= 0 ? "text-brand-600" : "text-red-600")}>
                      {stats.netPosition < 0 ? '-' : '+'}{currency(Math.abs(stats.netPosition))}
                    </p>
                </div>
            </div>
        </div>

        {/* Tab Navigation */}
        <div className="px-6 border-b border-gray-200 bg-white flex flex-col md:flex-row md:items-center justify-between flex-none gap-4 pb-0 pt-4 md:py-0">
          <div className="flex gap-6">
            <TabButton active={activeTab === 'sales'} onClick={() => { setActiveTab('sales'); setSearchTerm(''); }} label="Sales Ledger" />
            <TabButton active={activeTab === 'expenses'} onClick={() => { setActiveTab('expenses'); setSearchTerm(''); }} label="Capital Expenses" />
          </div>
          <div className="flex items-center gap-2 pb-3 md:pb-0">
             <div className="relative">
                <Search className="absolute left-2.5 top-2.5 text-gray-400" size={14} />
                <input 
                    className="pl-8 pr-3 py-1.5 text-xs border border-gray-200 rounded-lg focus:ring-brand-500 focus:border-brand-500 w-48"
                    placeholder="Search..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            {activeTab === 'expenses' && (
                <button 
                    onClick={() => { closeExpenseModal(); setIsAddingExpense(true); }}
                    className="text-xs font-bold bg-brand-600 text-white px-3 py-1.5 rounded-lg hover:bg-brand-700 flex items-center gap-1 shadow-sm whitespace-nowrap"
                >
                    <Plus size={14} /> Add
                </button>
            )}
            <button onClick={downloadCSV} className="text-xs font-bold text-gray-500 hover:text-brand-600 flex items-center gap-1 px-3 py-1.5 rounded-lg hover:bg-gray-50">
                <Download size={14} /> Export
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-auto p-6">

             {/* SALES LEDGER TABLE */}
             {activeTab === 'sales' && (
                <table className="w-full text-left border-collapse bg-white rounded-xl shadow-sm overflow-hidden">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <SortHeader label="Date" sKey="date" />
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Items</th>
                            <SortHeader label="Method" sKey="paymentMethod" />
                            <SortHeader label="Total" sKey="totalRevenue" align="right" />
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">VAT</th>
                            <SortHeader label="Profit" sKey="totalProfit" align="right" />
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Action</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {processedSales.map((sale) => {
                            // Calculate Sales Tax for display row
                            const tax = sale.items.reduce((acc, i) => {
                                const rate = i.taxRate || 0;
                                const net = i.unitPrice / (1 + (rate/100));
                                return acc + ((i.unitPrice - net) * i.quantity);
                            }, 0);

                            return (
                            <tr key={sale.id} className="hover:bg-gray-50 transition-colors group">
                                <td className="px-6 py-3 text-sm text-gray-500 whitespace-nowrap">{sale.dateStr}</td>
                                <td className="px-6 py-3 text-sm text-gray-900">
                                <div className="flex flex-col">
                                    {sale.items.map((i, idx) => (
                                    <span key={idx} className="text-xs text-gray-600">{i.quantity}x {i.name}</span>
                                    ))}
                                </div>
                                </td>
                                <td className="px-6 py-3 text-sm text-gray-500 capitalize">{sale.paymentMethod}</td>
                                <td className="px-6 py-3 text-sm text-gray-900 font-bold text-right">{currency(sale.totalRevenue)}</td>
                                <td className="px-6 py-3 text-sm text-gray-400 text-right">{currency(tax)}</td>
                                <td className="px-6 py-3 text-sm text-green-600 font-bold text-right">{currency(sale.totalProfit)}</td>
                                <td className="px-6 py-3 text-right">
                                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                        <button onClick={() => setEditingSale(sale)} className="p-1.5 text-gray-400 hover:text-brand-600 hover:bg-brand-50 rounded">
                                            <Edit2 size={16} />
                                        </button>
                                        <button onClick={() => onDeleteSale(sale.id)} className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        )})}
                        {processedSales.length === 0 && <tr><td colSpan={7} className="text-center py-12 text-gray-400">No sales recorded matching criteria.</td></tr>}
                    </tbody>
                </table>
             )}

             {/* CAPITAL EXPENSES TABLE */}
             {activeTab === 'expenses' && (
                <table className="w-full text-left border-collapse bg-white rounded-xl shadow-sm overflow-hidden">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <SortHeader label="Item Details" sKey="name" />
                            <SortHeader label="Source" sKey="store" />
                            <SortHeader label="Logistics" sKey="date" />
                            <SortHeader label="Personnel" sKey="paidBy" />
                            <SortHeader label="Amount" sKey="price" align="right" />
                            <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {processedExpenses.map((item) => (
                            <tr key={item.id} className="hover:bg-gray-50 transition-colors group">
                                <td className="px-6 py-3">
                                    <div className="flex flex-col">
                                        <div className="font-bold text-gray-900 text-sm">
                                            {item.quantity && item.quantity > 1 && <span className="text-gray-500 mr-1">{item.quantity}x</span>}
                                            {item.name}
                                        </div>
                                        <div className="flex items-center gap-2 mt-1">
                                            <span className={clsx(
                                                "text-[10px] px-1.5 py-0.5 rounded font-bold uppercase",
                                                item.category === 'Filament' && "bg-blue-100 text-blue-700",
                                                item.category === 'Printer' && "bg-purple-100 text-purple-700",
                                                item.category === 'Parts' && "bg-orange-100 text-orange-700",
                                                item.category === 'Other' && "bg-gray-100 text-gray-700"
                                            )}>
                                                {item.category}
                                            </span>
                                            {item.remarks && <span className="text-xs text-gray-400 italic truncate max-w-[150px]">{item.remarks}</span>}
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-3">
                                    <div className="flex flex-col gap-1">
                                        <div className="flex items-center gap-1 text-xs font-semibold text-gray-700">
                                            <Tag size={12} className="text-gray-400" /> {item.platform || '—'}
                                        </div>
                                        <div className="flex items-center gap-1 text-xs text-gray-500">
                                            <Store size={12} className="text-gray-400" /> {item.store || '—'}
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-3">
                                    <div className="flex flex-col gap-1">
                                        <div className="flex items-center gap-1 text-xs text-gray-600" title="Ordered">
                                            <Calendar size={12} className="text-gray-400" /> 
                                            {/* Legacy data support: item.date might exist instead of purchaseDate */}
                                            {item.purchaseDate || (item as any).date}
                                        </div>
                                        {item.dateReceived && (
                                            <div className="flex items-center gap-1 text-xs text-green-600 font-medium" title="Received">
                                                <Truck size={12} /> {item.dateReceived}
                                            </div>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-3">
                                    <div className="flex gap-2">
                                        <div className="flex flex-col items-center">
                                            <span className="text-[10px] text-gray-400 uppercase">Ord</span>
                                            <span className="bg-gray-100 text-gray-600 text-xs font-bold px-1.5 rounded">{item.orderedBy || '-'}</span>
                                        </div>
                                        <div className="flex flex-col items-center">
                                            <span className="text-[10px] text-gray-400 uppercase">Paid</span>
                                            <span className="bg-gray-100 text-gray-600 text-xs font-bold px-1.5 rounded">{item.paidBy || '-'}</span>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-3 text-right">
                                    <div className="font-bold text-gray-900 text-sm">{currency(item.price)}</div>
                                    {item.quantity > 1 && <div className="text-[10px] text-gray-400">@{currency(item.price/item.quantity)}/ea</div>}
                                    {item.receiptLink && (
                                        <a href={item.receiptLink} target="_blank" rel="noopener noreferrer" className="text-[10px] text-brand-600 hover:underline flex items-center justify-end gap-1">
                                            <LinkIcon size={10} /> Receipt
                                        </a>
                                    )}
                                </td>
                                <td className="px-6 py-3 text-right">
                                    <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-all">
                                        <button 
                                            onClick={() => handleEditExpense(item)}
                                            className="p-1.5 text-gray-400 hover:text-brand-600 hover:bg-brand-50 rounded"
                                        >
                                            <Edit2 size={16} />
                                        </button>
                                        <button 
                                            onClick={() => onDeleteCapital(item.id)} 
                                            className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded"
                                        >
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                        {processedExpenses.length === 0 && <tr><td colSpan={6} className="text-center py-12 text-gray-400">No expenses recorded matching criteria.</td></tr>}
                    </tbody>
                </table>
             )}
        </div>

        {/* ... (Modals remain unchanged, just referencing context closing) */}
        {/* Edit Sale Modal */}
        {editingSale && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-white rounded-xl shadow-xl w-full max-w-sm overflow-hidden">
                    <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="font-bold text-gray-900">Edit Transaction</h3>
                        <button onClick={() => setEditingSale(null)} className="text-gray-400 hover:text-gray-600"><X size={20}/></button>
                    </div>
                    <div className="p-6 space-y-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">Date</label>
                            <input 
                                type="text" 
                                className="w-full text-sm border-gray-300 rounded-lg p-2.5"
                                value={editingSale.dateStr}
                                onChange={(e) => setEditingSale({...editingSale, dateStr: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">Payment Method</label>
                            <select 
                                className="w-full text-sm border-gray-300 rounded-lg p-2.5"
                                value={editingSale.paymentMethod}
                                // @ts-ignore
                                onChange={(e) => setEditingSale({...editingSale, paymentMethod: e.target.value})}
                            >
                                <option value="cash">Cash</option>
                                <option value="gcash">GCash</option>
                                <option value="card">Card</option>
                                <option value="other">Other</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-bold text-gray-500 mb-1">Total Revenue (Adjustment)</label>
                            <input 
                                type="number" 
                                className="w-full text-sm border-gray-300 rounded-lg p-2.5 font-bold"
                                value={editingSale.totalRevenue}
                                onChange={(e) => setEditingSale({...editingSale, totalRevenue: parseFloat(e.target.value) || 0})}
                            />
                            <p className="text-[10px] text-orange-500 mt-1">Warning: Changing revenue affects calculated profit.</p>
                        </div>
                    </div>
                    <div className="bg-gray-50 p-4 border-t border-gray-100 flex justify-end gap-2">
                        <button onClick={() => setEditingSale(null)} className="px-4 py-2 text-sm text-gray-600 font-medium hover:bg-gray-200 rounded-lg">Cancel</button>
                        <button onClick={handleSaveSaleEdit} className="px-4 py-2 text-sm bg-brand-600 text-white font-bold hover:bg-brand-700 rounded-lg">Save Changes</button>
                    </div>
                </div>
            </div>
        )}

        {/* Add/Edit Expense Modal */}
        {isAddingExpense && (
            <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
                <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl overflow-hidden flex flex-col max-h-[90vh]">
                    <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="font-bold text-gray-900 flex items-center gap-2">
                            <ShoppingCart size={18} className="text-brand-600"/> 
                            {editingExpenseId ? 'Edit Capital Expense' : 'Add Capital Expense'}
                        </h3>
                        <button onClick={closeExpenseModal} className="text-gray-400 hover:text-gray-600"><X size={20}/></button>
                    </div>
                    <form onSubmit={handleSaveExpense} className="overflow-y-auto p-6">
                        <div className="grid grid-cols-2 gap-4 mb-4">
                            <div className="col-span-2 md:col-span-1">
                                <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                                <input required autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. Bambu Lab X1C" value={newExpense.name} onChange={e => setNewExpense({...newExpense, name: e.target.value})} />
                            </div>
                            <div className="col-span-2 md:col-span-1">
                                <div className="grid grid-cols-2 gap-2">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">Qty</label>
                                        <input type="number" min="1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="1" value={newExpense.quantity} onChange={e => setNewExpense({...newExpense, quantity: e.target.value === '' ? '' : parseInt(e.target.value)})} />
                                    </div>
                                    <div className="relative">
                                        <label className="block text-xs font-bold text-gray-500 mb-1">Unit Price</label>
                                        <div className="relative">
                                            <span className="absolute left-3 top-2.5 text-gray-400 text-sm">₱</span>
                                            <input required type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg pl-7 pr-3 py-2.5 focus:ring-brand-500" placeholder="0.00" value={newExpense.unitPrice} onChange={e => setNewExpense({...newExpense, unitPrice: e.target.value})} />
                                        </div>
                                    </div>
                                </div>
                                <div className="text-[10px] text-right text-gray-400 mt-1">
                                    Total: {currency((parseFloat(newExpense.unitPrice)||0) * (Number(newExpense.quantity)||1))}
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-3 gap-4 mb-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Category</label>
                                <select className="w-full text-sm border-gray-300 rounded-lg p-2.5" value={newExpense.category} onChange={e => setNewExpense({...newExpense, category: e.target.value as any})}>
                                    <option value="Printer">Printer</option>
                                    <option value="Filament">Filament</option>
                                    <option value="Parts">Parts</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Platform</label>
                                <input className="w-full text-sm border-gray-300 rounded-lg p-2.5" placeholder="e.g. Shopee" value={newExpense.platform} onChange={e => setNewExpense({...newExpense, platform: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Store Name</label>
                                <input className="w-full text-sm border-gray-300 rounded-lg p-2.5" placeholder="e.g. Makerlab" value={newExpense.store} onChange={e => setNewExpense({...newExpense, store: e.target.value})} />
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mb-4 bg-gray-50 p-4 rounded-lg border border-gray-100">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Purchase Date</label>
                                <input type="date" className="w-full text-sm border-gray-300 rounded-lg p-2.5" value={newExpense.purchaseDate} onChange={e => setNewExpense({...newExpense, purchaseDate: e.target.value})} />
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Date Received (Optional)</label>
                                <input type="date" className="w-full text-sm border-gray-300 rounded-lg p-2.5" value={newExpense.dateReceived || ''} onChange={e => setNewExpense({...newExpense, dateReceived: e.target.value})} />
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mb-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Ordered By</label>
                                <select className="w-full text-sm border-gray-300 rounded-lg p-2.5" value={newExpense.orderedBy} onChange={e => setNewExpense({...newExpense, orderedBy: e.target.value})}>
                                    <option value="BB">BB</option>
                                    <option value="RB">RB</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Paid By</label>
                                <select className="w-full text-sm border-gray-300 rounded-lg p-2.5" value={newExpense.paidBy} onChange={e => setNewExpense({...newExpense, paidBy: e.target.value})}>
                                    <option value="BB">BB</option>
                                    <option value="RB">RB</option>
                                    <option value="Shared">Shared</option>
                                </select>
                            </div>
                        </div>

                        <div className="mb-4">
                            <label className="block text-xs font-bold text-gray-500 mb-1">Remarks / Receipt Link</label>
                            <input className="w-full text-sm border-gray-300 rounded-lg p-2.5 mb-2" placeholder="http://..." value={newExpense.receiptLink || ''} onChange={e => setNewExpense({...newExpense, receiptLink: e.target.value})} />
                            <textarea className="w-full text-sm border-gray-300 rounded-lg p-2.5" rows={2} placeholder="Additional notes..." value={newExpense.remarks || ''} onChange={e => setNewExpense({...newExpense, remarks: e.target.value})} />
                        </div>

                        <div className="flex justify-end gap-2 pt-4 border-t border-gray-100">
                            <button type="button" onClick={closeExpenseModal} className="px-4 py-2 text-sm text-gray-600 font-medium hover:bg-gray-200 rounded-lg">Cancel</button>
                            <button type="submit" className="px-6 py-2 text-sm bg-brand-600 text-white font-bold hover:bg-brand-700 rounded-lg">
                                {editingExpenseId ? 'Update Expense' : 'Add Expense'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Store, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, Settings, Download, Upload, Loader2, X
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<{name: string, price: number, cost: number, taxRate: number} | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  const refreshAllData = async () => {
    return Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  };

  useEffect(() => {
    refreshAllData();
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost, 
    inputs.wastageMultiplier,
    inputs.machineCost, 
    inputs.lifespanHours, 
    inputs.powerWatts, 
    inputs.dryerPowerWatts, 
    inputs.elecRate, 
    inputs.laborRate, 
    inputs.laborMins, 
    inputs.failMargin, 
    // Shopee Fee Triggers
    inputs.platformCommissionFee, 
    inputs.platformTransactionFee, 
    inputs.platformServiceFee, 
    inputs.platformFixedFee, 

    inputs.taxRate, 
    inputs.packagingCost, 
    inputs.shippingCost, 
    inputs.markup
  ]);

  // Sidebar persistence
  useEffect(() => {
      localStorage.setItem('bambuCalc_Sidebar', JSON.stringify(isSidebarOpen));
  }, [isSidebarOpen]);

  // --- ACTIONS: CALCULATOR ---

  const handleSaveJob = async (asCopy = false) => {
    setIsSaving(true);
    const currentResults = calculateCosts(inputs);

    // Base object
    const jobData: any = {
      name: inputs.jobName,
      inputs: { ...inputs },
      resultsSnapshot: currentResults,
      finalPrice: currentResults.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1),
      status: 'pending' // Default status for new/updated jobs if not specified, though logic below preserves it
    };

    if (editingJobId && !asCopy) {
      // Preserve existing status if editing
      const existing = history.find(h => h.id === editingJobId);
      if (existing) jobData.status = existing.status || 'pending';

      await updateJob(editingJobId, {
        ...jobData,
        updatedAt: Date.now()
      });
      setEditingJobId(null); // Exit edit mode
    } else {
      // Create new
      await saveJob({
        ...jobData,
        date: new Date().toLocaleDateString(),
        createdAt: Date.now()
      });
    }

    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleToggleJobStatus = async (job: HistoryItem) => {
      const newStatus = job.status === 'completed' ? 'pending' : 'completed';
      // Optimistic update
      setHistory(prev => prev.map(h => h.id === job.id ? { ...h, status: newStatus } : h));
      await updateJob(job.id, { status: newStatus });
      // Background refresh to ensure sync
      const updated = await getJobs();
      setHistory(updated);
  };

  const handleEditJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
  };

  const handleLoadJob = (job: HistoryItem) => {
    // Just load inputs, treat as new unless they explicitly clicked edit
    setInputs(job.inputs);
    setEditingJobId(null);
  };

  const handleCancel = () => {
    setEditingJobId(null);
    setInputs(mergeWithDefaults(loadSettings()));
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      setHistory(await getJobs());
      setJobToDelete(null);
    }
  };

  const handleImportToInventory = () => {
    if (!inputs.jobName) {
      alert("Please enter a Job Name first.");
      return;
    }

    // Exclude shipping from inventory cost basis usually
    const shipping = typeof inputs.shippingCost === 'number' ? inputs.shippingCost : parseFloat(inputs.shippingCost as string) || 0;
    const costBasis = Math.max(0, results.unit.totalCostBasis - shipping);
    const taxRate = typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string) || 0;

    setProductToImport({
      name: inputs.jobName,
      price: parseFloat(results.unit.finalPrice.toFixed(2)),
      cost: parseFloat(costBasis.toFixed(2)),
      taxRate: taxRate
    });
  };

  const executeImportToInventory = async () => {
    if (!productToImport) return;

    await saveProduct({
      name: productToImport.name,
      category: 'Printed', // Default category
      price: productToImport.price,
      cost: productToImport.cost,
      taxRate: productToImport.taxRate, 
      stock: 0,
      createdAt: Date.now()
    });
    setProducts(await getProducts());
    setProductToImport(null);
    setActiveView('products'); // Switch view to show the result
  };

  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
        const parsed = await parseGCodeFile(file);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                jobName: parsed.filename ? parsed.filename.replace(/\.(gcode|3mf|txt)$/i, '') : prev.jobName,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
        } else {
            alert('Could not extract data from file.');
        }
    } catch (e) {
        alert('Error parsing file.');
    } finally {
        setIsParsing(false);
    }
  };

  // --- ACTIONS: PRODUCTS ---
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    setProducts(await getProducts());
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    setProducts(await getProducts());
  };

  const handleDeleteProduct = (id: string) => {
    setProductToDelete(id);
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
        await deleteProduct(productToDelete);
        setProducts(await getProducts());
        setProductToDelete(null);
    }
  };

  // --- ACTIONS: POS ---
  const handleAddToCart = (item: SaleItem) => {
    setCart(prev => {
      const existing = prev.findIndex(i => i.refId === item.refId && i.type === item.type);
      if (existing !== -1) {
        const updated = [...prev];
        updated[existing].quantity += 1;
        return updated;
      }
      return [...prev, item];
    });
  };

  const handleUpdateCartQty = (index: number, delta: number) => {
    setCart(prev => {
      const updated = [...prev];
      updated[index].quantity += delta;
      if (updated[index].quantity <= 0) return prev.filter((_, i) => i !== index);
      return updated;
    });
  };

  const handleCheckout = async (method: Sale['paymentMethod'], shippingCost: number) => {
    const itemRev = cart.reduce((sum, i) => sum + (i.unitPrice * i.quantity), 0);
    const itemCost = cart.reduce((sum, i) => sum + (i.unitCost * i.quantity), 0);

    // Add shipping to Revenue
    const totalRev = itemRev + shippingCost;

    // Add shipping to Cost (assuming pass-through/zero profit on shipping)
    // This prevents profit from inflating by the shipping amount
    const totalCost = itemCost + shippingCost;

    // Profit = Sum [ (ItemPrice / (1+Tax)) - ItemCost ] * Qty
    const totalProfit = cart.reduce((sum, i) => {
        const rate = i.taxRate || 0;
        const netPrice = i.unitPrice / (1 + (rate/100));
        return sum + ((netPrice - i.unitCost) * i.quantity);
    }, 0);

    // 1. Save Sale
    await saveSale({
      items: cart,
      totalRevenue: totalRev,
      totalCost: totalCost,
      totalProfit: totalProfit,
      paymentMethod: method,
      timestamp: Date.now(),
      dateStr: new Date().toLocaleDateString(),
      shipping: shippingCost
    });

    // 2. Update Inventory Stock
    for (const item of cart) {
        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                const newStock = product.stock - item.quantity;
                await updateProduct(product.id, { stock: newStock });
            }
        }
    }

    setSales(await getSales());
    setProducts(await getProducts());
    setCart([]);
    alert('Sale Completed!');
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    setSales(await getSales());
  };

  const handleDeleteSale = (id: string) => {
    setSaleToDelete(id);
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
        await deleteSale(saleToDelete);
        setSales(await getSales());
        setSaleToDelete(null);
    }
  };

  // --- ACTIONS: BACKUP / RESTORE ---
  const handleExportData = () => {
      const data = {
          jobs: history,
          products: products,
          sales: sales,
          capital: capitalHistory,
          exportedAt: new Date().toISOString()
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3d_print_data_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportData = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || !e.target.files[0]) return;
      const file = e.target.files[0];

      setIsImporting(true);
      try {
          const text = await file.text();
          const data = JSON.parse(text);

          let count = 0;

          if (data.jobs && Array.isArray(data.jobs)) {
              for (const job of data.jobs) {
                 // Remove ID to force new creation or check uniqueness logic?
                 // For simplicity in this request, we append as new to avoid overwriting unique IDs from different systems.
                 // A real system might upsert based on ID.
                 const { id, ...rest } = job; 
                 await saveJob(rest);
                 count++;
              }
          }
          if (data.products && Array.isArray(data.products)) {
              for (const p of data.products) {
                  const { id, ...rest } = p;
                  await saveProduct(rest);
                  count++;
              }
          }
          if (data.sales && Array.isArray(data.sales)) {
              for (const s of data.sales) {
                  const { id, ...rest } = s;
                  await saveSale(rest);
                  count++;
              }
          }
          if (data.capital && Array.isArray(data.capital)) {
              for (const c of data.capital) {
                  const { id, ...rest } = c;
                  await saveCapitalItem(rest);
                  count++;
              }
          }

          alert(`Import successful! Added ${count} records.`);
          await refreshAllData();
          setShowSettingsModal(false);

      } catch (err) {
          console.error(err);
          alert("Failed to import file. Invalid format.");
      } finally {
          setIsImporting(false);
          // Reset file input
          e.target.value = '';
      }
  };

  // --- RENDER HELPERS ---
  const currency = (val: number | undefined) => {
    return '₱' + (val || 0).toLocaleString('en-US', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    });
  };

  // --- MAIN RENDER ---
  return (
    <div className="flex flex-col h-screen bg-gray-100 overflow-hidden font-sans">

      {/* 1. TOP NAVIGATION */}
      <div className="bg-slate-900 text-white h-16 flex items-center justify-between px-6 shadow-md flex-none z-50">
        <div className="flex items-center gap-3">
          <div className="bg-brand-600 p-1.5 rounded-lg">
             <Printer size={20} />
          </div>
          <h1 className="font-bold text-lg tracking-tight hidden sm:block">Command <span className="text-brand-500">Center</span></h1>
        </div>

        <nav className="flex bg-slate-800 rounded-lg p-1 gap-1">
          <NavButton active={activeView === 'calculator'} onClick={() => setActiveView('calculator')} icon={<Calculator size={18}/>} label="Calculator" />
          <NavButton active={activeView === 'products'} onClick={() => setActiveView('products')} icon={<PackageIcon size={18}/>} label="Inventory" />
          <NavButton active={activeView === 'pos'} onClick={() => setActiveView('pos')} icon={<Store size={18}/>} label="POS" />
          <NavButton active={activeView === 'dashboard'} onClick={() => setActiveView('dashboard')} icon={<LayoutDashboard size={18}/>} label="Analytics" />
        </nav>

        <div className="flex items-center gap-4 w-32 justify-end">
           {/* Cloud Status Text */}
           <div 
             className={clsx(
               "flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border",
               syncStatus.isCloud ? "bg-green-900/30 text-green-400 border-green-800" : "bg-red-900/30 text-red-400 border-red-800"
             )}
             title={`Project ID: ${syncStatus.projectId}`}
           >
              <Cloud size={12} />
              <span className="hidden lg:inline">{syncStatus.isCloud ? "Online" : "Connection Error"}</span>
           </div>

           {/* Settings / Data Button */}
           <button 
             onClick={() => setShowSettingsModal(true)}
             className="text-slate-400 hover:text-white transition-colors"
           >
              <Settings size={20} />
           </button>

           {cart.length > 0 && activeView !== 'pos' && (
              <button onClick={() => setActiveView('pos')} className="relative p-2 bg-brand-600 rounded-full hover:bg-brand-500 transition-colors">
                 <ShoppingCart size={18} />
                 <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-bold">
                    {cart.reduce((a, b) => a + b.quantity, 0)}
                 </span>
              </button>
           )}
        </div>
      </div>

      {/* 2. MAIN CONTENT AREA */}
      <div className="flex-1 overflow-hidden relative">

        {/* VIEW: CALCULATOR */}
        {activeView === 'calculator' && (
           <CalculatorView 
              inputs={inputs} setInputs={setInputs} results={results} history={history}
              editingJobId={editingJobId} isSaving={isSaving} isParsing={isParsing}
              isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen}
              onLoadJob={handleLoadJob} onEditJob={handleEditJob} onSaveJob={handleSaveJob}
              onDeleteJob={(id) => setJobToDelete(id)}
              onCancel={handleCancel}
