                    {/* Footer Actions */}
                    <div className="bg-slate-800/80 p-6 border-t border-slate-700 backdrop-blur-sm">
                        <div className="text-center mb-6">
                            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Recommended List Price (VAT Inc)</p>

                            {/* Editable Price Input */}
                            <div className="relative group">
                                <div className="absolute left-0 top-1/2 -translate-y-1/2 text-slate-500 font-bold text-2xl pl-2 pointer-events-none">₱</div>
                                <input 
                                    type="number" 
                                    className="w-full bg-transparent text-4xl font-black text-white tracking-tight text-center border-b border-transparent hover:border-slate-600 focus:border-brand-500 focus:outline-none transition-all pb-1"
                                    value={isEditingPrice ? priceInputValue : (viewMode === 'unit' ? results.unit.finalPrice : results.batch.finalPrice).toFixed(2)}
                                    onFocus={(e) => {
                                        setIsEditingPrice(true);
                                        setPriceInputValue((viewMode === 'unit' ? results.unit.finalPrice : results.batch.finalPrice).toFixed(2));
                                        e.target.select();
                                    }}
                                    onBlur={() => setIsEditingPrice(false)}
                                    onChange={handlePriceChange}
                                />
                                <Edit2 size={12} className="absolute right-0 top-1/2 -translate-y-1/2 text-slate-600 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                            </div>

                            <div className="text-brand-500 font-bold text-xs mt-2 bg-brand-500/10 inline-block px-3 py-1 rounded-full">
                                {currency(viewMode === 'unit' ? results.unit.profit : results.batch.profit)} Profit
                            </div>
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            {editingJobId ? (
                                <>
                                    <button 
                                        onClick={onCancel}
                                        className="col-span-1 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all text-sm"
                                    >
                                        <X size={16} /> Cancel
                                    </button>
                                    <button 
                                        onClick={() => onSaveJob(false)}
                                        disabled={isSaving}
                                        className="col-span-1 bg-brand-600 hover:bg-brand-500 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/20 disabled:opacity-50 text-sm"
                                    >
                                        {isSaving ? <Loader2 className="animate-spin" size={16} /> : <Edit2 size={16} />}
                                        Update
                                    </button>
                                    <button 
                                        onClick={() => onSaveJob(true)}
                                        disabled={isSaving}
                                        className="col-span-2 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all disabled:opacity-50 text-sm"
                                    >
                                        <Copy size={16} /> Save as New Copy
                                    </button>
                                </>
                            ) : (
                                <>
                                    <button 
                                        onClick={onCancel}
                                        className="col-span-1 bg-slate-700 hover:bg-slate-600 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all text-sm"
                                    >
                                        <X size={16} /> Clear
                                    </button>
                                    <button 
                                        onClick={() => onSaveJob(false)}
                                        disabled={isSaving}
                                        className="col-span-1 bg-brand-600 hover:bg-brand-500 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/20 disabled:opacity-50 text-sm"
                                    >
                                        {isSaving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
                                        Save Job
                                    </button>
                                </>
                            )}

                            <button 
                                onClick={() => {
                                    const text = `Quote: ${inputs.jobName}\nPrice: ${currency(results.unit.finalPrice)}`;
                                    navigator.clipboard.writeText(text);
                                    alert('Copied!');
                                }}
                                className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                            >
                                <Copy size={14} /> Copy
                            </button>
                             <button 
                                onClick={onShowDashboard}
                                className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                            >
                                <LayoutDashboard size={14} /> Dash
                            </button>

                            <button 
                                onClick={onAddToInventory}
                                className="col-span-2 bg-brand-600/10 hover:bg-brand-600/20 text-brand-600 font-bold py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs border border-brand-200 mt-1"
                            >
                                <PackagePlus size={16} /> Add to Inventory
                            </button>
                        </div>
                    </div>
                </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
};

const Section = ({ title, icon, children, isOpen = true, onToggle, action }: any) => {
    return (
        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
            <div 
                className={clsx(
                    "px-6 py-4 border-b border-gray-100 bg-gray-50/50 flex items-center justify-between cursor-pointer hover:bg-gray-100 transition-colors",
                    !isOpen && "border-b-0"
                )}
                onClick={onToggle}
            >
                <div className="flex items-center gap-2">
                    {icon}
                    <h2 className="text-xs font-bold text-gray-700 uppercase tracking-widest">{title}</h2>
                </div>
                <div className="flex items-center gap-3">
                    {action}
                    {onToggle && (
                        <div className="text-gray-400">
                            {isOpen ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                        </div>
                    )}
                </div>
            </div>

            {isOpen && (
                <div className="p-6 space-y-6 animate-in slide-in-from-top-2 duration-200">
                    {children}
                </div>
            )}
        </section>
    );
};

const LineItem = ({ label, value, color, currency }: { label: string, value: number, color: string, currency: (val: number) => string }) => (
    <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
            <div className={clsx("w-2 h-2 rounded-full", color)}></div>
            <span className="text-xs font-bold text-slate-400">{label}</span>
        </div>
        <span className="text-xs font-bold text-white">{currency(value)}</span>
    </div>
);

const SubItem = ({ label, value, currency, color }: { label: string, value: number, currency: (val: number) => string, color?: string }) => (
    <div className={clsx("flex justify-between items-center text-[10px] font-medium", color || "text-slate-500")}>
        <span>{label}</span>
        <span>{currency(value)}</span>
    </div>
);

import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, Settings, Download, Upload, Loader2, X
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<{name: string, price: number, cost: number, taxRate: number} | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  const refreshAllData = async () => {
    return Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  };

  useEffect(() => {
    refreshAllData();
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [inputs]);

  const currency = (val: number) => '₱' + val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- HANDLERS ---

  // File Handler
  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
      const data = await parseGCodeFile(file);
      if (data.found) {
        setInputs(prev => ({
          ...prev,
          timeHours: data.hours,
          timeMinutes: data.minutes,
          materialGrams: data.grams,
          jobName: data.filename?.replace(/\.(gcode|3mf|txt)$/i, '') || prev.jobName
        }));
      } else {
        alert("Could not extract print time or weight from file.");
      }
    } catch (e) {
      console.error(e);
      alert("Error parsing file");
    } finally {
      setIsParsing(false);
    }
  };

  // Job Handlers
  const handleLoadJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    handleLoadJob(job);
  };

  const handleSaveJob = async (asCopy: boolean) => {
    setIsSaving(true);
    try {
      const jobData = {
        name: inputs.jobName || 'Untitled Job',
        date: new Date().toLocaleDateString(),
        inputs,
        resultsSnapshot: results,
        finalPrice: results.unit.finalPrice,
        status: 'pending' as const,
        createdAt: Date.now()
      };

      if (editingJobId && !asCopy) {
        await updateJob(editingJobId, { ...jobData, updatedAt: Date.now() });
        setEditingJobId(null);
      } else {
        await saveJob(jobData);
      }
      refreshAllData();
    } catch (e) {
      console.error(e);
      alert("Failed to save job");
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggleJobStatus = async (job: HistoryItem) => {
    const newStatus = job.status === 'completed' ? 'pending' : 'completed';
    await updateJob(job.id, { status: newStatus });
    refreshAllData();
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      refreshAllData();
      setJobToDelete(null);
    }
  };

  const handleAddToInventory = () => {
      setProductToImport({
          name: inputs.jobName || 'Untitled Print',
          price: results.unit.finalPrice,
          cost: results.unit.productionCost,
          taxRate: typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string)
      });
      setActiveView('products');
  };

  // Capital Handlers
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    refreshAllData();
  };

  const handleUpdateCapital = async (id: string, updates: Partial<CapitalItem>) => {
    await updateCapitalItem(id, updates);
    refreshAllData();
  };

  const confirmDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    refreshAllData();
  };

  // Product Handlers
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    refreshAllData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    refreshAllData();
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
      await deleteProduct(productToDelete);
      refreshAllData();
      setProductToDelete(null);
    }
  };

  // Sale/POS Handlers
  const handleCheckout = async (paymentMethod: Sale['paymentMethod'], shipping: number) => {
    let totalRevenue = 0;
    let totalCost = 0;

    // Calculate totals and deduct stock
    for (const item of cart) {
        totalRevenue += item.unitPrice * item.quantity;
        totalCost += item.unitCost * item.quantity;

        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                await updateProduct(product.id, { stock: product.stock - item.quantity });
            }
        }
    }

    const sale: Omit<Sale, 'id'> = {
        items: cart,
        totalRevenue: totalRevenue + shipping,
        totalCost,
        totalProfit: (totalRevenue + shipping) - totalCost,
        paymentMethod,
        shipping,
        timestamp: Date.now(),
        dateStr: new Date().toLocaleDateString()
    };

    await saveSale(sale);
    setCart([]);
    refreshAllData();
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    refreshAllData();
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
      await deleteSale(saleToDelete);
      refreshAllData();
      setSaleToDelete(null);
    }
  };

  // --- BACKUP / RESTORE LOGIC ---

  const handleExportData = () => {
      const data = {
          jobs: history,
          products: products,
          sales: sales,
          capital: capitalHistory,
          exportedAt: new Date().toISOString()
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3d_print_data_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportData = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || !e.target.files[0]) return;
      const file = e.target.files[0];

      setIsImporting(true);
      try {
          const text = await file.text();
          const data = JSON.parse(text);

          // 1. Fetch existing data for de-duplication (checking against current loaded state + more if needed)
          // We can rely on the current state if it's reasonably fresh, or fetch fresh.
          // To be safe against a large DB not fully loaded in state, we should fetch ID lists or rely on state if `refreshAllData` was called.
          // For simplicity and performance in this client-side app, we'll dedupe against the currently loaded state `history`, `products`, etc.
          // *Better:* Fetch fresh full lists to be sure.

          const [exJobs, exProducts, exSales, exCapital] = await Promise.all([
             getJobs(2000), // Check last 2000 jobs
             getProducts(),
             getSales(2000),
             getCapitalItems(2000)
          ]);

          // Sets for fast lookup
          // Job: De-dupe by createdAt timestamp
          const jobTimestamps = new Set(exJobs.map(j => j.createdAt));
          // Product: De-dupe by Name (Case insensitive)
          const productNames = new Set(exProducts.map(p => p.name.toLowerCase()));
          // Sales: De-dupe by timestamp
          const saleTimestamps = new Set(exSales.map(s => s.timestamp));
          // Capital: De-dupe by Name + PurchaseDate + Price (Composite key)
          const getCapKey = (c: any) => `${c.name}|${c.purchaseDate}|${c.price}`;
          const capitalKeys = new Set(exCapital.map(c => getCapKey(c)));

          let added = 0;
          let skipped = 0;

          // Import Jobs
          if (data.jobs && Array.isArray(data.jobs)) {
              for (const job of data.jobs) {
                 if (job.createdAt && jobTimestamps.has(job.createdAt)) {
                     skipped++; continue;
                 }
                 // Legacy support: if no createdAt, maybe check name+date?
                 // For now, assume good export format.
                 const { id, ...rest } = job; 
                 await saveJob(rest);
                 added++;
              }
          }

          // Import Products
          if (data.products && Array.isArray(data.products)) {
              for (const p of data.products) {
                  if (p.name && productNames.has(p.name.toLowerCase())) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = p;
                  await saveProduct(rest);
                  added++;
              }
          }

          // Import Sales
          if (data.sales && Array.isArray(data.sales)) {
              for (const s of data.sales) {
                  if (s.timestamp && saleTimestamps.has(s.timestamp)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = s;
                  await saveSale(rest);
                  added++;
              }
          }

          // Import Capital
          if (data.capital && Array.isArray(data.capital)) {
              for (const c of data.capital) {
                  const key = getCapKey(c);
                  if (capitalKeys.has(key)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = c;
                  await saveCapitalItem(rest);
                  added++;
              }
          }

          alert(`Import successful!\n\n✅ Added: ${added} new records\n🚫 Skipped: ${skipped} duplicates`);
          await refreshAllData();
          setShowSettingsModal(false);

      } catch (err) {
          console.error(err);
          alert("Failed to import file. Invalid format or corrupt file.");
      } finally {
          setIsImporting(false);
          // Reset file input
          e.target.value = '';
      }
  };

  // Navigation Helper
  const NavItem = ({ view, icon: Icon, label }: { view: typeof activeView, icon: any, label: string }) => (
    <button 
      onClick={() => setActiveView(view)}
      className={clsx(
          "flex items-center gap-2 px-4 py-2 rounded-lg transition-colors text-sm font-bold",
          activeView === view ? "bg-brand-600 text-white" : "text-gray-600 hover:bg-gray-100"
      )}
    >
        <Icon size={18} />
        <span className="hidden md:inline">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-white">
        {/* Top Navigation */}
        <header className="flex items-center justify-between px-6 py-3 border-b border-gray-200 flex-none bg-white z-40">
            <div className="flex items-center gap-3">
                <div className="bg-brand-600 text-white p-2 rounded-lg">
                    <Printer size={20} />
                </div>
                <div>
                    <h1 className="font-black text-lg text-gray-900 leading-none">BambuCalc</h1>
                    <div className="flex items-center gap-1 text-[10px] text-gray-400 font-medium">
                        <Cloud size={10} /> {syncStatus.isCloud ? 'Cloud Sync Active' : 'Local Mode'}
                    </div>
                </div>
            </div>

            <nav className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl border border-gray-100">
                <NavItem view="calculator" icon={Calculator} label="Calculator" />
                <NavItem view="products" icon={PackageIcon} label="Inventory" />
                <NavItem view="pos" icon={ShoppingCart} label="POS" />
                <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            </nav>

            <div className="flex items-center gap-2 w-32 justify-end">
                 <button 
                    onClick={() => setShowSettingsModal(true)}
                    className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
                    title="Settings & Data"
                 >
                    <Settings size={20} />
                 </button>
            </div>
        </header>

        {/* Main View Area */}
        <main className="flex-1 overflow-hidden relative">
            {activeView === 'calculator' && (
                <CalculatorView 
                    inputs={inputs}
                    setInputs={setInputs}
                    results={results}
                    history={history}
                    editingJobId={editingJobId}
                    isSaving={isSaving}
                    isSidebarOpen={isSidebarOpen}
                    setIsSidebarOpen={setIsSidebarOpen}
                    onLoadJob={handleLoadJob}
                    onEditJob={handleEditJob}
                    onDeleteJob={id => setJobToDelete(id)}
                    onSaveJob={handleSaveJob}
                    onCancel={() => { setEditingJobId(null); setInputs(mergeWithDefaults({})); }}
                    onShowMath={() => setShowMathModal(true)}
                    onShowDashboard={() => setActiveView('dashboard')}
                    onAddToInventory={handleAddToInventory}
                    handleFile={handleFile}
                    isParsing={isParsing}
                    currency={currency}
                    onToggleJobStatus={handleToggleJobStatus}
                />
            )}

            {activeView === 'products' && (
                <ProductManager 
                    products={products}
                    onAdd={handleAddProduct}
                    onUpdate={handleUpdateProduct}
                    onDelete={id => setProductToDelete(id)}
                    currency={currency}
                />
            )}

            {activeView === 'pos' && (
                <POSInterface 
                    products={products}
                    jobs={history}
                    cart={cart}
                    currency={currency}
                    onAddToCart={item => {
                        const existing = cart.findIndex(c => c.type === item.type && c.refId === item.refId);
                        if (existing >= 0) {
                            const newCart = [...cart];
                            newCart[existing].quantity += item.quantity;
                            setCart(newCart);
                        } else {
                            setCart([...cart, item]);
                        }
                    }}
                    onUpdateCartQty={(idx, delta) => {
                         const newCart = [...cart];
                         newCart[idx].quantity += delta;
                         if (newCart[idx].quantity <= 0) newCart.splice(idx, 1);
                         setCart(newCart);
                    }}
                    onRemoveFromCart={idx => {
                        const newCart = [...cart];
                        newCart.splice(idx, 1);
                        setCart(newCart);
                    }}
                    onCheckout={handleCheckout}
                    onClearCart={() => setCart([])}
                />
            )}

            {activeView === 'dashboard' && (
                <DashboardView 
                    history={history}
                    capitalHistory={capitalHistory}
                    sales={sales}
                    onDeleteJob={id => setJobToDelete(id)}
                    onAddCapital={handleAddCapital}
                    onUpdateCapital={handleUpdateCapital}
                    onDeleteCapital={confirmDeleteCapital}
                    onUpdateSale={handleUpdateSale}
                    onDeleteSale={id => setSaleToDelete(id)}
                    currency={currency}
                />
            )}
        </main>

        {/* Modals */}
        <MathModal 
            isOpen={showMathModal} 
            onClose={() => setShowMathModal(false)}
            inputs={inputs}
            results={results}
            currency={currency}
        />

        {/* Settings Modal (Backup/Restore) */}
        {showSettingsModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
             <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl border border-gray-100">
                 <div className="flex justify-between items-center mb-6">
                    <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                        <Settings className="text-brand-600" /> Settings & Data
                    </h2>
                    <button onClick={() => setShowSettingsModal(false)} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                 </div>

                 <div className="space-y-4">
                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Backup Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Download a JSON file containing all jobs, products, sales, and expenses.</p>
                         <button 
                            onClick={handleExportData}
                            className="w-full flex items-center justify-center gap-2 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold py-2 rounded-lg transition-colors text-sm shadow-sm"
                         >
                             <Download size={16} /> Download Backup
                         </button>
                     </div>

                     <div className="bg-gray-50 p-4 rounded-xl border border-gray-100">
                         <h3 className="text-sm font-bold text-gray-800 mb-2">Restore Data</h3>
                         <p className="text-xs text-gray-500 mb-3">Import data from a backup file. Existing records will be skipped to prevent duplicates.</p>
                         <div className="relative">
                            <input 
                                type="file" 
                                accept=".json" 
                                onChange={handleImportData}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                disabled={isImporting}
                            />
                            <button 
                                className="w-full flex items-center justify-center gap-2 bg-brand-600 hover:bg-brand-700 text-white font-bold py-2 rounded-lg transition-colors text-sm shadow-md disabled:opacity-50"
                                disabled={isImporting}
                            >
                                {isImporting ? <Loader2 className="animate-spin" size={16} /> : <Upload size={16} />}
                                {isImporting ? 'Importing...' : 'Upload Backup File'}
                            </button>
                         </div>
                     </div>
                 </div>

                 <div className="mt-6 text-center text-[10px] text-gray-400">
                     v1.2.1 • Data is synced to Google Firebase
                 </div>
             </div>
          </div>
        )}

        <ConfirmDialog 
            isOpen={!!jobToDelete}
            title="Delete Job?"
            message="This action cannot be undone. The job record will be permanently removed."
            onConfirm={confirmDeleteJob}
            onCancel={() => setJobToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToDelete}
            title="Delete Product?"
            message="Are you sure? This will remove the product from inventory and POS."
            onConfirm={confirmDeleteProduct}
            onCancel={() => setProductToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!saleToDelete}
            title="Delete Sale Record?"
            message="This will remove the transaction from your ledger."
            onConfirm={confirmDeleteSale}
            onCancel={() => setSaleToDelete(null)}
        />

        <ConfirmDialog 
            isOpen={!!productToImport}
            title="Import to Inventory"
            message={`Add "${productToImport?.name}" to Inventory?\nRecommended Price: ${currency(productToImport?.price || 0)}\nCost Basis: ${currency(productToImport?.cost || 0)}\nVAT Rate: ${productToImport?.taxRate}%`}
            onConfirm={() => {
                if (productToImport) {
                    saveProduct({
                        name: productToImport.name,
                        category: 'Printed',
                        price: productToImport.price,
                        cost: productToImport.cost,
                        taxRate: productToImport.taxRate,
                        stock: 0,
                        createdAt: Date.now()
                    }).then(() => {
                        refreshAllData();
                        setProductToImport(null);
                    });
                }
            }}
            onCancel={() => setProductToImport(null)}
            confirmText="Import"
            type="info"
        />
    </div>
  );
}

export default App;

export interface Material {
  id: string;
  name: string;
  costPerKg: number;
}

export interface ExtraCost {
  id: string;
  name: string;
  price: number | string;
}

export interface CalculatorInputs {
  // Job Info
  jobName: string;
  batchQty: number | string;
  notes?: string; // New: Job specific notes

  // Material
  materialCost: number | string;
  materialGrams: number | string;
  wastageMultiplier: number | string; // New: Wastage factor (e.g. 1.05)

  // Time
  timeHours: number | string;
  timeMinutes: number | string;
  dryingHours: number | string; 
  dryingMinutes: number | string; 
  dryingTimeSameAsPrintTime: boolean; 

  // Extras
  extras: ExtraCost[];

  // Machine Overhead
  machineCost: number | string;
  lifespanHours: number | string;
  powerWatts: number | string;
  dryerPowerWatts: number | string;
  elecRate: number | string; // Cost per kWh

  // Labor
  laborRate: number | string; // Hourly
  laborMins: number | string; // Prep time per batch
  failMargin: number | string; // Percentage

  // Commercial
  // Shopee PH Specific Structure
  usePlatformFees: boolean; // Toggle for platform fees
  platformCommissionFee: number | string; // % on Item Price
  platformTransactionFee: number | string; // % on (Item + Shipping)
  platformServiceFee: number | string; // % on Item Price
  platformFixedFee: number | string; // Fixed amount

  taxRate: number | string; // Percentage (VAT)
  packagingCost: number | string; // Per Unit
  shippingCost: number | string; // Per Unit
  markup: number | string; // Percentage
}

export interface CostBreakdown {
  material: number;
  energy: number;
  depreciation: number;
  labor: number;
  extras: number;
  failureRisk: number;

  // Commercial
  packaging: number;
  shipping: number;
  tax: number;
  platformFeeAmount: number;

  // Totals
  productionCost: number; // Raw cost to make
  totalCostBasis: number; // Cost + Ops + Tax + Ship
  profit: number;
  finalPrice: number;
}

export interface CalculatedResults {
  unit: CostBreakdown;
  batch: CostBreakdown;
  // Metadata for Math View
  meta: {
    printHours: number;
    dryingHours: number;
    printerEnergyCost: number;
    dryerEnergyCost: number;
    billedGrams: number;
  }
}

export interface HistoryItem {
  id: string;
  date: string; // Legacy string date
  createdAt: number; // Timestamp
  updatedAt?: number; // Timestamp of last edit
  name: string;
  inputs: CalculatorInputs;
  // Snapshot of calculations at the time of save to prevent logic drift
  resultsSnapshot?: CalculatedResults; 
  finalPrice: number;
  status?: 'pending' | 'completed'; // New Status field
}

export interface CapitalItem {
  id: string;
  name: string; // "Purchases" in xls
  price: number;
  quantity: number; // Quantity of items
  category: 'Printer' | 'Filament' | 'Parts' | 'Other';

  // New Spreadsheet Fields
  platform: string; // e.g. "Shopee", "Website"
  store: string;    // e.g. "Makerlab", "Yan Plasticware"
  purchaseDate: string;
  dateReceived?: string;
  orderedBy: string; // Initials (RB, BB)
  paidBy: string;    // Initials (RB, BB, Shared)
  receiptLink?: string;
  remarks?: string;

  createdAt: number; // For sorting
}

// --- NEW COMMERCE TYPES ---

export interface Product {
  id: string;
  name: string;
  sku?: string;
  category: string;
  price: number; // Selling Price (VAT Inc)
  cost: number;  // Cost Basis
  laborCost?: number; // New: Track labor portion
  energyCost?: number; // New: Track energy portion
  taxRate: number; // VAT Rate included in price
  stock: number;
  imageUrl?: string;
  createdAt: number;
}

export interface SaleItem {
  type: 'product' | 'job';
  refId: string; // ID of the Product or HistoryItem
  name: string;
  quantity: number;
  unitPrice: number;
  unitCost: number; // Snapshot for profit calc
  laborCost?: number; // New: Snapshot
  energyCost?: number; // New: Snapshot
  taxRate: number; // Snapshot of VAT rate at time of sale
}

export interface Sale {
  id: string;
  items: SaleItem[];
  totalRevenue: number;
  totalCost: number;
  totalProfit: number;
  paymentMethod: 'cash' | 'gcash' | 'card' | 'other';
  timestamp: number;
  dateStr: string;
  shipping?: number;
}

import React, { useState, useEffect } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, CapitalItem, Product, SaleItem, Sale } from './types';
import { calculateCosts } from './services/calculatorService';
import { parseGCodeFile } from './services/gcodeService';
import { 
  saveJob, getJobs, deleteJob, updateJob,
  saveCapitalItem, getCapitalItems, deleteCapitalItem, updateCapitalItem,
  getProducts, saveProduct, deleteProduct, updateProduct,
  saveSale, getSales, updateSale, deleteSale,
  getSyncStatus
} from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';

// View Components
import { CalculatorView } from './components/CalculatorView';
import { DashboardView } from './components/DashboardView';
import { MathModal } from './components/MathModal';
import { ProductManager } from './components/ProductManager';
import { POSInterface } from './components/POSInterface';
import { ConfirmDialog } from './components/ConfirmDialog';

import { 
  Printer, Calculator, Package as PackageIcon, 
  ShoppingCart, LayoutDashboard, Cloud, Settings, Download, Upload, Loader2, X
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // --- STATE MANAGEMENT ---
  const [activeView, setActiveView] = useState<'calculator' | 'products' | 'pos' | 'dashboard'>('calculator');

  // Calculator State
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isParsing, setIsParsing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Data State
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [syncStatus] = useState(getSyncStatus());

  // POS State (Lifted)
  const [cart, setCart] = useState<SaleItem[]>([]);

  // UI State
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });
  const [showMathModal, setShowMathModal] = useState(false);
  const [showSettingsModal, setShowSettingsModal] = useState(false);

  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [productToDelete, setProductToDelete] = useState<string | null>(null);
  const [saleToDelete, setSaleToDelete] = useState<string | null>(null);
  const [productToImport, setProductToImport] = useState<Omit<Product, 'id' | 'createdAt' | 'stock' | 'category'> | null>(null);
  const [isImporting, setIsImporting] = useState(false);

  // --- EFFECT HOOKS ---

  // Initial Data Load
  const refreshAllData = async () => {
    return Promise.all([
      getJobs(),
      getCapitalItems(),
      getProducts(),
      getSales()
    ]).then(([j, c, p, s]) => {
      setHistory(j);
      setCapitalHistory(c);
      setProducts(p);
      setSales(s);
    });
  };

  useEffect(() => {
    refreshAllData();
  }, []);

  // Recalculate when inputs change
  useEffect(() => {
    setResults(calculateCosts(inputs));
  }, [inputs]);

  // Persist settings
  useEffect(() => {
    saveSettings(inputs);
  }, [inputs]);

  const currency = (val: number) => '₱' + val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // --- HANDLERS ---

  // File Handler
  const handleFile = async (file: File) => {
    setIsParsing(true);
    try {
      const data = await parseGCodeFile(file);
      if (data.found) {
        setInputs(prev => ({
          ...prev,
          timeHours: data.hours,
          timeMinutes: data.minutes,
          materialGrams: data.grams,
          jobName: data.filename?.replace(/\.(gcode|3mf|txt)$/i, '') || prev.jobName
        }));
      } else {
        alert("Could not extract print time or weight from file.");
      }
    } catch (e) {
      console.error(e);
      alert("Error parsing file");
    } finally {
      setIsParsing(false);
    }
  };

  // Job Handlers
  const handleLoadJob = (job: HistoryItem) => {
    setInputs(job.inputs);
    setEditingJobId(job.id);
    setActiveView('calculator');
    if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const handleEditJob = (job: HistoryItem) => {
    handleLoadJob(job);
  };

  const handleSaveJob = async (asCopy: boolean) => {
    setIsSaving(true);
    try {
      const jobData = {
        name: inputs.jobName || 'Untitled Job',
        date: new Date().toLocaleDateString(),
        inputs,
        resultsSnapshot: results,
        finalPrice: results.unit.finalPrice,
        status: 'pending' as const,
        createdAt: Date.now()
      };

      if (editingJobId && !asCopy) {
        await updateJob(editingJobId, { ...jobData, updatedAt: Date.now() });
        setEditingJobId(null);
      } else {
        await saveJob(jobData);
      }
      refreshAllData();
    } catch (e) {
      console.error(e);
      alert("Failed to save job");
    } finally {
      setIsSaving(false);
    }
  };

  const handleToggleJobStatus = async (job: HistoryItem) => {
    const newStatus = job.status === 'completed' ? 'pending' : 'completed';
    await updateJob(job.id, { status: newStatus });
    refreshAllData();
  };

  const confirmDeleteJob = async () => {
    if (jobToDelete) {
      await deleteJob(jobToDelete);
      refreshAllData();
      setJobToDelete(null);
    }
  };

  const handleAddToInventory = () => {
      setProductToImport({
          name: inputs.jobName || 'Untitled Print',
          price: results.unit.finalPrice,
          cost: results.unit.productionCost,
          laborCost: results.unit.labor,
          energyCost: results.unit.energy,
          taxRate: typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string)
      });
      setActiveView('products');
  };

  // Capital Handlers
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    refreshAllData();
  };

  const handleUpdateCapital = async (id: string, updates: Partial<CapitalItem>) => {
    await updateCapitalItem(id, updates);
    refreshAllData();
  };

  const confirmDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    refreshAllData();
  };

  // Product Handlers
  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await saveProduct(p);
    refreshAllData();
  };

  const handleUpdateProduct = async (id: string, p: Partial<Product>) => {
    await updateProduct(id, p);
    refreshAllData();
  };

  const confirmDeleteProduct = async () => {
    if (productToDelete) {
      await deleteProduct(productToDelete);
      refreshAllData();
      setProductToDelete(null);
    }
  };

  // Sale/POS Handlers
  const handleCheckout = async (paymentMethod: Sale['paymentMethod'], shipping: number) => {
    let totalRevenue = 0;
    let totalCost = 0;

    // Calculate totals and deduct stock
    for (const item of cart) {
        totalRevenue += item.unitPrice * item.quantity;
        totalCost += item.unitCost * item.quantity;

        if (item.type === 'product') {
            const product = products.find(p => p.id === item.refId);
            if (product) {
                await updateProduct(product.id, { stock: product.stock - item.quantity });
            }
        }
    }

    const sale: Omit<Sale, 'id'> = {
        items: cart,
        totalRevenue: totalRevenue + shipping,
        totalCost,
        totalProfit: (totalRevenue + shipping) - totalCost,
        paymentMethod,
        shipping,
        timestamp: Date.now(),
        dateStr: new Date().toLocaleDateString()
    };

    await saveSale(sale);
    setCart([]);
    refreshAllData();
  };

  const handleUpdateSale = async (id: string, updates: Partial<Sale>) => {
    await updateSale(id, updates);
    refreshAllData();
  };

  const confirmDeleteSale = async () => {
    if (saleToDelete) {
      await deleteSale(saleToDelete);
      refreshAllData();
      setSaleToDelete(null);
    }
  };

  // --- BACKUP / RESTORE LOGIC ---

  const handleExportData = () => {
      const data = {
          jobs: history,
          products: products,
          sales: sales,
          capital: capitalHistory,
          exportedAt: new Date().toISOString()
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `3d_print_data_backup_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleImportData = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (!e.target.files || !e.target.files[0]) return;
      const file = e.target.files[0];

      setIsImporting(true);
      try {
          const text = await file.text();
          const data = JSON.parse(text);

          const [exJobs, exProducts, exSales, exCapital] = await Promise.all([
             getJobs(2000), 
             getProducts(),
             getSales(2000),
             getCapitalItems(2000)
          ]);

          const jobTimestamps = new Set(exJobs.map(j => j.createdAt));
          const productNames = new Set(exProducts.map(p => p.name.toLowerCase()));
          const saleTimestamps = new Set(exSales.map(s => s.timestamp));
          const getCapKey = (c: any) => `${c.name}|${c.purchaseDate}|${c.price}`;
          const capitalKeys = new Set(exCapital.map(c => getCapKey(c)));

          let added = 0;
          let skipped = 0;

          // Import Jobs
          if (data.jobs && Array.isArray(data.jobs)) {
              for (const job of data.jobs) {
                 if (job.createdAt && jobTimestamps.has(job.createdAt)) {
                     skipped++; continue;
                 }
                 const { id, ...rest } = job; 
                 await saveJob(rest);
                 added++;
              }
          }

          // Import Products
          if (data.products && Array.isArray(data.products)) {
              for (const p of data.products) {
                  if (p.name && productNames.has(p.name.toLowerCase())) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = p;
                  await saveProduct(rest);
                  added++;
              }
          }

          // Import Sales
          if (data.sales && Array.isArray(data.sales)) {
              for (const s of data.sales) {
                  if (s.timestamp && saleTimestamps.has(s.timestamp)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = s;
                  await saveSale(rest);
                  added++;
              }
          }

          // Import Capital
          if (data.capital && Array.isArray(data.capital)) {
              for (const c of data.capital) {
                  const key = getCapKey(c);
                  if (capitalKeys.has(key)) {
                      skipped++; continue;
                  }
                  const { id, ...rest } = c;
                  await saveCapitalItem(rest);
                  added++;
              }
          }

          alert(`Import successful!\n\n✅ Added: ${added} new records\n🚫 Skipped: ${skipped} duplicates`);
          await refreshAllData();
          setShowSettingsModal(false);

      } catch (err) {
          console.error(err);
          alert("Failed to import file. Invalid format or corrupt file.");
      } finally {
          setIsImporting(false);
          // Reset file input
          e.target.value = '';
      }
  };

  // Navigation Helper
  const NavItem = ({ view, icon: Icon, label }: { view: typeof activeView, icon: any, label: string }) => (
    <button 
      onClick={() => setActiveView(view)}
      className={clsx(
          "flex items-center gap-2 px-4 py-2 rounded-lg transition-colors text-sm font-bold",
          activeView === view ? "bg-brand-600 text-white" : "text-gray-600 hover:bg-gray-100"
      )}
    >
        <Icon size={18} />
        <span className="hidden md:inline">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-white">
        {/* Top Navigation */}
        <header className="flex items-center justify-between px-6 py-3 border-b border-gray-200 flex-none bg-white z-40">
            <div className="flex items-center gap-3">
                <div className="bg-brand-600 text-white p-2 rounded-lg">
                    <Printer size={20} />
                </div>
                <div>
                    <h1 className="font-black text-lg text-gray-900 leading-none">BambuCalc</h1>
                    <div className="flex items-center gap-1 text-[10px] text-gray-400 font-medium">
                        <Cloud size={10} /> {syncStatus.isCloud ? 'Cloud Sync Active' : 'Local Mode'}
                    </div>
                </div>
            </div>

            <nav className="flex items-center gap-2 bg-gray-50 p-1 rounded-xl border border-gray-100 hidden md:flex">
                <NavItem view="calculator" icon={Calculator} label="Calculator" />
                <NavItem view="products" icon={PackageIcon} label="Inventory" />
                <NavItem view="pos" icon={ShoppingCart} label="POS" />
                <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
            </nav>

            {/* Mobile Nav Dropdown Placeholder (Simplified for now) */}
            <div className="md:hidden">
               <button onClick={() => setActiveView(activeView === 'calculator' ? 'dashboard' : 'calculator')} className="text-gray-600">
                  <LayoutDashboard />
               </button>
            </div>

            <div className="flex items-center gap-2 md:w-32 justify-end">
                 <button 
                    onClick={() => setShowSettingsModal(true)}
                    className="p-2 text-gray-400 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-all"
                    title="Settings & Data"
                 >
                    <Settings size={20} />
                 </button>
            </div>
        </header>

        {/* Main View Area */}
        <main className="flex-1 overflow-hidden relative">
            {activeView === 'calculator' && (
                <CalculatorView 
                    inputs={inputs}
                    setInputs={setInputs}
                    results={results}
                    history={history}
                    editingJobId={editingJobId}
                    isSaving={isSaving}
                    isSidebarOpen={isSidebarOpen}
                    setIsSidebarOpen={setIsSidebarOpen}
                    onLoadJob={handleLoadJob}
                    onEditJob={handleEditJob}
                    onDeleteJob={id => setJobToDelete(id)}
                    onSaveJob={handleSaveJob}
                    onCancel={() => { setEditingJobId(null); setInputs(mergeWithDefaults({})); }}
                    onShowMath={() => setShowMathModal(true)}
                    onShowDashboard={() => setActiveView('dashboard')}
                    onAddToInventory={handleAddToInventory}
                    handleFile={handleFile}
                    isParsing={isParsing}
                    currency={currency}
                    onToggleJobStatus={handleToggleJobStatus}
                />
            )}

            {activeView === 'products' && (
                <ProductManager 
                    products={products}
                    onAdd={handleAddProduct}
                    onUpdate={handleUpdateProduct}
                    onDelete={id => setProductToDelete(id)}
                    currency={currency}
                />
            )}

            {activeView === 'pos' && (
                <POSInterface 
                    products={products}
                    jobs={history}
                    cart={cart}
                    currency={currency}
                    onAddToCart={item => {
                        const existing = cart.findIndex(c => c.type === item.type && c.refId === item.refId);
                        if (existing >= 0) {
                            const newCart = [...cart];
                            newCart[existing].quantity += item.quantity;
                            setCart(newCart);
                        } else {
                            setCart([...cart, item]);
                        }
                    }}
                    onUpdateCartQty={(idx, delta) => {
                         const newCart = [...cart];
                         newCart[idx].quantity += delta;
                         if (newCart[idx].quantity <= 0) newCart.splice(idx, 1);
                         setCart(newCart);
                    }}
                    onRemoveFromCart={idx => {
                        const newCart = [...cart];
                        newCart.splice(idx, 1);
                        setCart(newCart);
                    }}
                    onCheckout={handleCheckout}
                    onClearCart={() => setCart([])}
                />
            )}

            {activeView === 'dashboard' && (
                <DashboardView 
                    history={history}
                    capitalHistory={capitalHistory}
                    sales={sales}
                    onDeleteJob={id => setJobToDelete(id)}
                    onAddCapital={handleAddCapital}
                    onUpdateCapital={handleUpdateCapital}
                    onDeleteCapital={confirmDeleteCapital}
                    onUpdateSale={handleUpdateSale}
                    onDeleteSale={id => setSaleToDelete(id)}
                    currency={currency}
                />
            )}
        </main>

        {/* Modals & Dialogs (Unchanged) */}
        <MathModal 
            isOpen={showMathModal} 
            onClose={() => setShowMathModal(false)}
            inputs={inputs}
            results={results}
            currency={currency}
        />

        {showSettingsModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
