import React, { useState, useMemo } from 'react';
import { Product } from '../types';
import { Plus, Trash2, Package, Search, Edit2, ArrowUp, ArrowDown, Minus } from 'lucide-react';
import clsx from 'clsx';

interface ProductManagerProps {
  products: Product[];
  onAdd: (p: Omit<Product, 'id'>) => Promise<void>;
  onUpdate: (id: string, p: Partial<Product>) => Promise<void>;
  onDelete: (id: string) => void;
  currency: (val: number) => string;
}

type SortKey = 'name' | 'stock' | 'cost' | 'price' | 'profit';
interface SortConfig {
    key: SortKey;
    direction: 'asc' | 'desc';
}

export const ProductManager: React.FC<ProductManagerProps> = ({ products, onAdd, onUpdate, onDelete, currency }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Sorting State
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'name', direction: 'asc' });

  // Form State
  const [newName, setNewName] = useState('');
  const [newPrice, setNewPrice] = useState('');
  const [newCost, setNewCost] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategory, setNewCategory] = useState('Standard');
  const [newTaxRate, setNewTaxRate] = useState('12');

  const resetForm = () => {
    setIsAdding(false);
    setEditingId(null);
    setNewName('');
    setNewPrice('');
    setNewCost('');
    setNewStock('');
    setNewCategory('Standard');
    setNewTaxRate('12');
  };

  const handleEdit = (p: Product) => {
    setEditingId(p.id);
    setNewName(p.name);
    // Round to 2 decimals for cleaner editing
    setNewPrice(p.price.toFixed(2));
    setNewCost(p.cost.toFixed(2));
    setNewStock(p.stock.toString());
    setNewCategory(p.category);
    setNewTaxRate(p.taxRate !== undefined ? p.taxRate.toString() : '12');
    setIsAdding(true);
  };

  const handleUpdateStock = async (id: string, currentStock: number, delta: number) => {
      const newStock = Math.max(0, currentStock + delta);
      await onUpdate(id, { stock: newStock });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newPrice) return;

    const productData = {
      name: newName,
      price: parseFloat(newPrice),
      cost: parseFloat(newCost) || 0,
      stock: parseInt(newStock) || 0,
      category: newCategory,
      taxRate: parseFloat(newTaxRate) || 0
    };

    if (editingId) {
        await onUpdate(editingId, productData);
    } else {
        await onAdd({
            ...productData,
            createdAt: Date.now()
        });
    }

    resetForm();
  };

  const handleSort = (key: SortKey) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  const processedProducts = useMemo(() => {
    let result = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

    result.sort((a, b) => {
        const rateA = (a.taxRate !== undefined) ? a.taxRate : 0;
        const netPriceA = a.price / (1 + (rateA/100));
        const profitA = netPriceA - a.cost;

        const rateB = (b.taxRate !== undefined) ? b.taxRate : 0;
        const netPriceB = b.price / (1 + (rateB/100));
        const profitB = netPriceB - b.cost;

        let valA: any = a[sortConfig.key as keyof Product];
        let valB: any = b[sortConfig.key as keyof Product];

        // Handle computed keys
        if (sortConfig.key === 'profit') {
            valA = profitA;
            valB = profitB;
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });

    return result;
  }, [products, searchTerm, sortConfig]);

  // Live calculation for form
  const formPrice = parseFloat(newPrice) || 0;
  const formCost = parseFloat(newCost) || 0;
  const formTax = parseFloat(newTaxRate) || 0;
  const formNet = formPrice / (1 + (formTax/100));
  const formProfit = formNet - formCost;
  const formMargin = formNet > 0 ? (formProfit/formNet)*100 : 0;

  const SortHeader = ({ label, sKey, align = 'left' }: { label: string, sKey: SortKey, align?: string }) => (
      <th 
        className={`px-6 py-3 text-xs font-bold text-gray-500 uppercase cursor-pointer hover:text-brand-600 hover:bg-gray-100 transition-colors text-${align}`}
        onClick={() => handleSort(sKey)}
      >
          <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
            {label}
            {sortConfig.key === sKey && (
                sortConfig.direction === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>
            )}
          </div>
      </th>
  );

  return (
    <div className="max-w-6xl mx-auto p-4 md:p-6 mb-16 md:mb-0">

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-xl md:text-2xl font-bold text-gray-900 flex items-center gap-2">
            <Package className="text-brand-600" /> Product Inventory
           </h2>
           <p className="text-gray-500 text-xs md:text-sm mt-1">Manage standardized items for Point of Sale.</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsAdding(true); }}
          className="bg-brand-600 hover:bg-brand-700 text-white px-3 py-2 md:px-4 md:py-2 rounded-lg font-bold flex items-center gap-2 text-xs md:text-sm shadow-lg shadow-brand-500/20"
        >
          <Plus size={16} /> <span className="hidden md:inline">Add Product</span><span className="md:hidden">Add</span>
        </button>
      </div>

      {/* Add/Edit Modal/Panel */}
      {isAdding && (
        <div className="mb-8 bg-white p-6 rounded-xl border border-brand-100 shadow-sm animate-in slide-in-from-top-4">
           <div className="flex justify-between items-start mb-4">
               <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide">
                   {editingId ? 'Edit Product Details' : 'New Product Details'}
               </h3>
               {/* Live Profit Preview */}
               <div className="bg-gray-50 rounded px-3 py-1 text-right border border-gray-100">
                   <div className="text-[10px] text-gray-500 uppercase">Projected Profit</div>
                   <div className="text-sm font-bold text-brand-600">{currency(formProfit)} ({formMargin.toFixed(0)}%)</div>
               </div>
           </div>

           <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-6 gap-4 items-end">
              <div className="md:col-span-2">
                 <label className="block text-xs font-bold text-gray-500 mb-1">Item Name</label>
                 <input autoFocus className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="e.g. 3D Benchy - Red" value={newName} onChange={e => setNewName(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Selling Price (VAT Inc)</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newPrice} onChange={e => setNewPrice(e.target.value)} required />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Cost Basis</label>
                 <input type="number" step="0.01" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0.00" value={newCost} onChange={e => setNewCost(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">VAT Rate %</label>
                 <input type="number" step="0.1" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="12" value={newTaxRate} onChange={e => setNewTaxRate(e.target.value)} />
              </div>
              <div>
                 <label className="block text-xs font-bold text-gray-500 mb-1">Stock</label>
                 <input type="number" className="w-full text-sm border-gray-300 rounded-lg p-2.5 focus:ring-brand-500" placeholder="0" value={newStock} onChange={e => setNewStock(e.target.value)} />
              </div>
              <div className="md:col-span-6 flex justify-end gap-2 mt-2">
                 <button type="button" onClick={resetForm} className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg">Cancel</button>
                 <button type="submit" className="px-6 py-2 text-sm font-bold text-white bg-brand-600 hover:bg-brand-700 rounded-lg">
                     {editingId ? 'Update Item' : 'Save Item'}
                 </button>
              </div>
           </form>
        </div>
      )}

      {/* Filter */}
      <div className="relative mb-4">
        <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
        <input 
          className="w-full pl-10 pr-4 py-2.5 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-brand-500 focus:border-brand-500"
          placeholder="Search products by name..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left min-w-[800px]">
          <thead className="bg-gray-50 border-b border-gray-100">
             <tr>
               <SortHeader label="Product" sKey="name" />
               <SortHeader label="Stock" sKey="stock" align="center" />
               <SortHeader label="Cost" sKey="cost" align="right" />
               <SortHeader label="Price (Inc)" sKey="price" align="right" />
               <SortHeader label="Profit" sKey="profit" align="right" />
               <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Actions</th>
             </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
             {processedProducts.map(p => {
               const rate = (p.taxRate !== undefined && p.taxRate !== null) ? p.taxRate : 0;
               const netPrice = p.price / (1 + (rate/100));
               const profit = netPrice - p.cost;
               const margin = netPrice > 0 ? (profit / netPrice) * 100 : 0;

               return (
               <tr key={p.id} className={clsx("hover:bg-gray-50 group transition-all", p.stock <= 0 && "opacity-60 grayscale bg-gray-50/50")}>
                 <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">{p.name}</div>
                    <div className="text-xs text-gray-500">{p.category} {rate > 0 ? `• VAT ${rate}%` : ''}</div>
                 </td>
                 <td className="px-6 py-4 text-center">
                    <div className="flex items-center justify-center gap-2">
                        <button 
                            onClick={() => handleUpdateStock(p.id, p.stock, -1)}
                            className="p-1 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded"
                        >
                            <Minus size={12} />
                        </button>
                        <span className={clsx("px-2 py-1 rounded text-xs font-bold w-8 text-center", p.stock > 0 ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
                          {p.stock}
                        </span>
                        <button 
                             onClick={() => handleUpdateStock(p.id, p.stock, 1)}
                             className="p-1 text-gray-400 hover:text-green-500 hover:bg-green-50 rounded"
                        >
                            <Plus size={12} />
                        </button>
                    </div>
                 </td>
                 <td className="px-6 py-4 text-right text-sm text-gray-500">{currency(p.cost)}</td>
                 <td className="px-6 py-4 text-right text-sm font-bold text-gray-900">{currency(p.price)}</td>
                 <td className="px-6 py-4 text-right">
                    <div className="text-sm font-bold text-brand-600">{currency(profit)}</div>
                    <div className="text-[10px] text-gray-400">{margin.toFixed(0)}% margin</div>
                 </td>
                 <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => handleEdit(p)} className="text-gray-400 hover:text-brand-600 p-1.5 hover:bg-brand-50 rounded">
                           <Edit2 size={16} />
                        </button>
                        <button onClick={() => onDelete(p.id)} className="text-gray-400 hover:text-red-600 p-1.5 hover:bg-red-50 rounded">
                           <Trash2 size={16} />
                        </button>
                    </div>
                 </td>
               </tr>
             )})}
             {processedProducts.length === 0 && (
               <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-400">No products found.</td></tr>
             )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product, HistoryItem, SaleItem, Sale } from '../types';
import { ShoppingCart, Plus, Minus, Trash2, Search, FileText, Package, CreditCard, Banknote, Truck, ArrowRight, Grid } from 'lucide-react';
import clsx from 'clsx';

interface POSInterfaceProps {
  products: Product[];
  jobs: HistoryItem[];
  cart: SaleItem[];
  currency: (val: number) => string;
  onAddToCart: (item: SaleItem) => void;
  onUpdateCartQty: (index: number, delta: number) => void;
  onRemoveFromCart: (index: number) => void;
  onCheckout: (paymentMethod: Sale['paymentMethod'], shipping: number) => Promise<void>;
  onClearCart: () => void;
}

export const POSInterface: React.FC<POSInterfaceProps> = ({ 
  products, jobs, cart, currency, 
  onAddToCart, onUpdateCartQty, onRemoveFromCart, onCheckout, onClearCart
}) => {
  const [activeTab, setActiveTab] = useState<'products' | 'jobs'>('products');
  const [mobileView, setMobileView] = useState<'catalog' | 'cart'>('catalog'); // Mobile View Toggle
  const [searchTerm, setSearchTerm] = useState('');
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [shipping, setShipping] = useState<string>(''); 

  // Cart Totals
  const subtotal = cart.reduce((sum, item) => sum + (item.unitPrice * item.quantity), 0);
  const shippingCost = parseFloat(shipping) || 0;
  const cartItemCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  // Tax Total for display (optional)
  const totalTax = cart.reduce((sum, item) => {
      const rate = item.taxRate || 0;
      const netPrice = item.unitPrice / (1 + (rate/100));
      return sum + ((item.unitPrice - netPrice) * item.quantity);
  }, 0);

  const finalTotal = subtotal + shippingCost;

  // Filtering
  const filteredProducts = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));
  const filteredJobs = jobs.filter(j => j.name.toLowerCase().includes(searchTerm.toLowerCase()));

  const handleProductClick = (p: Product) => {
    // Check stock limit
    const existingItem = cart.find(i => i.refId === p.id && i.type === 'product');
    const currentQty = existingItem ? existingItem.quantity : 0;

    if (currentQty >= p.stock) {
        return; // Do nothing if stock exhausted
    }

    onAddToCart({
      type: 'product',
      refId: p.id,
      name: p.name,
      quantity: 1,
      unitPrice: p.price,
      unitCost: p.cost,
      laborCost: p.laborCost, // Pass labor cost
      energyCost: p.energyCost, // Pass energy cost
      taxRate: p.taxRate || 0
    });
  };

  const handleJobClick = (j: HistoryItem) => {
    // Attempt to extract tax rate from job inputs
    let tax = 0;
    if (j.inputs && j.inputs.taxRate) {
        tax = typeof j.inputs.taxRate === 'number' ? j.inputs.taxRate : parseFloat(j.inputs.taxRate);
    }

    // Extract Labor & Energy from snapshot if available
    const labor = j.resultsSnapshot?.unit.labor;
    // Energy cost usually includes depreciation in "machine time" context, but strictly energy is energy.
    // Let's pass the raw energy value from snapshot.
    const energy = j.resultsSnapshot?.unit.energy;

    onAddToCart({
      type: 'job',
      refId: j.id,
      name: j.name,
      quantity: typeof j.inputs.batchQty === 'string' ? parseFloat(j.inputs.batchQty) : j.inputs.batchQty,
      unitPrice: j.resultsSnapshot?.unit.finalPrice || 0,
      unitCost: j.resultsSnapshot?.unit.productionCost || 0,
      laborCost: labor,
      energyCost: energy,
      taxRate: tax
    });
  };

  const handleQtyChange = (index: number, delta: number) => {
      const item = cart[index];
      if (item.type === 'product' && delta > 0) {
          const product = products.find(p => p.id === item.refId);
          if (product && item.quantity >= product.stock) {
              return; // Limit reached
          }
      }
      onUpdateCartQty(index, delta);
  };

  const handlePayment = (method: Sale['paymentMethod']) => {
      onCheckout(method, shippingCost);
      setPaymentModalOpen(false);
      setShipping(''); // Reset shipping after checkout
      setMobileView('catalog'); // Return to catalog
  };

  return (
    <div className="flex flex-col md:flex-row h-[calc(100vh-64px)] md:h-[calc(100vh-64px)] overflow-hidden relative">

      {/* LEFT PANEL: CATALOG */}
      <div className={clsx(
          "flex-1 flex flex-col bg-gray-50 border-r border-gray-200 h-full",
          mobileView === 'cart' ? 'hidden md:flex' : 'flex'
      )}>
        {/* Search & Tabs */}
        <div className="p-4 bg-white border-b border-gray-200 shadow-sm z-10">
          <div className="flex gap-2 mb-4">
             <button 
                onClick={() => setActiveTab('products')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'products' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <Package size={16} /> Products
             </button>
             <button 
                onClick={() => setActiveTab('jobs')}
                className={`flex-1 py-2 text-sm font-bold rounded-lg flex items-center justify-center gap-2 transition-colors ${activeTab === 'jobs' ? 'bg-brand-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
             >
               <FileText size={16} /> Saved Jobs
             </button>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input 
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-brand-500"
              placeholder="Search items..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {/* Grid/List Content */}
        <div className="flex-1 overflow-y-auto p-4 pb-20 md:pb-4">
          {activeTab === 'products' ? (
             <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
               {filteredProducts.map(p => {
                 const inCart = cart.find(i => i.refId === p.id && i.type === 'product')?.quantity || 0;
                 const isOutOfStock = p.stock <= 0 || inCart >= p.stock;

                 return (
                    <div 
                        key={p.id} 
                        onClick={() => !isOutOfStock && handleProductClick(p)}
                        className={clsx(
                            "bg-white p-3 rounded-xl border border-gray-200 shadow-sm transition-all flex flex-col justify-between h-32",
                            isOutOfStock ? "opacity-50 grayscale cursor-not-allowed bg-gray-50" : "hover:border-brand-500 hover:shadow-md cursor-pointer"
                        )}
                    >
                        <div>
                        <h4 className="font-bold text-gray-800 text-sm line-clamp-2">{p.name}</h4>
                        <p className={clsx("text-xs mt-1", p.stock === 0 ? "text-red-500 font-bold" : "text-gray-500")}>
                            {p.stock === 0 ? "Out of Stock" : `${p.stock} in stock`}
                        </p>
                        </div>
                        <div className="flex justify-between items-end">
                            <div className="font-bold text-brand-600 text-lg">{currency(p.price)}</div>
                            {p.taxRate > 0 && <span className="text-[10px] text-gray-400">VAT {p.taxRate}%</span>}
                        </div>
                    </div>
                 );
               })}
             </div>
          ) : (
             <div className="space-y-2">
               {filteredJobs.map(j => (
                 <div 
                    key={j.id} 
                    onClick={() => handleJobClick(j)}
                    className="bg-white p-3 rounded-xl border border-gray-200 shadow-sm hover:border-brand-500 hover:shadow-md cursor-pointer transition-all flex justify-between items-center"
                 >
                    <div>
                      <h4 className="font-bold text-gray-800 text-sm">{j.name}</h4>
                      <p className="text-xs text-gray-500">{j.date}</p>
                    </div>
                    <div className="text-right">
                       <div className="font-bold text-brand-600">{currency(j.resultsSnapshot?.unit.finalPrice || 0)}</div>
                       <div className="text-xs text-gray-400">per unit</div>
                    </div>
                 </div>
               ))}
             </div>
          )}
        </div>

        {/* Mobile View Cart Button */}
        <div className="md:hidden absolute bottom-4 right-4 z-20">
             <button 
                onClick={() => setMobileView('cart')}
                className="bg-brand-600 text-white p-4 rounded-full shadow-lg flex items-center gap-2 relative"
             >
                 <ShoppingCart size={24} />
                 {cartItemCount > 0 && (
                     <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs font-bold w-6 h-6 rounded-full flex items-center justify-center">
                         {cartItemCount}
                     </span>
                 )}
             </button>
        </div>
      </div>

      {/* RIGHT PANEL: CART */}
      <div className={clsx(
          "w-full md:w-96 flex-col bg-white shadow-xl z-20 h-full",
          mobileView === 'cart' ? 'flex' : 'hidden md:flex'
      )}>
         <div className="p-4 bg-gray-900 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
                <button onClick={() => setMobileView('catalog')} className="md:hidden text-gray-400 hover:text-white">
                    <ArrowRight className="rotate-180" size={20} />
                </button>
                <h2 className="font-bold flex items-center gap-2"><ShoppingCart size={20} /> Current Sale</h2>
            </div>
            <button onClick={onClearCart} className="text-xs text-gray-400 hover:text-white">Clear</button>
         </div>

         <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {cart.map((item, idx) => {
                const product = item.type === 'product' ? products.find(p => p.id === item.refId) : null;
                const isMax = product ? item.quantity >= product.stock : false;

                return (
                    <div key={idx} className="flex gap-2 items-center bg-gray-50 p-2 rounded-lg border border-gray-100">
                        <div className="flex-1">
                            <h4 className="text-sm font-bold text-gray-800 line-clamp-1">{item.name}</h4>
                            <div className="flex justify-between items-center pr-2">
                                <div className="text-xs text-brand-600 font-bold">{currency(item.unitPrice)}</div>
                                {item.taxRate > 0 && <span className="text-[9px] text-gray-400">Inc {item.taxRate}% Tax</span>}
                            </div>
                        </div>
                        <div className="flex items-center gap-2 bg-white border border-gray-200 rounded px-1 shadow-sm">
                            <button onClick={() => handleQtyChange(idx, -1)} className="p-1 text-gray-500 hover:text-red-600 transition-colors"><Minus size={12}/></button>
                            <span className="text-xs font-bold w-6 text-center text-gray-800 select-none">{item.quantity}</span>
                            <button 
                                onClick={() => handleQtyChange(idx, 1)} 
                                disabled={isMax}
                                className={clsx("p-1 transition-colors", isMax ? "text-gray-300 cursor-not-allowed" : "text-gray-500 hover:text-green-600")}
                            >
                                <Plus size={12}/>
                            </button>
                        </div>
                        <button onClick={() => onRemoveFromCart(idx)} className="text-gray-400 hover:text-red-500 p-1"><Trash2 size={16} /></button>
                    </div>
                );
            })}
            {cart.length === 0 && (
              <div className="text-center py-10 text-gray-400 text-sm italic">
                Cart is empty. Select items from the catalog.
              </div>
            )}
         </div>

         <div className="p-4 border-t border-gray-200 bg-gray-50 mb-16 md:mb-0">
            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span>Subtotal (Gross)</span>
               <span>{currency(subtotal)}</span>
            </div>

            <div className="flex justify-between items-center mb-1 text-gray-500 text-xs">
               <span className="flex items-center gap-1"><Truck size={12}/> Shipping</span>
               <div className="flex items-center w-24">
                 <span className="mr-1 text-gray-400">₱</span>
                 <input 
                   type="number" 
                   min="0"
                   step="0.01"
                   className="w-full text-right border border-gray-200 rounded px-1 py-0.5 text-xs bg-white focus:ring-1 focus:ring-brand-500 focus:outline-none"
                   placeholder="0.00"
                   value={shipping}
                   onChange={e => setShipping(e.target.value)}
                 />
               </div>
            </div>

            <div className="flex justify-between items-center mb-4 text-gray-400 text-xs">
               <span>Included VAT/Tax</span>
               <span>{currency(totalTax)}</span>
            </div>

            <div className="flex justify-between items-center mb-4 border-t border-gray-100 pt-2">
               <span className="text-gray-900 font-bold text-lg">Total</span>
               <span className="text-2xl font-black text-gray-900">{currency(finalTotal)}</span>
            </div>

            <button 
              disabled={cart.length === 0}
              onClick={() => setPaymentModalOpen(true)}
              className="w-full bg-brand-600 hover:bg-brand-700 disabled:bg-gray-300 disabled:cursor-not-allowed text-white py-3 rounded-xl font-bold text-lg shadow-lg shadow-brand-500/30 transition-all"
            >
              Checkout
            </button>
         </div>
      </div>

      {/* Payment Modal */}
      {paymentModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center">
           <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-2xl animate-in fade-in zoom-in duration-200">
              <h3 className="text-lg font-bold text-gray-900 mb-4 text-center">Select Payment Method</h3>
              <div className="space-y-3">
                 <button onClick={() => handlePayment('cash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-green-500 hover:bg-green-50 font-bold text-gray-700">
                    <Banknote className="text-green-600" /> Cash
                 </button>
                 <button onClick={() => handlePayment('gcash')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 font-bold text-gray-700">
                    <span className="text-blue-600 font-black">G</span> GCash
                 </button>
                 <button onClick={() => handlePayment('card')} className="w-full flex items-center justify-center gap-3 p-4 border border-gray-200 rounded-xl hover:border-purple-500 hover:bg-purple-50 font-bold text-gray-700">
                    <CreditCard className="text-purple-600" /> Card / Other
                 </button>
              </div>
              <button onClick={() => setPaymentModalOpen(false)} className="mt-4 w-full py-2 text-gray-400 hover:text-gray-600 text-sm">Cancel</button>
           </div>
        </div>
      )}

    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Sale } from '../types';
import { Download, TrendingUp, DollarSign, Wallet, ShoppingCart, Edit2, X, Trash2, Plus, Calendar, User, Truck, Tag, Link as LinkIcon, Store, Search, ArrowUp, ArrowDown, Zap, Users } from 'lucide-react';
import clsx from 'clsx';

interface DashboardViewProps {
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => Promise<void>;
  onUpdateCapital: (id: string, updates: Partial<CapitalItem>) => Promise<void>;
  onDeleteCapital: (id: string) => void;
  onUpdateSale: (id: string, updates: Partial<Sale>) => Promise<void>;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

interface SortConfig {
    key: string;
    direction: 'asc' | 'desc';
}

export const DashboardView: React.FC<DashboardViewProps> = ({ 
  history, capitalHistory, sales,
  onDeleteJob, onAddCapital, onUpdateCapital, onDeleteCapital, onUpdateSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = React.useState<'sales' | 'expenses'>('sales');

  // Sale Edit State
  const [editingSale, setEditingSale] = useState<Sale | null>(null);

  // Sorting & Searching State
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<SortConfig>({ key: 'date', direction: 'desc' });

  // Date Filtering State
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Expense Add/Edit State
  const [isAddingExpense, setIsAddingExpense] = useState(false);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);

  const DEFAULT_EXPENSE = {
      name: '',
      category: 'Parts',
      platform: 'Shopee',
      store: '',
      purchaseDate: new Date().toISOString().split('T')[0],
      dateReceived: '',
      orderedBy: 'BB',
      paidBy: 'BB',
      receiptLink: '',
      remarks: '',
      quantity: 1,
      unitPrice: ''
  };

  const [newExpense, setNewExpense] = useState<{
      name: string;
      category: string;
      platform: string;
      store: string;
      purchaseDate: string;
      dateReceived?: string;
      orderedBy: string;
      paidBy: string;
      receiptLink?: string;
      remarks?: string;
      quantity: number | '';
      unitPrice: string;
  }>(DEFAULT_EXPENSE);

  // Calculate aggregates
  const stats = useMemo(() => {
    // 1. Sales Revenue (Realized)
    let totalSalesRev = 0;
    let totalSalesProfit = 0;
    let totalTaxCollected = 0;
    let allocatedLabor = 0;
    let allocatedEnergy = 0;

    sales.forEach(s => {
      totalSalesRev += s.totalRevenue;
      totalSalesProfit += s.totalProfit;

      // Calculate tax portion for stats
      if (s.items) {
          s.items.forEach(i => {
              const rate = i.taxRate || 0;
              const netPrice = i.unitPrice / (1 + (rate/100));
              totalTaxCollected += (i.unitPrice - netPrice) * i.quantity;

              // Labor & Energy Accumulation
              if (i.laborCost) allocatedLabor += i.laborCost * i.quantity;
              if (i.energyCost) allocatedEnergy += i.energyCost * i.quantity;
          });
      }
    });

    // 2. Potential Value (Saved Jobs)
    let potentialRev = 0;
    history.forEach(job => {
       potentialRev += job.finalPrice || 0;
    });

    // 3. Capital
    const totalCapital = capitalHistory.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalSalesProfit - totalCapital;

    return { totalSalesRev, totalSalesProfit, totalCapital, netPosition, potentialRev, totalTaxCollected, allocatedLabor, allocatedEnergy };
  }, [history, capitalHistory, sales]);

  // Handle Sort
  const handleSort = (key: string) => {
      setSortConfig(current => ({
          key,
          direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc'
      }));
  };

  // Filter and Sort Sales
  const processedSales = useMemo(() => {
      let result = [...sales];

      // 1. Search
      if (searchTerm) {
          const lower = searchTerm.toLowerCase();
          result = result.filter(s => 
              s.dateStr.toLowerCase().includes(lower) || 
              s.paymentMethod.toLowerCase().includes(lower) || 
              s.items.some(i => i.name.toLowerCase().includes(lower))
          );
      }

      // 2. Date Filter
      if (dateRange.start) {
        const startTs = new Date(dateRange.start).setHours(0,0,0,0);
        result = result.filter(s => s.timestamp >= startTs);
      }
      if (dateRange.end) {
        const endTs = new Date(dateRange.end).setHours(23,59,59,999);
        result = result.filter(s => s.timestamp <= endTs);
      }

      // 3. Sort
      result.sort((a, b) => {
          let valA: any = a[sortConfig.key as keyof Sale];
          let valB: any = b[sortConfig.key as keyof Sale];

          // Special Keys
          if (sortConfig.key === 'date') {
              valA = a.timestamp;
              valB = b.timestamp;
          }

          if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
          if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
          return 0;
      });
      return result;
  }, [sales, searchTerm, sortConfig, dateRange]);

  // Filter and Sort Expenses
  const processedExpenses = useMemo(() => {
    let result = [...capitalHistory];

    // 1. Search
    if (searchTerm) {
        const lower = searchTerm.toLowerCase();
        result = result.filter(e => 
            e.name.toLowerCase().includes(lower) ||
            e.store.toLowerCase().includes(lower) ||
            e.platform.toLowerCase().includes(lower) || 
            e.category.toLowerCase().includes(lower)
        );
    }

    // 2. Date Filter
    if (dateRange.start) {
       result = result.filter(e => e.purchaseDate >= dateRange.start);
    }
    if (dateRange.end) {
       result = result.filter(e => e.purchaseDate <= dateRange.end);
    }

    // 3. Sort
    result.sort((a, b) => {
        let valA: any = a[sortConfig.key as keyof CapitalItem];
        let valB: any = b[sortConfig.key as keyof CapitalItem];

        // Special Keys
        if (sortConfig.key === 'date') {
            valA = new Date(a.purchaseDate).getTime();
            valB = new Date(b.purchaseDate).getTime();
        }

        if (typeof valA === 'string') {
            valA = valA.toLowerCase();
            valB = valB.toLowerCase();
        }

        if (valA < valB) return sortConfig.direction === 'asc' ? -1 : 1;
        if (valA > valB) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
    });
    return result;
  }, [capitalHistory, searchTerm, sortConfig, dateRange]);


  const downloadCSV = () => {
      let content = "";
      let filename = "";

      if (activeTab === 'sales') {
        const headers = ['Date', 'Type', 'Total', 'VAT', 'Profit', 'Payment'];
        const rows = processedSales.map(s => {
            let tax = 0;
            s.items.forEach(i => {
                const rate = i.taxRate || 0;
                const net = i.unitPrice / (1 + (rate/100));
                tax += (i.unitPrice - net) * i.quantity;
            });
            return [
                s.dateStr, 
                'Sale', 
                s.totalRevenue.toFixed(2), 
                tax.toFixed(2), 
                s.totalProfit.toFixed(2), 
                s.paymentMethod
            ].join(',');
        });
        content = [headers.join(','), ...rows].join('\n');
        filename = 'sales_ledger.csv';
      } else {
        const headers = ['Purchase Date', 'Item', 'Qty', 'Category', 'Total Price', 'Store', 'Platform', 'Ordered By', 'Paid By'];
        const rows = processedExpenses.map(c => [
            c.purchaseDate, c.name, c.quantity || 1, c.category, c.price.toFixed(2), c.store, c.platform, c.orderedBy, c.paidBy
        ].join(','));
        content = [headers.join(','), ...rows].join('\n');
        filename = 'capital_expenses.csv';
      }

      const csvContent = "data:text/csv;charset=utf-8," + encodeURI(content);
      const link = document.createElement("a");
      link.setAttribute("href", csvContent);
      link.setAttribute("download", filename);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const handleSaveSaleEdit = async () => {
      if (!editingSale) return;
      const newProfit = editingSale.totalRevenue - editingSale.totalCost; // Simplified logic, assumes cost doesn't change
      await onUpdateSale(editingSale.id, {
          dateStr: editingSale.dateStr,
          paymentMethod: editingSale.paymentMethod,
          totalRevenue: editingSale.totalRevenue,
          totalProfit: newProfit
      });
      setEditingSale(null);
  };

  const handleEditExpense = (item: CapitalItem) => {
      setNewExpense({
          name: item.name,
          category: item.category,
          platform: item.platform || '',
          store: item.store || '',
          purchaseDate: item.purchaseDate,
          dateReceived: item.dateReceived || '',
          orderedBy: item.orderedBy || 'BB',
          paidBy: item.paidBy || 'BB',
          receiptLink: item.receiptLink || '',
          remarks: item.remarks || '',
          quantity: item.quantity || 1,
          unitPrice: item.quantity > 0 ? (item.price / item.quantity).toFixed(2) : item.price.toFixed(2)
      });
      setEditingExpenseId(item.id);
      setIsAddingExpense(true);
  };

  const closeExpenseModal = () => {
      setIsAddingExpense(false);
      setEditingExpenseId(null);
      setNewExpense(DEFAULT_EXPENSE);
  };

  const handleSaveExpense = async (e: React.FormEvent) => {
      e.preventDefault();

      const qty = Number(newExpense.quantity) || 1;
      const unit = parseFloat(newExpense.unitPrice) || 0;
      const total = unit * qty;

      if (!newExpense.name || total <= 0) {
          alert("Please enter a valid Name and Price.");
          return;
      }

      const expenseData = {
          name: newExpense.name,
          price: total,
          quantity: qty,
          category: newExpense.category as any,
          platform: newExpense.platform || '',
          store: newExpense.store || '',
          purchaseDate: newExpense.purchaseDate || new Date().toLocaleDateString(),
          dateReceived: newExpense.dateReceived || null,
          orderedBy: newExpense.orderedBy || 'BB',
          paidBy: newExpense.paidBy || 'BB',
          receiptLink: newExpense.receiptLink || null,
          remarks: newExpense.remarks || null,
      };

      try {
        if (editingExpenseId) {
            await onUpdateCapital(editingExpenseId, expenseData);
        } else {
            await onAddCapital({
                ...expenseData,
                createdAt: Date.now()
            });
        }
        closeExpenseModal();
      } catch (err) {
        alert("Failed to save expense. Please try again.");
        console.error(err);
      }
  };

  const SortHeader = ({ label, sKey, align = 'left' }: { label: string, sKey: string, align?: string }) => (
      <th 
        className={`px-6 py-3 text-xs font-bold text-gray-500 uppercase cursor-pointer hover:text-brand-600 hover:bg-gray-100 transition-colors text-${align}`}
        onClick={() => handleSort(sKey)}
      >
          <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : 'justify-start'}`}>
            {label}
            {sortConfig.key === sKey && (
                sortConfig.direction === 'asc' ? <ArrowUp size={12}/> : <ArrowDown size={12}/>
            )}
          </div>
      </th>
  );

  return (
    <div className="flex flex-col h-full bg-gray-50 overflow-hidden relative mb-16 md:mb-0">

        {/* Stats Overview */}
        <div className="flex-none p-6">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                <StatsCard 
                    icon={<DollarSign size={20} />} 
                    label="Realized Revenue" 
                    value={currency(stats.totalSalesRev)} 
                    subValue={`${currency(stats.totalTaxCollected)} VAT included`}
                    color="text-blue-600" bg="bg-blue-50" 
                />
                <StatsCard 
                    icon={<TrendingUp size={20} />} 
                    label="Net Profit" 
                    value={currency(stats.totalSalesProfit)} 
                    color="text-green-600" bg="bg-green-50" 
                />
                <StatsCard 
                    icon={<ShoppingCart size={20} />} 
                    label="Capital Expenses" 
                    value={currency(stats.totalCapital)} 
                    color="text-orange-600" bg="bg-orange-50" 
                />
                <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex items-center gap-3">
                    <div className={clsx("p-2 rounded-lg", stats.netPosition >= 0 ? "bg-brand-50 text-brand-600" : "bg-red-50 text-red-600")}>
                        <Wallet size={20} />
                    </div>
                    <div>
                        <p className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Net Position</p>
                        <p className={clsx("text-xl font-bold", stats.netPosition >= 0 ? "text-brand-600" : "text-red-600")}>
                        {stats.netPosition < 0 ? '-' : '+'}{currency(Math.abs(stats.netPosition))}
                        </p>
                    </div>
                </div>
            </div>

            {/* New Stats Row for Labor/Energy Allocation */}
            <div className="grid grid-cols-2 gap-4">
                <div className="bg-purple-50 p-3 rounded-xl border border-purple-100 flex items-center gap-3">
                   <div className="p-2 bg-white rounded-lg text-purple-600 shadow-sm"><Users size={16} /></div>
                   <div>
                      <p className="text-[10px] font-bold text-purple-800 uppercase">Allocated Labor</p>
                      <p className="text-lg font-bold text-purple-900">{currency(stats.allocatedLabor)}</p>
                   </div>
                </div>
                <div className="bg-yellow-50 p-3 rounded-xl border border-yellow-100 flex items-center gap-3">
                   <div className="p-2 bg-white rounded-lg text-yellow-600 shadow-sm"><Zap size={16} /></div>
                   <div>
                      <p className="text-[10px] font-bold text-yellow-800 uppercase">Electricity Cost</p>
                      <p className="text-lg font-bold text-yellow-900">{currency(stats.allocatedEnergy)}</p>
                   </div>
                </div>
            </div>
        </div>

        {/* Tab Navigation */}
        <div className="px-6 border-b border-gray-200 bg-white flex flex-col md:flex-row md:items-center justify-between flex-none gap-4 pb-0 pt-4 md:py-0">
          <div className="flex gap-6">
            <TabButton active={activeTab === 'sales'} onClick={() => { setActiveTab('sales'); setSearchTerm(''); }} label="Sales Ledger" />
            <TabButton active={activeTab === 'expenses'} onClick={() => { setActiveTab('expenses'); setSearchTerm(''); }} label="Capital Expenses" />
          </div>

          <div className="flex items-center gap-3 pb-3 md:pb-0">
             {/* Date Filters */}
             <div className="flex items-center gap-2 bg-white border border-gray-300 rounded-lg p-1.5 shadow-sm">
                <input 
                    type="date" 
                    className="text-xs text-gray-700 border-none focus:ring-0 p-0 bg-transparent w-auto font-medium"
                    value={dateRange.start}
                    onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))}
                />
                <span className="text-gray-400 text-xs px-1">to</span>
                <input 
                    type="date" 
                    className="text-xs text-gray-700 border-none focus:ring-0 p-0 bg-transparent w-auto font-medium"
                    value={dateRange.end}
                    onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))}
                />
                {(dateRange.start || dateRange.end) && (
                    <button 
                        onClick={() => setDateRange({ start: '', end: '' })}
                        className="p-1 hover:bg-gray-100 rounded-full text-gray-400 hover:text-gray-600 transition-colors ml-1"
                    >
                        <X size={12} />
                    </button>
