                        <FileText size={20} className="text-gray-400 group-hover:text-brand-500" />
                        <span className="text-[10px] text-gray-400">{j.date}</span>
                    </div>
                    <div className="font-bold text-gray-900 line-clamp-2 mb-1">{j.name}</div>
                    <div className="mt-auto text-brand-600 font-bold">{currency(j.finalPrice)}</div>
