                        className="w-20 text-right text-xs p-1 border border-gray-300 rounded bg-white"
                        value={shippingCost}
                        onChange={e => setShippingCost(e.target.value)}
                        placeholder="0"
                     />
                 </div>
                 <div className="flex justify-between text-lg font-black text-brand-600 pt-2 border-t border-gray-200">
                     <span>Total</span>
                     <span>{currency(finalTotal)}</span>
                 </div>
             </div>

             <div className="grid grid-cols-2 gap-2">
                 <button 
                    className={clsx("py-2 text-xs font-bold rounded border", paymentMethod === 'cash' ? "bg-green-50 text-green-700 border-green-200" : "bg-white text-gray-500 border-gray-200")}
                    onClick={() => setPaymentMethod('cash')}
                 >
                     CASH
                 </button>
                 <button 
                    className={clsx("py-2 text-xs font-bold rounded border", paymentMethod === 'gcash' ? "bg-blue-50 text-blue-700 border-blue-200" : "bg-white text-gray-500 border-gray-200")}
                    onClick={() => setPaymentMethod('gcash')}
                 >
                     GCASH
                 </button>
             </div>

             <button 
                 onClick={handleCheckoutSubmit}
                 disabled={cart.length === 0 || isCheckingOut}
                 className="w-full py-3 bg-brand-600 hover:bg-brand-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-xl shadow-lg shadow-brand-500/30 transition-all flex justify-center items-center gap-2"
             >
                 {isCheckingOut ? 'Processing...' : `Charge ${currency(finalTotal)}`}
             </button>
         </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem } from '../types';
import { InputGroup } from './InputGroup';
import { HistoryPanel } from './HistoryPanel';
import { SummaryChart } from './SummaryChart';
import { Save, PlusCircle, Trash2, FileUp, Menu, Zap, Clock, Weight, DollarSign, Box } from 'lucide-react';
import clsx from 'clsx';

interface CalculatorViewProps {
  inputs: CalculatorInputs;
  setInputs: React.Dispatch<React.SetStateAction<CalculatorInputs>>;
  results: CalculatedResults;
  history: HistoryItem[];
  editingJobId: string | null;
  isSaving: boolean;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (v: boolean) => void;
  onLoadJob: (job: HistoryItem) => void;
  onEditJob: (job: HistoryItem) => void;
  onDeleteJob: (id: string) => void;
  onSaveJob: (asCopy: boolean) => Promise<void>;
  onCancel: () => void;
  onShowMath: () => void;
  onShowDashboard: () => void;
  onAddToInventory: () => void;
  handleFile: (file: File) => void;
  isParsing: boolean;
  currency: (val: number) => string;
  onToggleJobStatus: (job: HistoryItem) => void;
}

export const CalculatorView: React.FC<CalculatorViewProps> = ({
  inputs, setInputs, results, history, editingJobId, isSaving, 
  isSidebarOpen, setIsSidebarOpen, onLoadJob, onEditJob, onDeleteJob, 
  onSaveJob, onCancel, onShowMath, onAddToInventory, handleFile, isParsing, currency, onToggleJobStatus
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [priceInputValue, setPriceInputValue] = useState('');
  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [activeTab, setActiveTab] = useState<'basic' | 'advanced' | 'commercial'>('basic');

  // Input Helper
  const setIn = (field: keyof CalculatorInputs, value: any) => {
    setInputs(prev => ({ ...prev, [field]: value }));
  };

  // --- File Drop Handlers ---
  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const onFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  // --- Reverse Calculation Handler ---
  const handlePriceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setPriceInputValue(val);

    const numericVal = parseFloat(val);
    if (isNaN(numericVal) || numericVal < 0) return;

    // 1. Determine Target Unit Price (Gross)
    const qty = typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1;
    const grossPrice = viewMode === 'unit' ? numericVal : numericVal / qty;

    // 2. Op Cost
    const opCost = results.unit.productionCost + results.unit.packaging;
    if (opCost <= 0) return;

    // 3. Calculate Deductions (Tax + Fees)
    const useFees = inputs.usePlatformFees !== false;
    const comm = useFees ? (typeof inputs.platformCommissionFee === 'number' ? inputs.platformCommissionFee : parseFloat(inputs.platformCommissionFee as string) || 0) : 0;
    const svc = useFees ? (typeof inputs.platformServiceFee === 'number' ? inputs.platformServiceFee : parseFloat(inputs.platformServiceFee as string) || 0) : 0;
    const trans = useFees ? (typeof inputs.platformTransactionFee === 'number' ? inputs.platformTransactionFee : parseFloat(inputs.platformTransactionFee as string) || 0) : 0;
    const fixed = useFees ? (typeof inputs.platformFixedFee === 'number' ? inputs.platformFixedFee : parseFloat(inputs.platformFixedFee as string) || 0) : 0;

    const taxRate = typeof inputs.taxRate === 'number' ? inputs.taxRate : parseFloat(inputs.taxRate as string) || 0;

    // Tax Amount = P - P/(1+rate)
    const taxAmount = grossPrice - (grossPrice / (1 + (taxRate/100)));

    // Fees
    const feeAmount = (grossPrice * (comm/100)) + 
                      (grossPrice * (svc/100)) + 
                      ((grossPrice + results.unit.shipping) * (trans/100)) + 
                      fixed;

    // Net Received (Wallet) before Cost
    const netReceived = grossPrice - taxAmount - feeAmount;

    // Implied Profit
    const impliedProfit = netReceived - opCost;
    const newMarkup = (impliedProfit / opCost) * 100;

    setInputs(prev => ({
        ...prev,
        markup: parseFloat(newMarkup.toFixed(6))
    }));
  };

  const handleManualMarkupChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      setIn('markup', e.target.value);
      setPriceInputValue(''); // Clear manual price override visual when markup changes
  };

  const currentResult = viewMode === 'unit' ? results.unit : results.batch;

  // Use displayed price if manually typing, else calculated
  const displayPrice = priceInputValue && document.activeElement?.id === 'finalPriceInput'
      ? priceInputValue
      : currentResult.finalPrice.toFixed(2);

  return (
    <div className="flex h-full overflow-hidden bg-gray-50">
      {/* Sidebar */}
      <div 
        className={clsx(
            "fixed inset-y-0 left-0 z-30 w-64 bg-white border-r border-gray-200 transform transition-transform duration-300 ease-in-out md:relative md:translate-x-0 flex flex-col",
            isSidebarOpen ? "translate-x-0" : "-translate-x-full md:hidden"
        )}
      >
        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
           <h3 className="font-bold text-gray-700">Recent Jobs</h3>
           <button onClick={() => setIsSidebarOpen(false)} className="md:hidden text-gray-400">
               <Menu size={20} />
           </button>
        </div>
        <div className="flex-1 overflow-hidden">
            <HistoryPanel 
                items={history}
                onLoad={onLoadJob}
                onEdit={onEditJob}
                onDelete={onDeleteJob}
                onToggleStatus={onToggleJobStatus}
            />
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative" 
           onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}>

        {/* Mobile Toggle */}
        {!isSidebarOpen && (
            <button 
                onClick={() => setIsSidebarOpen(true)}
                className="absolute left-4 top-4 z-20 p-2 bg-white rounded-lg shadow-md md:hidden text-gray-600"
            >
                <Menu size={20} />
            </button>
        )}

        {/* Drag Overlay */}
        {dragActive && (
            <div className="absolute inset-0 z-50 bg-brand-500/10 backdrop-blur-sm flex items-center justify-center border-4 border-dashed border-brand-500 rounded-xl m-4">
                <div className="text-brand-600 font-bold text-xl flex flex-col items-center animate-bounce">
                    <FileUp size={48} />
                    <span className="mt-4">Drop G-Code / 3MF file here</span>
                </div>
            </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-32">
            <div className="max-w-5xl mx-auto space-y-6">

                {/* Header Section */}
                <div className="flex flex-col md:flex-row gap-4 md:items-start justify-between">
                    <div className="flex-1 space-y-4">
                        <div className="flex gap-2">
                             <input 
                                className="flex-1 text-2xl font-bold bg-transparent border-0 border-b-2 border-gray-200 focus:border-brand-500 focus:ring-0 px-0 py-1 placeholder-gray-300 transition-colors"
                                placeholder="Job Name"
                                value={inputs.jobName}
                                onChange={e => setIn('jobName', e.target.value)}
                             />
                             <div className="w-24">
                                <InputGroup 
                                    label=""
                                    type="number"
                                    value={inputs.batchQty}
                                    onChange={e => setIn('batchQty', e.target.value)}
                                    prefix="Qty"
                                    className="!mt-0"
                                />
                             </div>
                        </div>
                        <input 
                            className="w-full text-sm text-gray-500 bg-transparent border-0 border-b border-gray-100 focus:border-gray-300 focus:ring-0 px-0 py-1 placeholder-gray-300"
                            placeholder="Add notes..."
                            value={inputs.notes || ''}
                            onChange={e => setIn('notes', e.target.value)}
                        />
                    </div>

                    <div className="flex gap-2 self-start md:self-center">
                        <div className="relative">
                            <input 
                                type="file" 
                                id="gcode-upload" 
                                className="hidden" 
                                onChange={onFileInput}
                                accept=".gcode,.3mf,.txt" 
                            />
                            <label 
                                htmlFor="gcode-upload" 
                                className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 text-gray-600 rounded-lg hover:border-brand-500 hover:text-brand-600 transition-colors shadow-sm text-sm font-bold"
                            >
                                {isParsing ? <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin"/> : <FileUp size={16} />}
                                <span>Import File</span>
                            </label>
                        </div>
                    </div>
                </div>

                {/* Tabs */}
                <div className="flex border-b border-gray-200">
                    <button onClick={() => setActiveTab('basic')} className={clsx("px-6 py-3 text-sm font-bold border-b-2 transition-colors", activeTab === 'basic' ? "border-brand-500 text-brand-600" : "border-transparent text-gray-500 hover:text-gray-700")}>Production</button>
                    <button onClick={() => setActiveTab('commercial')} className={clsx("px-6 py-3 text-sm font-bold border-b-2 transition-colors", activeTab === 'commercial' ? "border-brand-500 text-brand-600" : "border-transparent text-gray-500 hover:text-gray-700")}>Commercial</button>
                    <button onClick={() => setActiveTab('advanced')} className={clsx("px-6 py-3 text-sm font-bold border-b-2 transition-colors", activeTab === 'advanced' ? "border-brand-500 text-brand-600" : "border-transparent text-gray-500 hover:text-gray-700")}>Settings</button>
                </div>

                {/* Content */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

                    {/* Form Area */}
                    <div className="lg:col-span-2 space-y-6">

                        {activeTab === 'basic' && (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-6 gap-y-4 animate-in fade-in slide-in-from-left-4">
                                {/* Material */}
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm md:col-span-2">
                                    <h4 className="flex items-center gap-2 text-sm font-bold text-gray-800 mb-4">
                                        <Box size={16} className="text-blue-500" /> Material
                                    </h4>
                                    <div className="grid grid-cols-2 gap-4">
                                        <InputGroup label="Filament Cost" prefix="₱" suffix="/kg" value={inputs.materialCost} onChange={e => setIn('materialCost', e.target.value)} />
                                        <InputGroup label="Weight Used" suffix="g" value={inputs.materialGrams} onChange={e => setIn('materialGrams', e.target.value)} />
                                    </div>
                                </div>

                                {/* Time */}
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="flex items-center gap-2 text-sm font-bold text-gray-800 mb-4">
                                        <Clock size={16} className="text-purple-500" /> Print Time
                                    </h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        <InputGroup label="Hours" value={inputs.timeHours} onChange={e => setIn('timeHours', e.target.value)} />
                                        <InputGroup label="Minutes" value={inputs.timeMinutes} onChange={e => setIn('timeMinutes', e.target.value)} />
                                    </div>
                                </div>

                                {/* Labor */}
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="flex items-center gap-2 text-sm font-bold text-gray-800 mb-4">
                                        <Zap size={16} className="text-yellow-500" /> Labor
                                    </h4>
                                    <div className="grid grid-cols-2 gap-2">
                                        <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={e => setIn('laborMins', e.target.value)} />
                                        <InputGroup label="Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={e => setIn('laborRate', e.target.value)} />
                                    </div>
                                </div>

                                {/* Extras */}
                                <div className="md:col-span-2 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                     <div className="flex justify-between items-center mb-2">
                                        <h4 className="flex items-center gap-2 text-sm font-bold text-gray-800">
                                            <PlusCircle size={16} className="text-gray-500" /> Extra Hardware
                                        </h4>
                                        <button 
                                            onClick={() => setIn('extras', [...inputs.extras, { id: Date.now().toString(), name: '', price: 0 }])}
                                            className="text-xs text-brand-600 hover:text-brand-700 font-bold"
                                        >
                                            + Add Item
                                        </button>
                                     </div>
                                     <div className="space-y-2">
                                         {inputs.extras.map((extra, idx) => (
                                             <div key={extra.id} className="flex gap-2 items-center">
                                                 <input 
                                                    className="flex-1 text-xs border-gray-200 rounded" 
                                                    placeholder="Item name"
                                                    value={extra.name}
                                                    onChange={e => {
                                                        const newExtras = [...inputs.extras];
                                                        newExtras[idx].name = e.target.value;
                                                        setIn('extras', newExtras);
                                                    }}
                                                 />
                                                 <input 
                                                    className="w-24 text-xs border-gray-200 rounded" 
                                                    placeholder="Price"
                                                    type="number"
                                                    value={extra.price}
                                                    onChange={e => {
                                                        const newExtras = [...inputs.extras];
                                                        newExtras[idx].price = e.target.value;
                                                        setIn('extras', newExtras);
                                                    }}
                                                 />
                                                 <button 
                                                    onClick={() => {
                                                        const newExtras = inputs.extras.filter((_, i) => i !== idx);
                                                        setIn('extras', newExtras);
                                                    }}
                                                    className="text-gray-400 hover:text-red-500"
                                                 >
                                                     <Trash2 size={14} />
                                                 </button>
                                             </div>
                                         ))}
                                         {inputs.extras.length === 0 && <p className="text-xs text-gray-400 italic">No extra items.</p>}
                                     </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'commercial' && (
                            <div className="space-y-4 animate-in fade-in slide-in-from-left-4">
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="text-sm font-bold text-gray-800 mb-4">Pricing Strategy</h4>
                                    <div className="grid grid-cols-2 gap-4">
                                        <InputGroup label="Markup" suffix="%" value={inputs.markup} onChange={handleManualMarkupChange} />
                                        <InputGroup label="VAT Rate" suffix="%" value={inputs.taxRate} onChange={e => setIn('taxRate', e.target.value)} />
                                    </div>

                                    <div className="mt-4 pt-4 border-t border-gray-100">
                                        <label className="flex items-center gap-2 mb-4 cursor-pointer">
                                            <input 
                                                type="checkbox" 
                                                checked={inputs.usePlatformFees !== false}
                                                onChange={e => setIn('usePlatformFees', e.target.checked)}
                                                className="rounded text-brand-600 focus:ring-brand-500"
                                            />
                                            <span className="text-sm font-bold text-gray-700">Include Shopee Fees</span>
                                        </label>

                                        {inputs.usePlatformFees !== false && (
                                            <div className="grid grid-cols-2 gap-3 pl-6 border-l-2 border-brand-100">
                                                <InputGroup label="Commission" suffix="%" value={inputs.platformCommissionFee} onChange={e => setIn('platformCommissionFee', e.target.value)} />
                                                <InputGroup label="Transaction" suffix="%" value={inputs.platformTransactionFee} onChange={e => setIn('platformTransactionFee', e.target.value)} />
                                                <InputGroup label="Service" suffix="%" value={inputs.platformServiceFee} onChange={e => setIn('platformServiceFee', e.target.value)} />
                                                <InputGroup label="Fixed Fee" prefix="₱" value={inputs.platformFixedFee} onChange={e => setIn('platformFixedFee', e.target.value)} />
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="text-sm font-bold text-gray-800 mb-4">Logistics</h4>
                                    <div className="grid grid-cols-2 gap-4">
                                        <InputGroup label="Packaging" prefix="₱" value={inputs.packagingCost} onChange={e => setIn('packagingCost', e.target.value)} />
                                        <InputGroup label="Shipping Cost" prefix="₱" value={inputs.shippingCost} onChange={e => setIn('shippingCost', e.target.value)} hint="Pass-through cost" />
                                    </div>
                                </div>
                            </div>
                        )}

                        {activeTab === 'advanced' && (
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in slide-in-from-left-4">
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="text-sm font-bold text-gray-800 mb-4">Machine Depreciation</h4>
                                    <div className="space-y-3">
                                        <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={e => setIn('machineCost', e.target.value)} />
                                        <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={e => setIn('lifespanHours', e.target.value)} />
                                    </div>
                                </div>
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="text-sm font-bold text-gray-800 mb-4">Energy Settings</h4>
                                    <div className="space-y-3">
                                        <InputGroup label="Electricity Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={e => setIn('elecRate', e.target.value)} />
                                        <InputGroup label="Printer Power" suffix="Watts" value={inputs.powerWatts} onChange={e => setIn('powerWatts', e.target.value)} />
                                        <InputGroup label="Dryer Power" suffix="Watts" value={inputs.dryerPowerWatts} onChange={e => setIn('dryerPowerWatts', e.target.value)} />
                                    </div>
                                </div>
                                <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
                                    <h4 className="text-sm font-bold text-gray-800 mb-4">Margins</h4>
                                    <InputGroup label="Wastage Multiplier" value={inputs.wastageMultiplier} onChange={e => setIn('wastageMultiplier', e.target.value)} hint="1.05 = 5% waste" />
                                    <InputGroup label="Failure Risk" suffix="%" value={inputs.failMargin} onChange={e => setIn('failMargin', e.target.value)} className="mt-3" />
                                </div>
                             </div>
                        )}
                    </div>

                    {/* Results Area */}
                    <div className="lg:col-span-1">
                        <div className="sticky top-4 space-y-4">
                            {/* Summary Card */}
                            <div className="bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">
                                <div className="p-6 bg-brand-600 text-white relative">
                                    <div className="flex justify-between items-center mb-2">
                                        <span className="text-brand-100 text-xs font-bold uppercase tracking-wider">Suggested Price</span>
                                        <div className="flex bg-brand-700 rounded-lg p-0.5">
                                            <button onClick={() => setViewMode('unit')} className={clsx("px-2 py-0.5 text-[10px] font-bold rounded-md transition-colors", viewMode === 'unit' ? "bg-white text-brand-600" : "text-brand-100")}>Unit</button>
                                            <button onClick={() => setViewMode('batch')} className={clsx("px-2 py-0.5 text-[10px] font-bold rounded-md transition-colors", viewMode === 'batch' ? "bg-white text-brand-600" : "text-brand-100")}>Batch</button>
                                        </div>
                                    </div>
                                    <div className="flex items-baseline gap-1">
                                        <span className="text-2xl font-medium opacity-80">₱</span>
                                        <input 
                                            id="finalPriceInput"
                                            className="text-5xl font-black bg-transparent border-0 border-b-2 border-brand-400 focus:border-white focus:ring-0 px-0 py-0 w-full placeholder-brand-300 text-white"
                                            value={displayPrice}
                                            onChange={handlePriceChange}
                                        />
                                    </div>
                                    <p className="text-brand-100 text-xs mt-2 opacity-80">
                                        Profit: {currency(currentResult.profit)} ({((currentResult.profit / currentResult.finalPrice) * 100 || 0).toFixed(0)}%)
                                    </p>
                                </div>

                                <div className="p-6">
                                    <SummaryChart data={currentResult} currency={currency} />

                                    <div className="mt-6 space-y-3">
                                        <Row label="Material Cost" val={currentResult.material} />
                                        <Row label="Labor & Prep" val={currentResult.labor} />
                                        <Row label="Machine & Energy" val={currentResult.energy + currentResult.depreciation} />
                                        <Row label="Overhead & Risk" val={currentResult.failureRisk + currentResult.extras} />
                                        <div className="border-t border-gray-100 my-2"></div>
                                        <Row label="Platform Fees" val={currentResult.platformFeeAmount} className="text-orange-600" />
                                        <Row label="Tax (VAT)" val={currentResult.tax} className="text-orange-600" />
                                    </div>

                                    <button 
                                        onClick={onShowMath}
                                        className="w-full mt-6 py-2 text-xs font-bold text-gray-500 hover:text-brand-600 hover:bg-gray-50 rounded-lg transition-colors border border-gray-200"
                                    >
                                        Show Math
                                    </button>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="grid grid-cols-2 gap-3">
                                <button 
                                    onClick={() => onSaveJob(false)}
                                    disabled={isSaving}
                                    className="flex items-center justify-center gap-2 py-3 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold rounded-xl shadow-sm transition-all"
                                >
                                    {isSaving ? "Saving..." : editingJobId ? "Update Job" : "Save Job"}
                                </button>
                                {editingJobId && (
                                    <button 
                                        onClick={() => onSaveJob(true)}
                                        className="flex items-center justify-center gap-2 py-3 bg-white border border-gray-200 hover:border-brand-500 text-gray-700 hover:text-brand-600 font-bold rounded-xl shadow-sm transition-all"
                                    >
                                        Save Copy
                                    </button>
                                )}
                                <button 
                                    onClick={onAddToInventory}
                                    className="col-span-2 flex items-center justify-center gap-2 py-3 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl shadow-lg shadow-brand-500/20 transition-all"
                                >
                                    <Box size={18} />
                                    Add to Inventory
                                </button>
                                {editingJobId && (
                                     <button 
                                        onClick={onCancel}
                                        className="col-span-2 text-xs text-gray-400 hover:text-gray-600"
                                     >
                                         Cancel Editing
                                     </button>
                                )}
                            </div>

                        </div>
                    </div>
                </div>

            </div>
        </div>
      </div>
    </div>
  );
};

const Row = ({ label, val, className }: any) => (
    <div className={clsx("flex justify-between text-sm", className || "text-gray-600")}>
        <span>{label}</span>
        <span className="font-bold">₱{val.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
    </div>
);
